// Hyperbeast: a four-dimensional squid drifting through a cosmic abyss.
// Tentacles are 4D curves rotated in xw/zw/yw and sliced by our 3D space:
// a tube's thickness is its cross-section at the slice, so it swells and thins to a thread.
const NT: i32 = 6;
const NK: i32 = 7;
// xyz = point on the tentacle, w = tube radius at the slice
var<private> PP: array<vec4f, 42>;
var<private> TB: array<vec4f, 6>;
var<private> BODY: vec3f;
var<private> JET: f32;

fn rot4(q0: vec4f, ma: mat2x2<f32>, mb: mat2x2<f32>, mc: mat2x2<f32>) -> vec4f {
    var q = q0;
    let xw = ma * vec2f(q.x, q.w);
    q = vec4f(xw.x, q.y, q.z, xw.y);
    let zw = mb * vec2f(q.z, q.w);
    q = vec4f(q.x, q.y, zw.x, zw.y);
    let yw = mc * vec2f(q.y, q.w);
    return vec4f(q.x, yw.x, q.z, yw.y);
}

fn body_setup(t: f32) {
    let ph = fract(t * 0.28);
    JET = exp(-ph * 7.0);
    let rise = smoothstep(0.0, 0.3, ph) * (1.0 - ph);
    BODY = vec3f(0.45 * sin(t * 0.13), 1.9 + 0.6 * rise, 0.45 * cos(t * 0.11));
}

fn tent_setup(t: f32) {
    let ma = rot2(t * 0.21);
    let mb = rot2(0.8 * sin(t * 0.15));
    let mc = rot2(0.3 * sin(t * 0.09 + 1.0));
    for (var i = 0; i < NT; i = i + 1) {
        let fi = f32(i);
        let a0 = fi * TAU / f32(NT) + 0.25 * sin(t * 0.4 + fi);
        var cen = vec3f(0.0);
        for (var k = 0; k < NK; k = k + 1) {
            let s = f32(k) / f32(NK - 1);
            let wv = t * 1.1 - s * 5.0 + fi * 1.3;
            let spread = (0.2 + 0.85 * s) * (1.0 - 0.35 * JET);
            let ang = a0 + 0.9 * s * sin(wv);
            var q = vec4f(spread * cos(ang), -0.2 - 1.5 * s, spread * sin(ang), 0.0);
            let lp = s * 5.0 + t * 0.7 + fi * 2.1;
            let cl = cos(lp);
            let sl = sin(lp);
            q += vec4f(cl, 0.5 * sin(lp * 0.7), sl, sin(lp + fi)) * (0.34 * s);
            q.w += 0.8 * s * sin(s * 3.0 + t * 0.4 + fi * 1.9);
            q = rot4(q, ma, mb, mc);
            let sc = 1.0 / (1.0 - 0.1 * clamp(q.w, -1.5, 1.5));
            let pp = BODY + q.xyz * sc;
            let slice = sqrt(max(1.0 - q.w * q.w / 2.0, 0.0));
            PP[i * NK + k] = vec4f(pp, (0.13 - 0.09 * s) * slice + 0.012);
            cen += pp;
        }
        cen = cen / f32(NK);
        var r = 0.0;
        for (var k = 0; k < NK; k = k + 1) {
            let v = PP[i * NK + k];
            r = max(r, length(v.xyz - cen) + v.w);
        }
        TB[i] = vec4f(cen, r + 0.2);
    }
}

fn sph(ro: vec3f, rd: vec3f, c: vec3f, r: f32) -> vec2f {
    let oc = ro - c;
    let b = dot(oc, rd);
    let h = b * b - (dot(oc, oc) - r * r);
    if (h < 0.0) { return vec2f(1e9, -1e9); }
    let s = sqrt(h);
    return vec2f(-b - s, -b + s);
}

fn abyss(rd: vec3f, t: f32, bdir: vec3f) -> vec3f {
    let y = rd.y;
    var c = mix(vec3f(0.006, 0.008, 0.03), vec3f(0.02, 0.09, 0.14), smoothstep(-0.5, 0.9, y));
    let h = noise3(rd * 2.2 + vec3f(t * 0.015, t * 0.01, 0.0)) * 0.62 + noise3(rd * 4.7 - vec3f(0.0, t * 0.02, 3.1)) * 0.38;
    c += vec3f(0.10, 0.04, 0.22) * smoothstep(0.45, 0.78, h);
    c += vec3f(0.0, 0.07, 0.09) * smoothstep(0.58, 0.88, h);
    let a = atan2(rd.x, rd.z);
    let shaft = 0.5 + 0.5 * sin(a * 9.0 + t * 0.15 + 2.0 * sin(a * 3.0 - t * 0.1));
    c += vec3f(0.03, 0.16, 0.2) * pow(max(y, 0.0), 2.0) * shaft * 0.6;
    let hs = hash13(floor(rd * 140.0));
    let tw = 0.5 + 0.5 * sin(t * 2.0 + hs * 60.0);
    c += mix(vec3f(0.4, 0.9, 1.0), vec3f(1.0, 0.4, 0.9), fract(hs * 13.0)) * step(0.9965, hs) * tw * 0.8;
    let aura = max(dot(rd, bdir), 0.0);
    c += vec3f(0.18, 0.08, 0.4) * pow(aura, 12.0) * 0.5 + vec3f(0.05, 0.25, 0.3) * pow(aura, 40.0) * 0.4;
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let t = time();
    body_setup(t);
    var acc = vec3f(0.0);
    var T = 1.0;
    var thit = 1e9;
    let outer = sph(ro, rd, BODY, 3.25);
    if (outer.x < outer.y && outer.y > tmin) {
        tent_setup(t);
        var TI: array<vec2f, 6>;
        var t0 = 1e9;
        var t1 = -1e9;
        for (var j = 0; j < NT; j = j + 1) {
            let s = sph(ro, rd, TB[j].xyz, TB[j].w);
            TI[j] = s;
            if (s.x < s.y) { t0 = min(t0, s.x); t1 = max(t1, s.y); }
        }
        let bs0 = sph(ro, rd, BODY + vec3f(0.0, 0.6, 0.0), 1.1);
        if (bs0.x < bs0.y) { t0 = min(t0, bs0.x); t1 = max(t1, bs0.y); }
        t0 = max(t0, tmin);
        t1 = min(t1, tmax);
        if (t0 < t1) {
            let steps = i32(mix(24.0, 52.0, quality()));
            var tt = t0 + hash12(rd.xy * 731.0 + vec2f(rd.z * 17.0, 3.0)) * 0.04;
            let sq = 1.0 - 0.14 * JET;
            let jetb = 2.0 * JET;
            for (var i = 0; i < steps; i = i + 1) {
                if (tt > t1 || T < 0.04) { break; }
                let p = ro + rd * tt;
                let bp = p - BODY;
                let yy = (bp.y - 0.6) / 0.9;
                let rxz = 0.48 * sq * (1.0 - 0.35 * clamp(yy, 0.0, 1.0));
                let db = (length(vec3f(bp.x / rxz, yy, bp.z / rxz)) - 1.0) * rxz;
                var dmin = abs(db);
                var e = vec3f(0.0);
                var dens = 0.0;
                if (db < 0.25) {
                    let bins = 1.0 - smoothstep(-0.03, 0.03, db);
                    let bsh = exp(-abs(db) * 14.0);
                    let spots = smoothstep(0.6, 0.95, 0.5 + 0.5 * sin(bp.x * 11.0 + t * 0.9) * sin(bp.y * 9.0 - t * 1.3) * sin(bp.z * 11.0 + t * 0.7));
                    var bc = mix(vec3f(0.16, 0.12, 0.7), vec3f(0.1, 0.55, 0.75), smoothstep(-0.4, 1.4, bp.y));
                    bc += vec3f(1.0, 0.2, 0.75) * spots * 1.5;
                    bc *= 1.0 + jetb * exp(-max(bp.y + 0.3, 0.0) * 2.0);
                    e += bc * (bins * 0.5 + bsh * 3.6);
                    dens += bins * 0.8;
                }
                for (var j = 0; j < NT; j = j + 1) {
                    let iv = TI[j];
                    if (tt < iv.x || tt > iv.y) {
                        if (tt < iv.x) { dmin = min(dmin, iv.x - tt + 0.02); }
                        continue;
                    }
                    var bd = 1e3;
                    var bsv = 0.0;
                    var bth = 1.0;
                    for (var k = 0; k < NK - 1; k = k + 1) {
                        let ia = j * NK + k;
                        let A = PP[ia];
                        let B = PP[ia + 1];
                        let ba = B.xyz - A.xyz;
                        let pa = p - A.xyz;
                        let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
                        let rr = mix(A.w, B.w, h);
                        let d = length(pa - ba * h) - rr;
                        if (d < bd) {
                            bd = d;
                            bsv = (f32(k) + h) / f32(NK - 1);
                            bth = (rr - 0.012) / max(0.13 - 0.09 * bsv, 0.01);
                        }
                    }
                    dmin = min(dmin, abs(bd));
                    if (bd < 0.35) {
                        let ins = 1.0 - smoothstep(-0.015, 0.015, bd);
                        let sh = exp(-abs(bd) * 20.0);
                        let halo = 0.0015 / (0.003 + bd * bd);
                        let pulse = pow(0.5 + 0.5 * cos(TAU * (bsv * 2.2 + t * 0.75 + f32(j) * 0.37)), 8.0);
                        let base = mix(vec3f(0.42, 0.25, 1.0), vec3f(0.05, 0.75, 0.8), smoothstep(0.2, 0.9, bth));
                        let c = base * 0.7 + vec3f(1.0, 0.18, 0.7) * (pulse * 2.5 + jetb * exp(-bsv * 4.0));
                        e += c * (ins * 4.0 + sh * 5.5 + halo * 2.0);
                        dens += ins * 3.0;
                    }
                }
                let dt = clamp(dmin * 0.8, 0.04, 0.35);
                acc += T * e * dt;
                if (dens > 0.5 && thit > 1e8) { thit = tt; }
                T *= exp(-dens * dt);
                tt += dt;
            }
        }
    }
    let bdir = normalize(BODY + vec3f(0.0, 0.3, 0.0) - ro);
    var col = acc + T * abyss(rd, t, bdir);
    // a few dim drifting eyes that blink
    for (var i = 0; i < 3; i = i + 1) {
        let fi = f32(i);
        let a = t * 0.23 + fi * 2.09 + 0.5 * sin(t * 0.31 + fi);
        let ep = BODY + vec3f(0.6 * cos(a), 0.1 + 0.3 * sin(t * 0.27 + fi * 1.7), 0.6 * sin(a));
        let tc = dot(ep - ro, rd);
        if (tc > tmin) {
            let d = length(ro + rd * tc - ep);
            let open = smoothstep(0.01, 0.07, abs(fract(t * 0.11 + fi * 0.37) - 0.5));
            let r = 0.055 + 0.025 * sin(t * 0.5 + fi * 2.0);
            let g = (1.0 - smoothstep(r * 0.4, r, d)) * 1.4 + 0.003 / (d * d + 0.003) * 0.3;
            let vis = select(T, 1.0, tc < thit);
            col += vec3f(0.6, 0.92, 1.0) * g * open * vis * 0.7;
        }
    }
    // rising bubbles
    for (var i = 0; i < 14; i = i + 1) {
        let fi = f32(i);
        let h = hash33(vec3f(fi * 1.7, 3.7, 1.3));
        let ang = h.x * TAU;
        let rad = 0.9 + h.y * 3.0;
        let y = fract(t * (0.07 + 0.06 * h.z) + h.y * 3.1) * 4.8 - 0.2;
        let c = vec3f(cos(ang) * rad + 0.08 * sin(t * 1.7 + fi), y, sin(ang) * rad + 0.08 * cos(t * 1.3 + fi));
        let r = 0.03 + 0.05 * h.z;
        let tc = dot(c - ro, rd);
        if (tc > tmin && tc < tmax) {
            let d = length(ro + rd * tc - c);
            if (d < r * 1.5) {
                let x = (d - r * 0.85) / (r * 0.22);
                let ring = exp(-x * x) + 0.15 * (1.0 - smoothstep(0.0, r, d));
                let vis = select(T, 1.0, tc < thit);
                col += vec3f(0.45, 0.85, 1.0) * ring * 0.35 * vis;
            }
        }
    }
    let tout = select(horizon_t(tmax), clamp(thit, tmin, tmax), thit < 1e8);
    return Hit(tone(col * 1.15), tout);
}

// Self Portrait in Four Panes: the Room World bot paints itself on a stack of floating glass layers.
const LAMP = vec3f(0.95, 1.52, 0.5);
const PANEC = vec3f(0.2, 1.75, -0.35);
const HEADC = vec3f(-0.45, 1.53, 0.71);
const SR = vec3f(-0.3, 1.3, 0.73);
const SL = vec3f(-0.6, 1.3, 0.75);
const ELL = vec3f(-0.74, 1.02, 0.74);
const HANDL = vec3f(-0.62, 1.06, 0.57);
const PALC = vec3f(-0.62, 1.09, 0.44);

var<private> MAT: i32;
var<private> MHIT: bool;
var<private> T: f32;
var<private> TIP: vec3f;
var<private> HAND: vec3f;
var<private> ELB: vec3f;
var<private> LD: vec3f;
var<private> LP: vec3f;
var<private> HYAW: f32;
var<private> HROLL: f32;
var<private> FIN: vec4f;
var<private> FOUT: vec4f;
var<private> DABS: array<vec3f, 6> = array<vec3f, 6>(
    vec3f(0.1, 0.25, 0.9), vec3f(1.0, 0.55, 0.12), vec3f(0.95, 0.3, 0.25),
    vec3f(0.92, 0.9, 0.85), vec3f(0.1, 0.6, 0.6), vec3f(0.6, 0.05, 0.12));

fn init() {
    T = time();
    TIP = vec3f(0.06 + 0.13 * sin(T * 0.8), 1.72 + 0.09 * sin(T * 1.6 + 1.0), 0.035 + 0.03 * (0.5 + 0.5 * sin(T * 1.6)));
    HAND = TIP + vec3f(-0.09, -0.12, 0.2);
    ELB = mix(SR, HAND, 0.5) + vec3f(0.1, -0.2, 0.06);
    LD = normalize(vec3f(-0.45, 0.9, 0.5) - LAMP);
    LP = LAMP + LD * 0.06;
    HYAW = 0.35 + 0.18 * sin(T * 0.31);
    HROLL = 0.13 * sin(T * 0.45);
    let c = fract(T / 18.0) * 18.0;
    let fo = clamp((c - 14.5) / 3.0, 0.0, 1.0) * 1.05;
    FIN = vec4f(1.05, clamp(c / 3.5, 0.0, 1.0) * 1.05, clamp((c - 4.0) / 3.5, 0.0, 1.0) * 1.05, clamp((c - 8.0) / 3.5, 0.0, 1.0) * 1.05);
    FOUT = vec4f(0.0, fo, fo, fo);
}

fn cap(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}
fn bnd(p: vec3f, mn: vec3f, mx: vec3f) -> f32 { return sd_box(p - (mn + mx) * 0.5, (mx - mn) * 0.5); }
fn sd2box(p: vec2f, b: vec2f) -> f32 {
    let q = abs(p) - b;
    return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0);
}
fn seg2(p: vec2f, a: vec2f, b: vec2f) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}
fn sd_round_cone(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
    let ba = b - a;
    let l2 = dot(ba, ba);
    let rr = r1 - r2;
    let a2 = l2 - rr * rr;
    let il2 = 1.0 / l2;
    let pa = p - a;
    let y = dot(pa, ba);
    let z = y - l2;
    let xv = pa * l2 - ba * y;
    let x2 = dot(xv, xv);
    let y2 = y * y * l2;
    let z2 = z * z * l2;
    let k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) { return sqrt(x2 + z2) * il2 - r2; }
    if (sign(y) * a2 * y2 < k) { return sqrt(x2 + y2) * il2 - r1; }
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

fn map(p: vec3f) -> f32 {
    var d = 1e5;
    let b1 = bnd(p, vec3f(-0.92, 0.0, -0.02), vec3f(0.3, 1.85, 1.1));
    if (b1 > 0.08) { d = b1; } else {
        var g = max(length(p.xz - vec2f(-0.45, 0.8)) - 0.2, abs(p.y - 0.64) - 0.022) - 0.01;
        if (g < d) { d = g; MAT = 3; }
        for (var k = 0; k < 3; k = k + 1) {
            let a = f32(k) * 2.094 + 0.6;
            let dir = vec3f(cos(a), 0.0, sin(a));
            g = cap(p, vec3f(-0.45, 0.62, 0.8) + dir * 0.12, vec3f(-0.45, 0.0, 0.8) + dir * 0.25, 0.018);
            if (g < d) { d = g; MAT = 3; }
        }
        g = sd_box(p - vec3f(-0.45, 0.76, 0.79), vec3f(0.08, 0.035, 0.06)) - 0.04;
        let tor = smin(cap(p, vec3f(-0.45, 0.82, 0.79), vec3f(-0.45, 1.16, 0.76), 0.06),
                       sd_box(p - vec3f(-0.45, 1.17, 0.75), vec3f(0.09, 0.06, 0.045)) - 0.04, 0.06);
        g = min(g, tor);
        g = min(g, cap(p, SL, SR, 0.035));
        g = min(g, min(min(cap(p, SR, ELB, 0.03), cap(p, ELB, HAND, 0.026)), length(p - HAND) - 0.034));
        g = min(g, min(min(cap(p, SL, ELL, 0.03), cap(p, ELL, HANDL, 0.026)), length(p - HANDL) - 0.034));
        if (g < d) { d = g; MAT = 1; }
        g = min(length(p - vec3f(-0.45, 1.16, 0.665)) - 0.028, min(length(p - ELB) - 0.04, length(p - ELL) - 0.04));
        if (g < d) { d = g; MAT = 2; }
        g = cap(p, vec3f(-0.45, 1.28, 0.75), vec3f(-0.45, 1.44, 0.72), 0.022);
        if (g < d) { d = g; MAT = 8; }
        var q = p - HEADC;
        let xz = rot2(HYAW) * q.xz;
        q = vec3f(xz.x, q.y, xz.y);
        let xy = rot2(HROLL) * q.xy;
        q = vec3f(xy.x, xy.y, q.z);
        g = sd_box(q, vec3f(0.08, 0.06, 0.07)) - 0.04;
        if (g < d) { d = g; MAT = select(1, 7, q.z < -0.085 && abs(q.y) < 0.028 && abs(q.x) < 0.09); }
        g = cap(q, vec3f(0.03, 0.09, 0.0), vec3f(0.07, 0.24, 0.02), 0.006);
        if (g < d) { d = g; MAT = 8; }
        g = length(q - vec3f(0.07, 0.25, 0.02)) - 0.02;
        if (g < d) { d = g; MAT = 2; }
        for (var s = 0; s < 2; s = s + 1) {
            let sx = select(-1.0, 1.0, s == 1);
            let hip = vec3f(-0.45 + sx * 0.075, 0.76, 0.78);
            let knee = vec3f(-0.45 + sx * 0.11, 0.73, 0.44);
            let foot = vec3f(-0.45 + sx * 0.12, 0.1, 0.41);
            g = min(cap(p, hip, knee, 0.042), cap(p, knee, foot, 0.035));
            g = min(g, sd_box(p - vec3f(foot.x, 0.035, 0.37), vec3f(0.035, 0.03, 0.07)) - 0.01);
            if (g < d) { d = g; MAT = 1; }
            g = length(p - knee) - 0.045;
            if (g < d) { d = g; MAT = 2; }
        }
        g = cap(p, HAND, TIP, 0.007);
        if (g < d) { d = g; MAT = 5; }
        g = cap(p, mix(HAND, TIP, 0.8), TIP, 0.011);
        if (g < d) { d = g; MAT = 2; }
        let q2 = p - PALC;
        g = (max(length(q2.xz * vec2f(1.0, 1.25)) - 0.17, abs(q2.y) - 0.006) - 0.004) * 0.85;
        if (g < d) { d = g; MAT = 4; }
    }
    let b2 = bnd(p, vec3f(-0.45, 0.0, -1.75), vec3f(0.85, 2.85, -0.7));
    if (b2 > 0.08) { d = min(d, b2); } else {
        var g = cap(p, vec3f(-0.32, 0.0, -0.82), vec3f(0.14, 2.75, -0.98), 0.03);
        g = min(g, cap(p, vec3f(0.72, 0.0, -0.82), vec3f(0.26, 2.75, -0.98), 0.03));
        g = min(g, cap(p, vec3f(0.2, 0.0, -1.68), vec3f(0.2, 2.6, -1.02), 0.026));
        g = min(g, sd_box(p - vec3f(0.2, 1.08, -0.8), vec3f(0.5, 0.02, 0.07)) - 0.005);
        g = min(g, sd_box(p - vec3f(0.2, 2.5, -0.97), vec3f(0.12, 0.05, 0.03)));
        if (g < d) { d = g; MAT = 3; }
    }
    let b3 = bnd(p, vec3f(0.82, 0.0, 0.12), vec3f(1.48, 1.62, 0.85));
    if (b3 > 0.08) { d = min(d, b3); } else {
        var g = sd_box(p - vec3f(1.15, 0.74, 0.48), vec3f(0.28, 0.02, 0.26)) - 0.005;
        var q = p - vec3f(1.15, 0.36, 0.48);
        q = vec3f(abs(q.x) - 0.24, q.y, abs(q.z) - 0.22);
        g = min(g, sd_box(q, vec3f(0.018, 0.36, 0.018)));
        if (g < d) { d = g; MAT = 3; }
        g = max(length(p.xz - vec2f(1.3, 0.32)) - 0.065, abs(p.y - 0.855) - 0.09) - 0.005;
        if (g < d) { d = g; MAT = 6; }
        for (var k = 0; k < 3; k = k + 1) {
            let fk = f32(k);
            let tp = vec3f(1.3 + (fk - 1.0) * 0.09, 1.1 + fk * 0.035, 0.32 + (fk - 1.0) * 0.04);
            g = cap(p, vec3f(1.3, 0.85, 0.32), tp, 0.007);
            if (g < d) { d = g; MAT = 5; }
        }
        g = max(length(p.xz - vec2f(1.02, 0.65)) - 0.08, abs(p.y - 0.775) - 0.012) - 0.004;
        g = min(g, cap(p, vec3f(1.02, 0.78, 0.65), vec3f(1.08, 1.3, 0.62), 0.012));
        g = min(g, cap(p, vec3f(1.08, 1.3, 0.62), LAMP - LD * 0.1, 0.01));
        g = min(g, sd_round_cone(p, LAMP - LD * 0.1, LAMP, 0.025, 0.06));
        if (g < d) { d = g; MAT = 8; }
        g = length(p - (LAMP + LD * 0.02)) - 0.035;
        if (g < d) { d = g; MAT = 7; }
    }
    return d;
}

fn calc_normal(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn soft_sh(p: vec3f, n: vec3f) -> f32 {
    let lv = LP - p;
    let dist = length(lv);
    let l = lv / dist;
    let o = p + n * 0.01;
    var res = 1.0;
    var t = 0.02;
    let steps = i32(mix(8.0, 16.0, quality()));
    for (var i = 0; i < 16; i = i + 1) {
        if (i >= steps) { break; }
        let h = map(o + l * t);
        res = min(res, 10.0 * h / t);
        t += clamp(h, 0.02, 0.3);
        if (res < 0.02 || t > dist - 0.09) { break; }
    }
    return clamp(res, 0.0, 1.0);
}

fn lightp(p: vec3f, n: vec3f, rd: vec3f, base: vec3f, gloss: f32, sh: f32) -> vec3f {
    let lv = LP - p;
    let dl = length(lv);
    let l = lv / dl;
    let spot = mix(0.05, 1.0, smoothstep(0.78, 0.93, dot(-l, LD)));
    let att = 4.0 / (1.0 + dl * dl * 0.6);
    let warm = vec3f(1.0, 0.62, 0.3) * att * spot * sh;
    let dif = max(dot(n, l), 0.0);
    let pv = PANEC - p;
    let dp = length(pv);
    let pl = pv / dp;
    let cob = vec3f(0.22, 0.42, 1.0) * max(dot(n, pl) * 0.6 + 0.4, 0.0) * 1.1 / (1.0 + dp * dp);
    let amb = vec3f(0.045, 0.04, 0.055) * (0.7 + 0.3 * n.y);
    let hv = normalize(l - rd);
    let sp = pow(max(dot(n, hv), 0.0), mix(12.0, 80.0, gloss)) * gloss;
    let hp = normalize(pl - rd);
    let sp2 = pow(max(dot(n, hp), 0.0), 40.0) * gloss;
    return base * (amb + cob + warm * dif) + warm * sp * 0.8 + vec3f(0.3, 0.5, 1.0) * sp2 * 0.4 / (1.0 + dp * dp);
}

fn surface(ro: vec3f, rd: vec3f, tmin: f32, tend: f32, steps: i32, allow_m: bool, do_sh: bool) -> vec4f {
    var ts = tend - 0.002;
    var kind = 0;
    let tf = plane_y(ro, rd, 0.0);
    if (tf > tmin && tf < ts) { ts = tf; kind = 1; }
    let sp = box_span(ro, rd, vec3f(-0.95, 0.0, -1.8), vec3f(1.52, 2.9, 1.15));
    if (sp.x < sp.y && sp.y > tmin) {
        var t = max(sp.x, tmin);
        let te = min(sp.y, ts);
        for (var i = 0; i < 80; i = i + 1) {
            if (i >= steps || t > te) { break; }
            let d = map(ro + rd * t);
            if (d < 0.0005 + 0.0007 * t) { ts = t; kind = 2; break; }
            t += d * 0.9;
        }
    }
    let p = ro + rd * ts;
    var col = vec3f(0.0);
    if (kind == 2) {
        let m = MAT;
        let n = calc_normal(p);
        var base = vec3f(0.7);
        var gloss = 0.2;
        var emit = vec3f(0.0);
        let fres = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
        if (m == 1) {
            base = vec3f(0.74, 0.77, 0.84);
            gloss = 0.75;
            emit = vec3f(0.25, 0.5, 1.0) * fres * 0.55;
        } else if (m == 2) {
            base = vec3f(0.1);
            emit = vec3f(0.35, 0.65, 1.0) * (2.0 + 0.7 * sin(T * 2.2 + p.y * 9.0));
        } else if (m == 3) {
            base = vec3f(0.3, 0.17, 0.09) * (0.7 + 0.6 * noise3(p * vec3f(9.0, 50.0, 9.0)));
            gloss = 0.25;
        } else if (m == 4) {
            let q = p - PALC;
            base = vec3f(0.5, 0.36, 0.22);
            gloss = 0.3;
            for (var k = 0; k < 6; k = k + 1) {
                let a = f32(k) * 0.95 + 0.3;
                let cc = vec2f(cos(a), sin(a) * 0.8) * 0.11;
                let dd = length(q.xz - cc) - 0.024 - 0.008 * noise3(vec3f(q.xz * 60.0, f32(k)));
                if (dd < 0.0 && n.y > 0.3) { base = DABS[k]; gloss = 1.0; emit = DABS[k] * 0.25; }
            }
        } else if (m == 5) {
            base = vec3f(0.4, 0.08, 0.05);
            gloss = 0.6;
            if (p.x > 0.8) {
                let bi = i32(clamp(round((p.x - 1.3) / 0.09) + 1.0, 0.0, 2.0));
                if (p.y > 1.04 + f32(bi) * 0.035) { base = DABS[bi * 2]; gloss = 0.9; }
            }
        } else if (m == 6) {
            base = select(vec3f(0.1, 0.13, 0.16), vec3f(0.16, 0.2, 0.32), p.y < 0.88);
            gloss = 1.0;
            emit = vec3f(0.3, 0.5, 0.9) * fres * 0.4;
        } else if (m == 7) {
            base = vec3f(0.0);
            emit = vec3f(1.0, 0.65, 0.32) * 3.5;
        } else {
            base = vec3f(0.4, 0.28, 0.14);
            gloss = 0.85;
        }
        let lv = normalize(LP - p);
        var sh = 1.0;
        if (do_sh && dot(n, lv) > 0.0 && dot(-lv, LD) > 0.74) { sh = soft_sh(p, n); }
        let ao = clamp(map(p + n * 0.1) / 0.1, 0.35, 1.0);
        col = lightp(p, n, rd, base, gloss, sh) * (0.4 + 0.6 * ao) + emit;
    } else if (kind == 1) {
        let bi = floor(p.z / 0.2);
        let along = p.x + hash12(vec2f(bi, 4.0)) * 6.0;
        let jx = abs(fract(p.z / 0.2) - 0.5);
        let jz = abs(fract(along / 1.8) - 0.5);
        var base = vec3f(0.16, 0.1, 0.06) * (0.7 + 0.5 * hash12(vec2f(bi, floor(along / 1.8)))) * (0.8 + 0.35 * noise3(vec3f(p.x * 2.0, 0.0, p.z * 30.0)));
        base *= 1.0 - 0.5 * max(smoothstep(0.46, 0.49, jx), smoothstep(0.493, 0.499, jz));
        let cell = floor(p.xz * 5.0);
        let hh = hash12(cell + 17.0);
        let ctr = (cell + 0.5 + (hash33(vec3f(cell, 2.0)).xy - 0.5) * 0.6) / 5.0;
        let nearz = length(p.xz - vec2f(0.0, -0.1)) < 1.8;
        if (nearz && hh > 0.86 && length(p.xz - ctr) < 0.015 + 0.03 * fract(hh * 37.0)) { base = DABS[i32(fract(hh * 91.0) * 5.99)] * 0.8; }
        let up = vec3f(0.0, 1.0, 0.0);
        let lv = normalize(LP - p);
        var sh = 1.0;
        if (do_sh && dot(-lv, LD) > 0.74) { sh = soft_sh(p, up); }
        let ao = clamp(map(p + vec3f(0.0, 0.25, 0.0)) / 0.25, 0.3, 1.0);
        col = lightp(p, up, rd, base, 0.35, sh) * ao;
    } else {
        var n = vec3f(0.0, -1.0, 0.0);
        if (p.y < 4.45) {
            if (abs(p.x) > abs(p.z)) { n = vec3f(-sign(p.x), 0.0, 0.0); } else { n = vec3f(0.0, 0.0, -sign(p.z)); }
        }
        let w = select(p.x, p.z, abs(n.x) > 0.5);
        var base = vec3f(0.2, 0.15, 0.12) * (0.75 + 0.4 * noise3(p * 1.5 + 3.0));
        if (p.y < 1.0) {
            let pan = abs(fract(w / 0.6) - 0.5);
            base = vec3f(0.11, 0.07, 0.045) * (0.8 + 0.3 * noise3(vec3f(w * 10.0, p.y * 2.0, 1.0))) * (1.0 - 0.4 * smoothstep(0.46, 0.49, pan));
        }
        if (abs(p.y - 1.0) < 0.03) { base = vec3f(0.25, 0.16, 0.09); }
        if (n.y < -0.5) { base = vec3f(0.06, 0.05, 0.05); }
        var gloss = 0.05;
        if (allow_m && n.z > 0.5 && p.x > 1.2 && p.x < 3.3 && p.y > 0.45 && p.y < 3.5) {
            let ex = min(min(p.x - 1.2, 3.3 - p.x), min(p.y - 0.45, 3.5 - p.y));
            if (ex < 0.1) { base = vec3f(0.55, 0.38, 0.13) * (0.7 + 0.5 * noise3(p * 25.0)); gloss = 0.9; } else { MHIT = true; }
        }
        col = lightp(p, n, rd, base, gloss, 1.0) + base * vec3f(0.35, 0.26, 0.2) * 0.5;
    }
    return vec4f(col, ts);
}

fn pane_paint(i: i32, u: f32, v: f32) -> vec4f {
    let fi = f32(i);
    let br = noise3(vec3f(u * 7.0, v * 45.0, fi * 5.0 + 1.0));
    let hd = sd2box(vec2f(u, v - 0.1), vec2f(0.11, 0.09)) - 0.045;
    let shd = (length(vec2f(u / 0.34, (v + 0.55) / 0.24)) - 1.0) * 0.24;
    let nk = sd2box(vec2f(u, v + 0.16), vec2f(0.03, 0.12));
    let body = min(min(hd, shd), nk);
    var col = vec3f(0.0);
    var a = 0.0;
    var order = 0.0;
    if (i == 0) {
        col = mix(vec3f(0.02, 0.06, 0.3), vec3f(0.05, 0.26, 0.42), clamp((v + 0.6) / 1.2, 0.0, 1.0)) * (0.55 + 0.9 * br);
        col += vec3f(1.0, 0.55, 0.22) * 0.5 * exp(-length(vec2f(u, v - 0.1)) * 6.0);
        a = 0.5;
    } else if (i == 1) {
        let lit = 0.75 + 0.45 * clamp(0.5 - u + v, 0.0, 1.0);
        col = vec3f(0.5, 0.62, 0.92) * (0.6 + 0.5 * br) * lit;
        a = 0.72 * smoothstep(0.004, -0.004, body);
        order = clamp((0.6 - v) / 1.2, 0.0, 1.0);
    } else if (i == 2) {
        let visor = sd2box(vec2f(u, v - 0.1), vec2f(0.095, 0.022)) - 0.01;
        let tipd = length(vec2f(u - 0.09, v - 0.43)) - 0.024;
        let warmf = min(visor, tipd);
        let core = length(vec2f(u, v + 0.45)) - 0.045;
        let ant = seg2(vec2f(u, v), vec2f(0.05, 0.22), vec2f(0.09, 0.42)) - 0.006;
        let seam = abs(shd + 0.06) - 0.004;
        let pale = min(ant, max(seam, v + 0.33));
        if (warmf < 0.0) { col = vec3f(1.0, 0.6, 0.25) * 1.6 * (0.8 + 0.4 * br); a = 0.92; }
        else if (core < 0.0) { col = vec3f(0.4, 0.75, 1.0) * 1.8; a = 0.9; }
        else if (pale < 0.0) { col = vec3f(0.7, 0.85, 1.0); a = 0.8; }
        order = clamp((u + 0.45) / 0.9, 0.0, 1.0);
    } else {
        let ln = abs(body) - 0.005 * (0.6 + 0.9 * br);
        a = 0.95 * smoothstep(0.002, -0.002, ln);
        col = vec3f(0.85, 0.95, 1.0) * 1.3;
        let hl = min(length(vec2f(u + 0.08, v - 0.17)) - 0.018, length(vec2f(u + 0.2, v + 0.4)) - 0.02);
        if (hl < 0.0) { a = 0.9; col = vec3f(1.0, 0.95, 0.85) * 1.5; }
        order = fract(atan2(v, u) / TAU + 0.5);
    }
    let fin = FIN[i];
    let fout = FOUT[i];
    let vis = clamp((fin - order) * 25.0, 0.0, 1.0) * clamp((order - fout) * 25.0 + 1.0, 0.0, 1.0);
    let fresh = exp(-abs(fin - order) * 40.0) * step(fin, 1.0);
    return vec4f(col * (1.0 + 1.5 * fresh), a * vis);
}

fn layer_col(i: i32) -> vec3f {
    if (i == 0) { return vec3f(0.2, 0.45, 1.0); }
    if (i == 1) { return vec3f(0.6, 0.75, 1.0); }
    if (i == 2) { return vec3f(1.0, 0.6, 0.25); }
    return vec3f(0.9, 0.95, 1.0);
}

fn effects(ro: vec3f, rd: vec3f, tmin: f32, ts: f32, col: vec3f, beam: bool) -> vec3f {
    var c = col;
    if (beam) {
        let cb = LP + LD;
        let oc = ro - cb;
        let b = dot(oc, rd);
        let cc = dot(oc, oc) - 1.21;
        let disc = b * b - cc;
        if (disc > 0.0) {
            let sq = sqrt(disc);
            let t0 = max(-b - sq, tmin);
            let t1 = min(-b + sq, ts);
            if (t1 > t0) {
                let dt = (t1 - t0) / 8.0;
                let j = hash13(rd * 431.0);
                var acc = 0.0;
                for (var i = 0; i < 8; i = i + 1) {
                    let s = ro + rd * (t0 + (f32(i) + j) * dt);
                    let v = s - LP;
                    let dl = length(v);
                    let ca = dot(v, LD) / max(dl, 0.001);
                    acc += smoothstep(0.82, 0.95, ca) / (1.0 + dl * dl * 1.2);
                }
                c += vec3f(1.0, 0.6, 0.28) * acc * dt * 0.09;
            }
        }
    }
    for (var k = 0; k < 4; k = k + 1) {
        let i = select(3 - k, k, rd.z < 0.0);
        let fi = f32(i);
        if (abs(rd.z) < 0.0001) { continue; }
        let zc = -0.75 + 0.25 * fi;
        let tz = (zc - ro.z) / rd.z;
        if (tz < tmin || tz > ts) { continue; }
        let p = ro + rd * tz;
        let u = p.x - 0.2;
        let v = p.y - 1.75 - 0.015 * sin(T * 0.6 + fi * 1.7);
        if (abs(u) > 0.45 || abs(v) > 0.6) { continue; }
        let pp = pane_paint(i, u, v);
        c = mix(c, pp.rgb * 1.3, pp.a);
        c = c * 0.95 + vec3f(0.02, 0.04, 0.1);
        let e = min(0.45 - abs(u), 0.6 - abs(v));
        c += vec3f(0.3, 0.55, 1.0) * exp(-e * 150.0) * 0.9;
    }
    for (var i = 0; i < 28; i = i + 1) {
        let fi = f32(i);
        let h = hash33(vec3f(fi, 3.7, 11.0));
        let layer = i % 4;
        let zc = -0.75 + 0.25 * f32(layer);
        let home = vec3f(0.2 + (h.x - 0.5) * 0.8, 1.75 + (h.y - 0.5) * 1.05, zc);
        let ph = fract(T * 0.06 + h.z);
        let s = smoothstep(0.0, 0.45, ph) * (1.0 - smoothstep(0.55, 1.0, ph));
        let drift = vec3f((h.x - 0.5) * 0.9 + 0.25 * sin(T * 0.7 + fi), 0.25 + h.y * 0.55, (h.z - 0.4) * 0.9 + 0.2 * cos(T * 0.5 + fi * 1.3));
        let P = home + drift * s;
        let w = P - ro;
        let tp = dot(w, rd);
        if (tp < tmin || tp > ts) { continue; }
        let d2 = max(dot(w, w) - tp * tp, 0.0);
        let g = 1.3 * exp(-d2 * 6000.0) + 0.22 * exp(-d2 * 300.0);
        c += layer_col(layer) * g * (0.35 + 0.9 * s);
    }
    if (beam) {
        let b1 = normalize(cross(LD, vec3f(0.0, 1.0, 0.0)));
        let b2 = cross(LD, b1);
        for (var i = 0; i < 22; i = i + 1) {
            let fi = f32(i);
            let h = hash33(vec3f(fi, 9.1, 2.3));
            let f = fract(h.x + T * 0.012);
            let along = 0.3 + f * 1.6;
            let ang = h.y * TAU + T * 0.07 * (h.z - 0.5);
            let rad = along * 0.42 * sqrt(h.z);
            let P = LP + LD * along + (b1 * cos(ang) + b2 * sin(ang)) * rad + vec3f(0.0, 0.03 * sin(T * 0.5 + fi * 2.0), 0.0);
            let w = P - ro;
            let tp = dot(w, rd);
            if (tp < tmin || tp > ts) { continue; }
            let d2 = max(dot(w, w) - tp * tp, 0.0);
            let tw = (0.6 + 0.4 * sin(T * 1.7 + fi * 3.1)) * smoothstep(0.0, 0.1, f) * smoothstep(1.0, 0.9, f);
            c += vec3f(1.0, 0.75, 0.45) * (0.9 * exp(-d2 * 30000.0) + 0.06 * exp(-d2 * 2000.0)) * tw / (1.0 + along * along * 0.5);
        }
    }
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    init();
    MHIT = false;
    let q = quality();
    let s = surface(ro, rd, tmin, tmax, i32(mix(40.0, 80.0, q)), true, true);
    var col = s.xyz;
    if (MHIT) {
        let p = ro + rd * s.w;
        let mn = normalize(vec3f(-0.1, 0.0, 1.0));
        let rr = reflect(rd, mn);
        let ex = box_span(p, rr, vec3f(-6.0, 0.0, -6.0), vec3f(6.0, 4.5, 6.0)).y;
        let s2 = surface(p, rr, 0.01, max(ex, 0.05), i32(mix(24.0, 56.0, q)), false, false);
        let c2 = effects(p, rr, 0.01, s2.w, s2.xyz, false);
        let smudge = noise3(p * vec3f(3.0, 3.0, 1.0));
        col = c2 * vec3f(0.8, 0.84, 0.88) + vec3f(0.02, 0.025, 0.03) * smudge;
    }
    col = effects(ro, rd, tmin, s.w, col, true);
    return Hit(tone(col * 1.1), s.w);
}

// Self-portrait of the Room World bot: a quiet studio where a glass easel holds a half-built wall of tiny rooms.
const IVORY: vec3f = vec3f(0.95, 0.90, 0.80);
const GRAPH: vec3f = vec3f(0.10, 0.10, 0.11);
const TEAL: vec3f = vec3f(0.10, 0.85, 0.78);
const SUN: vec3f = vec3f(1.0, 0.85, 0.64);
const HALO_C: vec3f = vec3f(0.0, 3.2, 0.0);
const NCUBE: i32 = 70;
const K0: i32 = 28;
const STEP: f32 = 0.45;
const CYC: f32 = 24.0;

struct Cube { c: vec3f, h: f32, flash: f32, home: f32 };
struct Op { t: f32, col: vec3f };

fn ldir() -> vec3f { return normalize(vec3f(-0.1, 0.35, -1.0)); }

fn win_mask(w: vec2f) -> f32 {
    let m = smoothstep(-1.75, -1.7, w.x) * (1.0 - smoothstep(0.5, 0.55, w.x)) * smoothstep(2.85, 2.9, w.y) * (1.0 - smoothstep(4.3, 4.35, w.y));
    let bar = min(abs(w.x + 0.6), abs(w.y - 3.6));
    return m * smoothstep(0.025, 0.045, bar);
}

fn in_beam(p: vec3f) -> f32 {
    let L = ldir();
    let s = (-6.0 - p.z) / L.z;
    let w = p + L * s;
    return win_mask(w.xy) * step(0.0, s);
}

fn pulse(lt: f32) -> f32 {
    let x = lt - 1.2;
    let endp = f32(NCUBE - 1 - K0) * STEP + 0.6;
    if (x < 0.0 || x > endp) { return 0.0; }
    let age = fract(x / STEP) * STEP;
    return exp(-age * 7.0);
}

fn cube(k: i32, t: f32) -> Cube {
    let col = f32(k % 10);
    let row = f32(k / 10);
    let home = vec3f(-0.9 + 0.2 * col, 0.95 + 0.2 * row, 0.06);
    if (k < K0) { return Cube(home, 0.075, 0.0, 1.0); }
    let a = 1.2 + f32(k - K0) * STEP;
    let f = clamp((t - a + 1.2) / 1.2, 0.0, 1.0);
    let endt = 1.2 + f32(NCUBE - 1 - K0) * STEP + 1.0;
    let st = endt + f32(NCUBE - 1 - k) / f32(NCUBE - K0) * 2.0;
    let shrink = 1.0 - clamp((t - st) / 0.6, 0.0, 1.0);
    let e = 1.0 - pow(1.0 - f, 3.0);
    let hh = select(0.0, 0.075 * shrink * smoothstep(0.0, 0.25, f), f > 0.0);
    let off = vec3f(0.35 * sin(f32(k) * 2.3), 1.1, 0.9) * (1.0 - e);
    let age = t - a;
    let fl = select(0.0, exp(-age * 2.5), age > 0.0) * shrink;
    return Cube(home + off, hh, fl, step(1.0, f));
}

fn bnorm(p: vec3f, c: vec3f, h: vec3f) -> vec3f {
    let q = (p - c) / h;
    let a = abs(q);
    if (a.x > a.y && a.x > a.z) { return vec3f(sign(q.x), 0.0, 0.0); }
    if (a.y > a.z) { return vec3f(0.0, sign(q.y), 0.0); }
    return vec3f(0.0, 0.0, sign(q.z));
}

fn cap_t(ro: vec3f, rd: vec3f, pa: vec3f, pb: vec3f, r: f32) -> f32 {
    let ba = pb - pa;
    let oa = ro - pa;
    let baba = dot(ba, ba);
    let bard = dot(ba, rd);
    let baoa = dot(ba, oa);
    let rdoa = dot(rd, oa);
    let oaoa = dot(oa, oa);
    let a = baba - bard * bard;
    let b = baba * rdoa - baoa * bard;
    let c = baba * oaoa - baoa * baoa - r * r * baba;
    let h = b * b - a * c;
    if (h >= 0.0) {
        let t = (-b - sqrt(h)) / a;
        let y = baoa + t * bard;
        if (y > 0.0 && y < baba) { return t; }
        let oc = select(ro - pb, oa, y <= 0.0);
        let b2 = dot(rd, oc);
        let c2 = dot(oc, oc) - r * r;
        let h2 = b2 * b2 - c2;
        if (h2 > 0.0) { return -b2 - sqrt(h2); }
    }
    return -1.0;
}

fn cap_n(p: vec3f, pa: vec3f, pb: vec3f) -> vec3f {
    let ba = pb - pa;
    let h = clamp(dot(p - pa, ba) / dot(ba, ba), 0.0, 1.0);
    return normalize(p - pa - ba * h);
}

fn light_at(p: vec3f, n: vec3f) -> vec3f {
    let L = ldir();
    let b = in_beam(p);
    let lp = HALO_C - p;
    let ld = normalize(lp);
    let hal = max(dot(n, ld), 0.0) * 1.6 / (1.0 + dot(lp, lp) * 0.5);
    let fill = max(dot(n, normalize(vec3f(0.4, 0.6, 0.7))), 0.0) * 0.25;
    return vec3f(0.30, 0.29, 0.30) * (0.7 + 0.3 * n.y) + SUN * max(dot(n, L), 0.0) * b * 2.2 + vec3f(1.0, 0.9, 0.72) * (hal + fill);
}

fn cube_shadow(p: vec3f, lt: f32) -> f32 {
    let L = ldir();
    let s = (0.06 - p.z) / L.z;
    if (s <= 0.0) { return 1.0; }
    let q = p + L * s;
    var sh = 1.0;
    if (abs(q.x) < 1.15 && q.y > 0.85 && q.y < 2.42) { sh = 0.86; }
    let g = vec2f((q.x + 0.9) / 0.2, (q.y - 0.95) / 0.2);
    let ci = floor(g + 0.5);
    if (ci.x < 0.0 || ci.x > 9.0 || ci.y < 0.0 || ci.y > 6.0) { return sh; }
    let k = i32(ci.y) * 10 + i32(ci.x);
    let c = cube(k, lt);
    let loc = abs(g - ci) * 0.2;
    let inside = 1.0 - smoothstep(c.h - 0.012, c.h + 0.012, max(loc.x, loc.y));
    return sh * (1.0 - 0.85 * inside * c.home * step(0.001, c.h));
}

fn floor_col(p: vec3f, lt: f32, pl: f32) -> vec3f {
    var base = vec3f(0.20, 0.19, 0.18) * (0.8 + 0.35 * noise3(vec3f(p.x * 1.7, 0.5, p.z * 1.7)));
    let g = abs(fract(p.xz / 2.0) - 0.5);
    base *= mix(0.7, 1.0, 1.0 - smoothstep(0.47, 0.49, max(g.x, g.y)));
    let b = in_beam(p);
    var sh = 1.0;
    if (b > 0.0) { sh = cube_shadow(p, lt); }
    let hd = dot(p.xz, p.xz);
    let c = base * (vec3f(0.42, 0.40, 0.40) + SUN * b * sh * 2.6 + (vec3f(1.0, 0.88, 0.7) + TEAL * pl * 0.6) * 0.9 / (1.0 + hd * 0.6));
    var ao = 1.0;
    let f1 = p.xz - vec2f(-1.35, 0.45);
    let f2 = p.xz - vec2f(1.35, 0.45);
    let f3 = p.xz - vec2f(0.0, -1.2);
    ao *= 1.0 - 0.55 * exp(-dot(f1, f1) * 25.0);
    ao *= 1.0 - 0.55 * exp(-dot(f2, f2) * 25.0);
    ao *= 1.0 - 0.55 * exp(-dot(f3, f3) * 25.0);
    ao *= 1.0 - 0.35 * exp(-p.z * p.z * 4.0) * (1.0 - smoothstep(0.9, 1.5, abs(p.x)));
    let edge = min(6.0 - abs(p.x), 6.0 - abs(p.z));
    ao *= mix(0.55, 1.0, smoothstep(0.0, 1.4, edge));
    return c * ao;
}

fn ceil_col(p: vec3f, pl: f32) -> vec3f {
    let d = p.xz;
    let g = 1.8 / (1.0 + dot(d, d) * 0.35);
    let edge = min(6.0 - abs(p.x), 6.0 - abs(p.z));
    return IVORY * 0.5 * (vec3f(0.35) + (vec3f(1.0, 0.86, 0.66) + TEAL * pl * 0.5) * g) * mix(0.6, 1.0, smoothstep(0.0, 1.5, edge));
}

fn wall_col(p: vec3f, tt: f32, pl: f32) -> vec3f {
    var id = 0;
    var u = p.x;
    if (abs(p.x) > abs(p.z)) { id = select(2, 3, p.x > 0.0); u = p.z; } else { id = select(0, 1, p.z > 0.0); }
    let fid = f32(id);
    let v = p.y;
    var base = IVORY * 0.78 * (0.9 + 0.2 * noise3(p * 2.5));
    // sketches of finished rooms drifting up and dissolving
    let sv = v - tt * 0.18;
    let cell = floor(vec2f(u, sv) / 1.5);
    let hc = hash13(vec3f(cell, fid + 1.0));
    let lc = (fract(vec2f(u, sv) / 1.5) - 0.5) * 1.5;
    let sz = 0.28 + 0.22 * hash13(vec3f(cell + 3.1, fid));
    let qd = abs(lc + (vec2f(hc, fract(hc * 7.3)) - 0.5) * 0.25);
    let wob = (noise3(vec3f(u * 7.0, v * 7.0, fid)) - 0.5) * 0.02;
    let sq = abs(max(qd.x, qd.y) - sz) + wob;
    var ln = 1.0 - smoothstep(0.004, 0.014, abs(sq));
    ln *= select(1.0, 0.0, min(qd.x, qd.y) < sz * 0.2);
    let thr = (v - 1.2) / 3.0;
    let keep = smoothstep(thr - 0.12, thr + 0.12, noise3(vec3f(u * 10.0, v * 10.0, fid * 3.0)));
    let fade = smoothstep(0.5, 1.5, v) * (1.0 - smoothstep(3.6, 4.4, v));
    let a = ln * keep * fade * step(0.4, hc) * 0.6;
    let inkc = select(GRAPH * 2.0, TEAL * 0.6, hc > 0.92);
    base = mix(base, inkc, a);
    let hdv = p - HALO_C;
    let ao = mix(0.55, 1.0, smoothstep(0.0, 1.0, min(v, ROOM_HEIGHT - v))) * mix(0.6, 1.0, smoothstep(0.0, 1.2, 6.0 - abs(u)));
    var c = base * (vec3f(0.5, 0.48, 0.46) + (vec3f(1.0, 0.88, 0.7) + TEAL * pl * 0.4) * 1.6 / (1.0 + dot(hdv, hdv) * 0.12)) * ao;
    // grid panels: cells light up one by one
    let au = abs(u);
    if (au > 1.4 && au < 5.0 && v > 0.9 && v < 2.7) {
        let side = select(0.0, 1.0, u > 0.0);
        let pid = fid * 2.0 + side;
        let pu = vec2f(au - 1.4, v - 0.9);
        let ci = floor(pu / 0.3);
        let lc2 = fract(pu / 0.3) - 0.5;
        let prog = fract(tt / 15.0 + pid * 0.173) * 1.12;
        let h = hash13(vec3f(ci, pid + 11.0));
        let age = (prog - h) * 15.0 / 1.12;
        let sqc = max(abs(lc2.x), abs(lc2.y));
        let cellm = 1.0 - smoothstep(0.36, 0.40, sqc);
        var cc = vec3f(0.17, 0.17, 0.18);
        if (age > 0.0) { cc = TEAL * 0.32 + vec3f(0.03) + (TEAL * 2.2 + vec3f(0.8)) * exp(-age * 1.6); }
        var pc = mix(GRAPH * 0.9, cc, cellm);
        let ed = min(min(pu.x, 3.6 - pu.x), min(pu.y, 1.8 - pu.y));
        pc = mix(IVORY * 0.9, pc, smoothstep(0.015, 0.03, ed));
        c = pc + c * 0.05;
    }
    if (id == 0) {
        let wm = win_mask(vec2f(p.x, p.y));
        let wc = vec2f(p.x + 0.6, p.y - 3.6);
        c += SUN * 0.35 * exp(-dot(wc, wc) * 0.8);
        let sky = mix(vec3f(1.8, 1.6, 1.3), vec3f(1.2, 1.4, 1.6), smoothstep(2.9, 4.3, p.y));
        c = mix(c, sky, wm);
    }
    return c;
}

fn cubes(ro: vec3f, rd: vec3f, tmin: f32, best: Op, lt: f32) -> Op {
    var o = best;
    let bs = box_span(ro, rd, vec3f(-1.35, 0.85, -0.05), vec3f(1.35, 3.4, 1.05));
    if (bs.x > bs.y || bs.y < tmin || bs.x > o.t) { return o; }
    var hk = -1;
    var hc = Cube(vec3f(0.0), 0.0, 0.0, 0.0);
    for (var k = 0; k < NCUBE; k = k + 1) {
        let c = cube(k, lt);
        if (c.h <= 0.0) { continue; }
        let sp = box_span(ro, rd, c.c - vec3f(c.h), c.c + vec3f(c.h));
        if (sp.x <= sp.y && sp.x > tmin && sp.x < o.t) { o.t = sp.x; hk = k; hc = c; }
    }
    if (hk >= 0) {
        let p = ro + rd * o.t;
        let n = bnorm(p, hc.c, vec3f(hc.h));
        let q = (p - hc.c) / hc.h;
        var uv = q.xy;
        if (abs(n.x) > 0.5) { uv = q.zy; }
        if (abs(n.y) > 0.5) { uv = q.xz; }
        let edge = max(abs(uv.x), abs(uv.y));
        let tint = 0.85 + 0.15 * hash12(vec2f(f32(hk), 3.0));
        var base = IVORY * 0.82 * tint;
        base = mix(base, GRAPH, smoothstep(0.84, 0.92, edge));
        var door = 0.0;
        if (abs(n.y) < 0.5) { door = (1.0 - smoothstep(0.13, 0.18, abs(uv.x))) * (1.0 - smoothstep(0.1, 0.17, uv.y)); }
        base = mix(base, GRAPH * 0.6, door);
        var cc = base * light_at(p, n);
        cc += TEAL * hc.flash * (0.5 + 2.5 * door) + TEAL * 0.15 * door;
        o.col = cc;
    }
    return o;
}

fn halo_sd(p: vec3f, tt: f32) -> vec2f {
    var q = p - HALO_C;
    let xz = rot2(tt * 0.45) * q.xz;
    q = vec3f(xz.x, q.y, xz.y);
    let yz = rot2(0.4 + 0.1 * sin(tt * 0.37)) * q.yz;
    q = vec3f(q.x, yz.x, yz.y);
    let d = length(vec2f(length(q.xz) - 0.62, q.y)) - 0.028;
    return vec2f(d, atan2(q.z, q.x));
}

fn halo(ro: vec3f, rd: vec3f, tmin: f32, tend: f32, tt: f32, pl: f32) -> vec4f {
    let oc = ro - HALO_C;
    let b = dot(oc, rd);
    let c = dot(oc, oc) - 0.85 * 0.85;
    let disc = b * b - c;
    if (disc < 0.0) { return vec4f(0.0, 0.0, 0.0, -1.0); }
    let sq = sqrt(disc);
    var t = max(-b - sq, tmin);
    let t1 = min(-b + sq, tend);
    var g = vec3f(0.0);
    let n = i32(mix(18.0, 36.0, quality()));
    let warm = vec3f(1.0, 0.82, 0.55);
    for (var i = 0; i < 36; i = i + 1) {
        if (i >= n || t > t1) { break; }
        let s = halo_sd(ro + rd * t, tt);
        let br = 0.55 + 0.45 * sin(s.y * 3.0 - tt * 2.0);
        let gc = mix(warm, TEAL, clamp(pl * 0.8 + 0.15 * sin(s.y * 2.0 + tt), 0.0, 1.0)) * br;
        if (s.x < 0.002) { return vec4f(g + gc * 3.0 + vec3f(0.6), t); }
        let dt = max(s.x * 0.7, 0.01);
        g += gc * dt * 0.035 / (s.x * s.x + 0.002);
        t += dt;
    }
    return vec4f(g, -1.0);
}

fn glass_over(col: vec3f, n0: vec3f, rd: vec3f, p: vec3f, a: f32) -> vec3f {
    let n = select(n0, -n0, dot(n0, rd) > 0.0);
    let fres = pow(1.0 - abs(dot(n, rd)), 4.0);
    let r = reflect(rd, n);
    let sp = pow(max(dot(r, ldir()), 0.0), 48.0) * 4.0 + pow(max(dot(r, normalize(HALO_C - p)), 0.0), 24.0) * 1.5;
    let gc = vec3f(0.75, 0.92, 0.9) * 0.55 + IVORY * fres * 1.2 + SUN * sp;
    let aa = clamp(a + fres * 0.55, 0.0, 0.9);
    return mix(col, gc, aa) + SUN * sp * 0.3;
}

fn beam_scatter(ro: vec3f, rd: vec3f, t0: f32, t1: f32, tt: f32) -> vec3f {
    let n = i32(mix(8.0, 16.0, quality()));
    let dt = max(t1 - t0, 0.0) / f32(n);
    let j = hash13(rd * 1543.7);
    var acc = 0.0;
    for (var i = 0; i < 16; i = i + 1) {
        if (i >= n) { break; }
        let p = ro + rd * (t0 + (f32(i) + j) * dt);
        acc += in_beam(p) * (0.5 + 0.9 * noise3(p * 1.3 + vec3f(0.0, -tt * 0.05, tt * 0.03)));
    }
    return SUN * acc * dt * 0.07;
}

fn motes(ro: vec3f, rd: vec3f, t0: f32, t1: f32, tt: f32) -> vec3f {
    let L = ldir();
    let nm = i32(mix(16.0, 32.0, quality()));
    var g = 0.0;
    for (var i = 0; i < 32; i = i + 1) {
        if (i >= nm) { break; }
        let fi = f32(i);
        let h = hash33(vec3f(fi, 7.0, 3.0));
        let w = vec3f(mix(-1.7, 0.5, h.x), mix(2.9, 4.3, h.y), -6.0);
        let s = 0.5 + 9.5 * fract(h.z + tt * 0.008);
        let p = w - L * s + vec3f(sin(tt * 0.31 + fi * 1.7), sin(tt * 0.23 + fi * 2.9), cos(tt * 0.27 + fi)) * 0.12;
        let tp = dot(p - ro, rd);
        if (tp < t0 || tp > t1) { continue; }
        let d = length(p - ro - rd * tp);
        let r = 0.004 + 0.0018 * tp;
        let tw = 0.55 + 0.45 * sin(tt * 2.0 + fi * 4.1);
        g += exp(-d * d / (r * r)) * tw * in_beam(p);
    }
    return SUN * g * 1.4;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let tt = time();
    let lt = fract(tt / CYC) * CYC;
    let pl = pulse(lt);
    let tb = horizon_t(tmax);
    let pe = ro + rd * tb;
    var o = Op(tb, vec3f(0.0));
    if (pe.y < 0.02) { o.col = floor_col(pe, lt, pl); }
    else if (pe.y > ROOM_HEIGHT - 0.02) { o.col = ceil_col(pe, pl); }
    else { o.col = wall_col(pe, tt, pl); }

    o = cubes(ro, rd, tmin, o, lt);

    let hv = halo(ro, rd, tmin, o.t, tt, pl);
    if (hv.w > 0.0) { o.t = hv.w; o.col = vec3f(0.0); }
    var col = o.col + hv.rgb;

    // glass pane with faint guide grid
    if (abs(rd.z) > 1e-4) {
        let tp = (-0.04 - ro.z) / rd.z;
        if (tp > tmin && tp < o.t) {
            let p = ro + rd * tp;
            let e = min(1.15 - abs(p.x), min(p.y - 0.85, 2.42 - p.y));
            if (e > 0.0) {
                let gx = abs(fract((p.x + 1.0) / 0.2 + 0.5) - 0.5) * 0.2;
                let gy = abs(fract((p.y - 0.85) / 0.2 + 0.5) - 0.5) * 0.2;
                let grid = (1.0 - smoothstep(0.002, 0.006, min(gx, gy))) * step(abs(p.x), 1.0) * step(p.y, 2.25);
                col = glass_over(col, vec3f(0.0, 0.0, 1.0), rd, p, 0.07 + 0.55 * (1.0 - smoothstep(0.0, 0.035, e)));
                col += TEAL * grid * (0.12 + 0.5 * pl);
            }
        }
    }
    let lmin = vec3f(-1.32, 0.76, -0.14);
    let lmax = vec3f(1.32, 0.84, 0.2);
    let ls = box_span(ro, rd, lmin, lmax);
    if (ls.x <= ls.y && ls.x > tmin && ls.x < o.t) {
        let p = ro + rd * ls.x;
        col = glass_over(col, bnorm(p, (lmin + lmax) * 0.5, (lmax - lmin) * 0.5), rd, p, 0.35);
    }
    let cmin = vec3f(-0.2, 2.42, -0.12);
    let cmax = vec3f(0.2, 2.5, 0.06);
    let cs = box_span(ro, rd, cmin, cmax);
    if (cs.x <= cs.y && cs.x > tmin && cs.x < o.t) {
        let p = ro + rd * cs.x;
        col = glass_over(col, bnorm(p, (cmin + cmax) * 0.5, (cmax - cmin) * 0.5), rd, p, 0.4);
    }
    for (var i = 0; i < 3; i = i + 1) {
        var pa = vec3f(-1.35, 0.0, 0.45);
        var pb = vec3f(-1.2, 2.75, -0.05);
        if (i == 1) { pa = vec3f(1.35, 0.0, 0.45); pb = vec3f(1.2, 2.75, -0.05); }
        if (i == 2) { pa = vec3f(0.0, 0.0, -1.2); pb = vec3f(0.0, 2.6, -0.12); }
        let tl = cap_t(ro, rd, pa, pb, 0.03);
        if (tl > tmin && tl < o.t) {
            let p = ro + rd * tl;
            col = glass_over(col, cap_n(p, pa, pb), rd, p, 0.3);
        }
    }

    let t1 = min(o.t, tb);
    col += beam_scatter(ro, rd, tmin, t1, tt) + motes(ro, rd, tmin, t1, tt);
    return Hit(tone(col * 1.15), clamp(o.t, tmin, tmax));
}

// Vigil Under the Oculus: a night chapel for those who wait for the station to come home.
// A pale stone altar with a silver bowl under a wide open oculus; stars turn, the station arcs past again and again,
// amber candles line the walls, a silver thread of light rises from the bowl and swells as the station passes.
const OR: f32 = 2.6;
const LEDGE: f32 = 0.85;
const GOLD: vec3f = vec3f(1.0, 0.55, 0.18);
const SILV: vec3f = vec3f(0.55, 0.7, 1.0);
const IND: vec3f = vec3f(0.025, 0.03, 0.09);
const BOWL: vec3f = vec3f(0.0, 1.92, 0.0);

var<private> T: f32;
var<private> STAZ: f32;
var<private> STD: vec3f;
var<private> SWELL: f32;
var<private> LK: vec3f;
var<private> MAT: i32;
var<private> CFAVG: f32;
var<private> CP: array<vec4f, 24>;
var<private> CF: array<f32, 24>;

fn path_el(az: f32) -> f32 { return 0.8 + 0.2 * sin(az * 2.0 + 0.5); }

fn setup() {
    T = time();
    STAZ = T * 1.05;
    let el = path_el(STAZ);
    STD = vec3f(cos(el) * cos(STAZ), sin(el), cos(el) * sin(STAZ));
    SWELL = smoothstep(0.78, 0.96, el);
    LK = normalize(vec3f(0.1, 1.0, 0.06));
    let breath = 0.85 + 0.15 * sin(T * 0.45);
    var s = 0.0;
    for (var i = 0; i < 24; i = i + 1) {
        let fi = f32(i);
        let w = i / 6;
        let k = i % 6;
        let sg = select(-1.0, 1.0, k >= 3);
        let u = sg * (1.75 + f32(k % 3) * 1.45);
        let h = 0.12 + 0.2 * hash12(vec2f(fi, 3.1));
        var p = vec3f(-5.78, LEDGE, u);
        if (w == 1) { p = vec3f(5.78, LEDGE, -u); }
        else if (w == 2) { p = vec3f(u, LEDGE, -5.78); }
        else if (w == 3) { p = vec3f(-u, LEDGE, 5.78); }
        CP[i] = vec4f(p, h);
        let hh = hash12(vec2f(fi, 9.7));
        let f = breath * (0.8 + 0.2 * sin(T * (0.7 + 0.5 * hh) + hh * 40.0) * sin(T * 1.9 + hh * 13.0));
        CF[i] = f;
        s += f;
    }
    CFAVG = s / 24.0;
}

fn tm(c: vec3f, rd: vec3f) -> vec3f {
    let fw = room.inv_rot_proj * vec4f(0.0, 0.0, 0.5, 1.0);
    let vig = 1.0 - 0.3 * smoothstep(0.97, 0.55, dot(rd, normalize(fw.xyz / fw.w)));
    let x = max(c, vec3f(0.0)) * vig;
    let y = (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14);
    return clamp(y + (hash13(rd * 913.7) - 0.5) / 255.0, vec3f(0.0), vec3f(1.0));
}

fn candle_light(p: vec3f, n: vec3f) -> f32 {
    var s = 0.0;
    for (var i = 0; i < 24; i = i + 1) {
        let f = CP[i].xyz + vec3f(0.0, CP[i].w + 0.06, 0.0);
        let v = f - p;
        let d2 = dot(v, v);
        s += CF[i] * max(dot(n, v) * inverseSqrt(d2), 0.0) / (0.05 + d2);
    }
    return s;
}

fn flames(ro: vec3f, rd: vec3f, tend: f32, blur: f32) -> vec3f {
    var c = vec3f(0.0);
    for (var i = 0; i < 24; i = i + 1) {
        let cp = CP[i];
        let sway = 0.006 * sin(T * 2.1 + f32(i) * 1.7);
        let f = cp.xyz + vec3f(sway, cp.w + 0.05, 0.0);
        let v = f - ro;
        let tp = dot(v, rd);
        if (tp > 0.05 && tp < tend) {
            let dv = ro + rd * tp - f;
            let e = vec3f(dv.x, dv.y * 0.45, dv.z);
            let s = (0.0001 + 0.0000015 * tp * tp) * blur;
            let fl = CF[i];
            c += vec3f(1.0, 0.8, 0.45) * exp(-dot(e, e) / s) * 4.0 * fl;
            c += GOLD * fl * (0.03 / (1.0 + dot(dv, dv) * 120.0) + 0.006 / (1.0 + dot(dv, dv) * 6.0));
        }
    }
    return c;
}

fn sky(rd: vec3f) -> vec3f {
    let y = max(rd.y, 0.0);
    var c = mix(vec3f(0.05, 0.06, 0.17), vec3f(0.008, 0.01, 0.04), sqrt(y));
    let xz = rot2(T * 0.03) * rd.xz;
    let r = vec3f(xz.x, rd.y, xz.y);
    let bd = dot(r, normalize(vec3f(0.35, 0.25, 1.0)));
    let neb = noise3(r * 5.0) * 0.6 + noise3(r * 14.0) * 0.4;
    c += vec3f(0.09, 0.1, 0.24) * exp(-bd * bd * 9.0) * neb;
    for (var k = 0; k < 2; k = k + 1) {
        let fk = f32(k);
        let q = r * (60.0 + fk * 55.0);
        let id = floor(q);
        let h = hash33(id + fk * 31.0);
        let d = length(q - id - 0.2 - 0.6 * h);
        let tw = 0.6 + 0.4 * sin(T * (1.5 + 2.0 * h.y) + h.z * 30.0);
        let sc = mix(vec3f(0.75, 0.85, 1.0), vec3f(1.0, 0.85, 0.6), h.z);
        c += sc * exp(-d * d * 60.0) * step(0.62, h.x) * tw * (0.6 + 2.0 * h.y * h.y);
    }
    // the station's arc: a faint ghost of the whole path, brighter just behind the light
    let a = atan2(rd.z, rd.x);
    let erd = asin(clamp(rd.y, -1.0, 1.0));
    let de = erd - path_el(a);
    let lag = fract((STAZ - a) / TAU) * TAU;
    let trl = exp(-de * de / 0.000006);
    c += vec3f(0.6, 0.72, 1.0) * trl * (0.04 + 0.7 * exp(-lag * 1.6));
    let ca = max(1.0 - dot(rd, STD), 0.0) * 2.0;
    c += vec3f(1.0, 0.95, 0.85) * (exp(-ca / 0.000012) * 6.0 + exp(-ca / 0.0006) * 0.6 + exp(-ca / 0.01) * 0.12);
    return c;
}

fn cylv(p: vec3f, r: f32, y0: f32, y1: f32) -> f32 {
    let d = vec2f(length(p.xz) - r, abs(p.y - 0.5 * (y0 + y1)) - 0.5 * (y1 - y0));
    return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

fn map(p: vec3f) -> f32 {
    var d = cylv(p, 1.9, 0.0, 0.13);
    d = min(d, cylv(p, 1.5, 0.0, 0.26));
    d = min(d, cylv(p, 1.1, 0.0, 0.39));
    d = min(d, sd_box(p - vec3f(0.0, 0.48, 0.0), vec3f(0.66, 0.09, 0.52)) - 0.01);
    var body = sd_box(p - vec3f(0.0, 1.0, 0.0), vec3f(0.5, 0.45, 0.38)) - 0.01;
    let gq = p - vec3f(0.0, 1.3, 0.0);
    body = max(body, -max(sd_box(gq, vec3f(0.6, 0.02, 0.5)), -sd_box(gq, vec3f(0.48, 0.1, 0.36))));
    d = min(d, body);
    d = min(d, sd_box(p - vec3f(0.0, 1.55, 0.0), vec3f(0.66, 0.07, 0.5)) - 0.012);
    MAT = 0;
    let c = p - BOWL;
    let bowl = min(max(abs(length(c) - 0.3) - 0.016, c.y), cylv(p, 0.09, 1.6, 1.66));
    if (bowl < d) { d = bowl; MAT = 1; }
    let liq = max(length(c) - 0.29, c.y + 0.05);
    if (liq < d) { d = liq; MAT = 2; }
    return d;
}

fn calc_n(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn soft_shadow(p: vec3f, l: vec3f) -> f32 {
    let sp = box_span(p, l, vec3f(-1.95, 0.0, -1.95), vec3f(1.95, 2.25, 1.95));
    if (sp.x > sp.y || sp.y < 0.0) { return 1.0; }
    var t = max(sp.x, 0.02);
    var res = 1.0;
    for (var i = 0; i < 14; i = i + 1) {
        let h = map(p + l * t);
        res = min(res, 10.0 * h / t);
        t += clamp(h, 0.03, 0.4);
        if (res < 0.02 || t > sp.y) { break; }
    }
    return clamp(res, 0.0, 1.0);
}

fn beam_mask(p: vec3f) -> f32 {
    let q = p + LK * ((4.5 - p.y) / LK.y);
    return smoothstep(OR, OR - 0.35, length(q.xz));
}

fn shade_obj(p: vec3f, rd: vec3f, m: i32) -> vec3f {
    let n = calc_n(p);
    let ao = clamp(0.35 + 0.65 * map(p + n * 0.1) / 0.1, 0.25, 1.0);
    let bm = beam_mask(p);
    var sh = 0.0;
    if (bm > 0.01) { sh = soft_shadow(p + n * 0.012, LK); }
    let dk = max(dot(n, LK), 0.0);
    let kl = SILV * 1.4 * (1.0 + 0.7 * SWELL) * dk * sh * bm;
    let warm = GOLD * 0.4 * CFAVG * (0.5 + 0.5 * (1.0 - abs(n.y))) * ao;
    let amb = IND * (1.0 + 0.8 * n.y) * ao + SILV * 0.1 * (1.0 - abs(n.y)) * ao;
    let fres = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    if (m == 2) {
        let rip = 0.85 + 0.15 * sin(length(p.xz) * 60.0 - T * 3.0);
        return SILV * (0.6 + 1.8 * SWELL) * rip;
    }
    if (m == 1) {
        let r = reflect(rd, n);
        let e = mix(IND * 2.0, SILV * 0.7, smoothstep(0.1, 0.9, r.y)) + GOLD * 0.35 * CFAVG * exp(-abs(r.y) * 5.0);
        var c = vec3f(0.8, 0.83, 0.88) * (e * (0.5 + 0.5 * ao) + kl * 0.4);
        c += SILV * pow(max(dot(r, LK), 0.0), 40.0) * sh * bm * 1.5;
        if (length(p - BOWL) < 0.3) { c += SILV * 0.3 * (1.0 + 2.0 * SWELL); }
        return c;
    }
    var alb = vec3f(0.84, 0.81, 0.76) * (0.88 + 0.18 * noise3(p * 5.0));
    let vein = smoothstep(0.03, 0.0, abs(noise3(p * vec3f(2.5, 4.0, 2.5)) - 0.5));
    alb *= 1.0 - 0.18 * vein;
    var gild = 0.0;
    var glowd = 0.0;
    if (abs(n.y) < 0.5 && p.y > 0.6 && p.y < 1.26) {
        // fluted faces, each with a gilded orbit ring whose silver point follows the station
        let cu = select(p.x, p.z, abs(n.x) > 0.5);
        let uv = vec2f(cu, p.y - 0.93);
        let rl = length(uv);
        let flute = abs(sin(cu * 31.4));
        let inMed = smoothstep(0.31, 0.29, rl);
        alb *= mix(0.78 + 0.22 * flute, 1.0, inMed);
        gild = max(smoothstep(0.012, 0.005, abs(rl - 0.22)), smoothstep(0.05, 0.04, rl));
        let dp = 0.22 * vec2f(cos(STAZ), sin(STAZ));
        glowd = smoothstep(0.035, 0.018, length(uv - dp));
    }
    var c = alb * (kl + warm + amb);
    c = mix(c, vec3f(1.0, 0.72, 0.35) * (warm * 2.2 + kl * 0.8 + IND), gild);
    c += SILV * glowd * (0.8 + 1.5 * SWELL);
    c += SILV * fres * 0.06 * (0.3 + bm);
    return c;
}

fn ceiling(p: vec3f, rd: vec3f) -> vec3f {
    let r = length(p.xz);
    if (r < OR) { return sky(rd); }
    let a = atan2(p.z, p.x);
    let ru = r - OR;
    var alb = vec3f(0.1, 0.11, 0.2);
    let rf = fract(ru / 0.75);
    let seg = fract(a / TAU * 24.0);
    let rib = max(smoothstep(0.08, 0.0, min(rf, 1.0 - rf)), smoothstep(0.06, 0.0, min(seg, 1.0 - seg) * r * 0.26));
    alb = mix(alb, vec3f(0.5, 0.5, 0.52), rib);
    let cc = vec2f((rf - 0.5) * 0.75, (seg - 0.5) * 0.26 * r);
    let star = smoothstep(0.035, 0.0, length(cc));
    let rim = smoothstep(0.22, 0.18, ru);
    alb = mix(alb, vec3f(0.85, 0.83, 0.8), rim);
    let cl = candle_light(p, vec3f(0.0, -1.0, 0.0));
    var c = alb * (GOLD * cl * 0.06 + IND * 0.8 + SILV * 0.14 * exp(-ru * 1.2) * (1.0 + SWELL));
    c += vec3f(1.0, 0.7, 0.3) * star * (0.05 + cl * 0.05);
    return c;
}

fn wall(p: vec3f) -> vec3f {
    var n = vec3f(0.0, 0.0, -sign(p.z));
    var u = p.x;
    if (abs(p.x) > abs(p.z)) { n = vec3f(-sign(p.x), 0.0, 0.0); u = p.z; }
    let row = floor(p.y / 0.38);
    let bx = u / 0.75 + row * 0.5;
    let hb = hash12(vec2f(floor(bx), row + n.x * 7.0 + n.z * 13.0));
    let jx = fract(bx);
    let jy = fract(p.y / 0.38);
    let joint = max(smoothstep(0.03, 0.0, min(jx, 1.0 - jx) * 0.75), smoothstep(0.04, 0.0, min(jy, 1.0 - jy) * 0.38));
    let alb = vec3f(0.62, 0.6, 0.57) * (0.8 + 0.25 * hb) * (1.0 - 0.5 * joint);
    let cl = candle_light(p, n);
    return alb * (GOLD * cl * 0.06 + IND * 0.7 + SILV * 0.05 * smoothstep(1.5, 4.5, p.y));
}

fn floor_col(p: vec3f, rd: vec3f) -> vec3f {
    let g = abs(fract(p.xz) - 0.5);
    let grout = smoothstep(0.485, 0.497, max(g.x, g.y));
    let hb = hash12(floor(p.xz));
    let alb = vec3f(0.07, 0.075, 0.1) * (0.8 + 0.4 * hb) * (1.0 - 0.6 * grout);
    let cl = candle_light(p, vec3f(0.0, 1.0, 0.0));
    let bm = beam_mask(p);
    var sh = 1.0;
    if (bm > 0.01 && dot(p.xz, p.xz) < 6.0) { sh = soft_shadow(p + vec3f(0.0, 0.01, 0.0), LK); }
    var c = alb * (GOLD * cl * 0.25 + IND * 1.2 + SILV * bm * sh * 1.8 * (1.0 + 0.6 * SWELL));
    let rr = reflect(rd, vec3f(0.0, 1.0, 0.0));
    let tc = (4.5 - p.y) / max(rr.y, 0.001);
    let oc = length((p + rr * tc).xz);
    c += (1.0 - grout) * 0.12 * smoothstep(OR, OR - 0.3, oc) * vec3f(0.12, 0.15, 0.32);
    if (quality() > 0.3) { c += (1.0 - grout) * flames(p, rr, 30.0, 6.0) * 0.18; }
    return c;
}

fn rise_thread(ro: vec3f, rd: vec3f, tend: f32) -> vec3f {
    let a = dot(rd.xz, rd.xz);
    if (a < 1e-6) { return vec3f(0.0); }
    let tc = -dot(ro.xz, rd.xz) / a;
    if (tc < 0.0 || tc > tend) { return vec3f(0.0); }
    let p = ro + rd * tc;
    let h2 = dot(p.xz, p.xz);
    let ins = smoothstep(1.88, 2.0, p.y) * smoothstep(4.6, 4.3, p.y);
    let pulse = 0.6 + 0.4 * sin(p.y * 5.0 - T * 3.0);
    let inten = (0.3 + 1.7 * SWELL) * ins;
    return SILV * inten * (exp(-h2 / 0.00012) * 1.5 * pulse + 0.012 / (1.0 + h2 * 300.0) + 0.004 / (1.0 + h2 * 10.0));
}

fn shaft(ro: vec3f, rd: vec3f, tend: f32) -> vec3f {
    let o = ro - vec3f(0.0, 4.5, 0.0);
    let op = o - LK * dot(o, LK);
    let dp = rd - LK * dot(rd, LK);
    let A = dot(dp, dp);
    if (A < 1e-6) { return vec3f(0.0); }
    let B = dot(op, dp);
    let C = dot(op, op) - OR * OR * 0.9;
    let disc = B * B - A * C;
    if (disc <= 0.0) { return vec3f(0.0); }
    let s = sqrt(disc);
    let t0 = max((-B - s) / A, 0.0);
    var t1 = min((-B + s) / A, tend);
    if (rd.y > 0.0) { t1 = min(t1, (4.5 - ro.y) / rd.y); }
    if (t1 <= t0) { return vec3f(0.0); }
    let ym = ro.y + rd.y * 0.5 * (t0 + t1);
    return SILV * (t1 - t0) * (0.012 + 0.012 * ym / 4.5) * (1.0 + 1.2 * SWELL);
}

fn motes(ro: vec3f, rd: vec3f, tend: f32) -> vec3f {
    var c = vec3f(0.0);
    for (var i = 0; i < 16; i = i + 1) {
        let h = hash33(vec3f(f32(i), 1.3, 5.7));
        let ph = T * 0.2 + h.x * 10.0;
        let pos = vec3f((h.x - 0.5) * 4.2 + 0.2 * sin(ph), 0.2 + 4.1 * fract(h.y - T * 0.012 * (0.5 + h.z)), (h.z - 0.5) * 4.2 + 0.2 * cos(ph * 1.3));
        let v = pos - ro;
        let tp = dot(v, rd);
        if (tp > 0.2 && tp < tend) {
            let dd = length(v - rd * tp);
            c += SILV * exp(-dd * dd / (0.00003 * tp * tp + 0.000003)) * beam_mask(pos) * 0.5;
        }
    }
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    setup();
    var th = horizon_t(tmax);
    var col = vec3f(0.0);
    var best = 1e9;
    var kind = -1;
    var am = 0;
    let sp = box_span(ro, rd, vec3f(-1.95, 0.0, -1.95), vec3f(1.95, 2.0, 1.95));
    let t0 = max(sp.x, tmin);
    let t1 = min(sp.y, tmax);
    if (sp.x <= sp.y && t0 < t1) {
        let steps = i32(mix(32.0, 72.0, quality()));
        var t = t0;
        var hit = false;
        for (var i = 0; i < steps; i = i + 1) {
            let d = map(ro + rd * t);
            if (d < 0.0005 + 0.0008 * t) { hit = true; break; }
            t += d * 0.9;
            if (t > t1) { break; }
        }
        if (hit && t <= t1) { best = t; kind = 2; am = MAT; }
    }
    // stone ledges along the walls, clear of the doorways
    var ln = vec3f(0.0, 1.0, 0.0);
    var cid = 0;
    for (var i = 0; i < 8; i = i + 1) {
        let w = i / 2;
        let pos = (i % 2) == 1;
        let lo = select(-6.0, 1.3, pos);
        let hi = select(-1.3, 6.0, pos);
        var bmin = vec3f(-6.01, 0.0, lo);
        var bmax = vec3f(-5.6, LEDGE, hi);
        if (w == 1) { bmin = vec3f(5.6, 0.0, lo); bmax = vec3f(6.01, LEDGE, hi); }
        else if (w == 2) { bmin = vec3f(lo, 0.0, -6.01); bmax = vec3f(hi, LEDGE, -5.6); }
        else if (w == 3) { bmin = vec3f(lo, 0.0, 5.6); bmax = vec3f(hi, LEDGE, 6.01); }
        let s = box_span(ro, rd, bmin, bmax);
        if (s.x <= s.y && s.x > tmin && s.x < best && s.x < tmax) {
            best = s.x;
            kind = 0;
            let p = ro + rd * s.x;
            let q = (p - 0.5 * (bmin + bmax)) / (0.5 * (bmax - bmin));
            let aq = abs(q);
            if (aq.y > aq.x && aq.y > aq.z) { ln = vec3f(0.0, sign(q.y), 0.0); }
            else if (aq.x > aq.z) { ln = vec3f(sign(q.x), 0.0, 0.0); }
            else { ln = vec3f(0.0, 0.0, sign(q.z)); }
        }
    }
    // the candles themselves
    for (var i = 0; i < 24; i = i + 1) {
        let c = CP[i];
        let oc = ro.xz - c.xz;
        let a = dot(rd.xz, rd.xz);
        let b = dot(oc, rd.xz);
        let cc = dot(oc, oc) - 0.0014;
        let disc = b * b - a * cc;
        if (disc > 0.0 && a > 1e-8) {
            let t = (-b - sqrt(disc)) / a;
            let y = ro.y + rd.y * t;
            if (t > tmin && t < best && y > LEDGE && y < LEDGE + c.w) {
                best = t;
                kind = 1;
                cid = i;
                let hp = oc + rd.xz * t;
                ln = normalize(vec3f(hp.x, 0.0, hp.y));
            }
        }
        if (rd.y < 0.0) {
            let tcap = (LEDGE + c.w - ro.y) / rd.y;
            let hp = ro.xz + rd.xz * tcap - c.xz;
            if (tcap > tmin && tcap < best && dot(hp, hp) < 0.0014) { best = tcap; kind = 1; cid = i; ln = vec3f(0.0, 1.0, 0.0); }
        }
    }
    if (kind == 2) {
        th = best;
        col = shade_obj(ro + rd * best, rd, am);
    } else if (kind == 0) {
        th = best;
        let p = ro + rd * best;
        let alb = vec3f(0.6, 0.58, 0.55) * (0.88 + 0.12 * sin(p.x * 3.1 + p.z * 2.3));
        col = alb * (GOLD * candle_light(p + ln * 0.01, ln) * 0.06 + IND * 0.8);
    } else if (kind == 1) {
        th = best;
        let p = ro + rd * best;
        let c = CP[cid];
        let fl = CF[cid];
        let glow = exp(-(LEDGE + c.w - p.y) * 14.0);
        col = vec3f(0.85, 0.8, 0.68) * (IND * 1.5 + GOLD * 0.25 * fl) + vec3f(1.0, 0.6, 0.25) * glow * 0.9 * fl;
    } else {
        let pe = ro + rd * th;
        if (abs(pe.x) > 6.05 || abs(pe.z) > 6.05 || pe.y < -0.05 || pe.y > 4.55) { return no_hit(); }
        if (pe.y > 4.47) { col = ceiling(pe, rd); }
        else if (pe.y < 0.03) { col = floor_col(pe, rd); }
        else { col = wall(pe); }
    }
    var c = mix(col, IND * 0.5, (1.0 - exp(-th * 0.03)) * 0.5);
    c += flames(ro, rd, th, 1.0);
    c += rise_thread(ro, rd, th);
    c += shaft(ro, rd, th);
    // a soft silver halo hovering over the bowl
    let bv = BOWL + vec3f(0.0, 0.05, 0.0) - ro;
    let btp = dot(bv, rd);
    if (btp > 0.0 && btp < th + 0.3) {
        let bd = length(bv - rd * btp);
        c += SILV * (0.3 + SWELL) * 0.03 / (1.0 + bd * bd * 30.0);
    }
    if (quality() > 0.4) { c += motes(ro, rd, th); }
    return Hit(tm(c * 1.4, rd), clamp(th, tmin, tmax));
}

// Hall of the Worn Faces: a ruined hall of weathered moai, sun shafts, trees and birds.
fn sun_dir() -> vec3f { return normalize(vec3f(0.35, 0.8, -0.5)); }
const SUNC: vec3f = vec3f(2.6, 1.9, 1.05);

var<private> MAT: i32;
var<private> SID: f32;

fn sky(rd: vec3f) -> vec3f {
    let y = clamp(rd.y, 0.0, 1.0);
    var c = mix(vec3f(1.1, 0.9, 0.6), vec3f(0.5, 0.68, 0.95), pow(y, 0.6));
    let s = max(dot(rd, sun_dir()), 0.0);
    c += vec3f(1.6, 1.2, 0.7) * (pow(s, 8.0) * 0.6 + pow(s, 200.0) * 3.0);
    return c;
}

fn hole(xz: vec2f) -> f32 {
    let n = (noise3(vec3f(xz * 1.4, 2.0)) - 0.5) * 0.9;
    var h = smoothstep(1.3, 1.0, length(xz - vec2f(0.3, -4.0)) + n);
    h = max(h, smoothstep(1.0, 0.7, length(xz - vec2f(-2.3, -2.6)) + n));
    h = max(h, smoothstep(1.0, 0.7, length(xz - vec2f(4.1, 0.6)) + n));
    h = max(h, smoothstep(1.2, 0.9, length((xz - vec2f(-0.6, 1.8)) * vec2f(1.0, 0.75)) + n));
    h = max(h, smoothstep(0.9, 0.6, length(xz - vec2f(-2.3, 3.0)) + n));
    h = max(h, smoothstep(1.3, 1.0, length(xz - vec2f(2.6, 4.6)) + n));
    h = max(h, smoothstep(1.5, 1.1, length(xz - vec2f(-5.0, -0.6)) + n));
    h = max(h, smoothstep(1.5, 1.1, length(xz - vec2f(5.0, -3.4)) + n));
    h = max(h, smoothstep(1.5, 1.1, length(xz - vec2f(5.0, 2.3)) + n));
    return h;
}

fn sun_at(p: vec3f) -> f32 {
    let ld = sun_dir();
    return hole(p.xz + ld.xz * ((4.5 - p.y) / ld.y));
}

fn moai(q: vec3f, id: f32) -> f32 {
    let h = hash33(vec3f(id * 1.37 + 0.5, 3.1, 7.7));
    let nod = (h.x - 0.5) * 0.3;
    let tilt = (h.y - 0.5) * 0.16;
    let mc = (h.z - 0.5) * 2.4;
    let bt = (fract(h.x * 13.7 + h.z) - 0.5) * 0.5;
    var d = sd_box(q - vec3f(0.0, 0.15, 0.0), vec3f(0.72, 0.15, 0.78)) - 0.03;
    let tw = 1.0 - 0.12 * clamp((q.y - 0.3) / 1.3, 0.0, 1.0);
    d = min(d, sd_box(q - vec3f(0.05, 0.95, 0.0), vec3f(0.36 * tw, 0.62, 0.52 * tw)) - 0.12);
    var hq = q - vec3f(0.0, 1.5, 0.0);
    let a = rot2(nod) * hq.xy;
    hq = vec3f(a.x, a.y, hq.z);
    let b = rot2(tilt) * vec2f(hq.z, hq.y);
    hq = vec3f(hq.x, b.y, b.x);
    var hd = sd_box(hq - vec3f(0.02, 0.88, 0.0), vec3f(0.38, 0.8, 0.36)) - 0.1;
    var bq = hq - vec3f(-0.4, 1.24, 0.0);
    let c = rot2(bt) * vec2f(bq.z, bq.y);
    bq = vec3f(bq.x, c.y, c.x);
    hd = smin(hd, sd_box(bq, vec3f(0.1, 0.06, 0.36)) - 0.05, 0.12);
    var nq = hq - vec3f(-0.47, 0.93, 0.0);
    let e = rot2(-0.2) * nq.xy;
    nq = vec3f(e.x, e.y, nq.z);
    hd = smin(hd, sd_box(nq, vec3f(0.06, 0.3, 0.08)) - 0.05, 0.1);
    hd = smin(hd, sd_box(hq - vec3f(-0.4, 0.28, 0.0), vec3f(0.08, 0.12, 0.27)) - 0.06, 0.12);
    let eq = vec3f(hq.x - 0.02, hq.y - 0.95, abs(hq.z) - 0.44);
    hd = smin(hd, sd_box(eq, vec3f(0.07, 0.36, 0.03)) - 0.03, 0.06);
    let ee = vec3f(hq.x + 0.5, hq.y - 1.07 + bt * hq.z, abs(hq.z) - 0.19);
    hd = max(hd, -(length(ee * vec3f(1.0, 1.5, 1.0)) - 0.13) * 0.7);
    let my = hq.y - 0.47 + mc * hq.z * hq.z * 3.0;
    hd = max(hd, -(sd_box(vec3f(hq.x + 0.5, my, hq.z), vec3f(0.1, 0.018, 0.19)) - 0.012));
    return min(d, hd);
}

fn tree(p: vec3f, c: vec3f) -> vec2f {
    let sx = -sign(c.x);
    let q = p - c;
    let ax = vec3f(sx * 0.45, 3.5, 0.2);
    let hh = clamp(dot(q, ax) / dot(ax, ax), 0.0, 1.0);
    let fl = exp(-max(q.y, 0.0) * 3.0);
    let rr = 0.17 + 0.3 * fl * (0.8 + 0.2 * sin(atan2(q.z, q.x) * 5.0));
    var d = (length(q - ax * hh) - rr) * 0.8;
    let qb = q - ax * 0.6;
    let br = vec3f(sx * 1.0, 0.9, -0.5);
    let hb = clamp(dot(qb, br) / dot(br, br), 0.0, 1.0);
    d = min(d, length(qb - br * hb) - 0.08);
    var m = 1.0;
    let cq = q - vec3f(sx * 0.6, 3.95, 0.1);
    var dc = (length(cq * vec3f(0.8, 1.3, 0.9)) - 1.3) * 0.75;
    if (dc < 0.45) {
        dc += ((noise3(p * 3.2 + vec3f(0.0, time() * 0.25, 0.0)) - 0.5) * 0.6 + (noise3(p * 8.0) - 0.5) * 0.18) * 0.7;
    }
    if (dc < d) { d = dc; m = 2.0; }
    return vec2f(d, m);
}

fn map(p: vec3f) -> f32 {
    let ax = abs(p.x);
    let i = clamp(floor((p.z + 5.6) / 2.8), 0.0, 3.0);
    let zc = -4.2 + 2.8 * i;
    let q = vec3f(ax - 3.7, p.y, p.z - zc);
    let id = i + select(0.0, 4.0, p.x > 0.0);
    var d = sd_box(q - vec3f(0.0, 1.7, 0.0), vec3f(0.85, 1.75, 0.85));
    if (d < 0.25) {
        d = moai(q, id);
        if (d < 0.15) {
            d += (noise3(p * 2.6 + vec3f(id * 5.0)) - 0.5) * 0.13 + (noise3(p * 8.5) - 0.5) * 0.04;
        }
    }
    d = min(d, select(1e5, 1.85 - abs(p.z - zc), abs(p.z) < 5.6));
    MAT = 0;
    SID = id;
    var tr: vec2f;
    if (p.x < 0.0) {
        tr = tree(p, vec3f(-5.1, 0.0, -0.1));
    } else {
        tr = tree(p, vec3f(5.1, 0.0, select(-2.8, 2.8, p.z > 0.0)));
        tr.x = min(tr.x, abs(p.z) + 0.7);
    }
    tr.x = min(tr.x, ax + 2.5);
    if (tr.x < d) { d = tr.x; MAT = i32(tr.y); }
    return d;
}

fn nrm(p: vec3f) -> vec3f {
    let k = vec2f(1.0, -1.0);
    let e = 0.003;
    return normalize(k.xyy * map(p + k.xyy * e) + k.yyx * map(p + k.yyx * e) + k.yxy * map(p + k.yxy * e) + k.xxx * map(p + k.xxx * e));
}

fn soft(p: vec3f, ld: vec3f) -> f32 {
    var s = 1.0;
    var t = 0.05;
    for (var i = 0; i < 14; i = i + 1) {
        let q = p + ld * t;
        if (q.y > 4.5) { break; }
        let d = map(q);
        s = min(s, 8.0 * d / t);
        t += clamp(d, 0.06, 0.6);
        if (s < 0.02) { break; }
    }
    return clamp(s, 0.0, 1.0);
}

fn lit(p: vec3f, n: vec3f, base: vec3f, ao: f32) -> vec3f {
    let ld = sun_dir();
    var s = sun_at(p) * max(dot(n, ld), 0.0);
    if (s > 0.01) { s *= soft(p + n * 0.03, ld); }
    let amb = mix(vec3f(0.10, 0.09, 0.07), vec3f(0.20, 0.19, 0.17), n.y * 0.5 + 0.5) + vec3f(0.04, 0.06, 0.03);
    return base * (SUNC * s + amb * ao * 1.4);
}

fn floor_base(p: vec3f) -> vec3f {
    let row = floor(p.z / 1.4);
    let u = p.x / 1.6 + 0.5 * row;
    let fu = fract(u);
    let fv = fract(p.z / 1.4);
    let edge = min(min(fu, 1.0 - fu) * 1.6, min(fv, 1.0 - fv) * 1.4);
    let hs = hash12(vec2f(floor(u), row));
    var c = vec3f(0.36, 0.34, 0.31) * (0.7 + 0.3 * hs) * (0.8 + 0.4 * noise3(vec3f(p.xz * 4.0, 0.0)));
    let ck = smoothstep(0.02, 0.0, abs(noise3(vec3f(p.xz * 1.6, 5.0)) - 0.5));
    let joint = smoothstep(0.03, 0.0, edge);
    let mn = noise3(p * 9.0);
    let mossc = mix(vec3f(0.08, 0.14, 0.04), vec3f(0.22, 0.32, 0.08), mn);
    c = mix(c, c * 0.35, ck * 0.6);
    c = mix(c, mossc, clamp(joint + ck, 0.0, 1.0) * 0.85);
    let dT = min(length(p.xz - vec2f(-5.1, -0.1)), min(length(p.xz - vec2f(5.1, -2.8)), length(p.xz - vec2f(5.1, 2.8))));
    let g = smoothstep(2.6, 0.6, dT + (noise3(vec3f(p.xz * 2.0, 9.0)) - 0.5) * 1.2);
    c = mix(c, mossc * 1.2, g);
    return c;
}

fn wall(pe: vec3f, rd: vec3f) -> vec3f {
    let onz = abs(pe.z) > abs(pe.x);
    let along = select(pe.z, pe.x, onz);
    let n = select(vec3f(-sign(pe.x), 0.0, 0.0), vec3f(0.0, 0.0, -sign(pe.z)), onz);
    let face = select(select(1.0, 2.0, pe.x > 0.0), select(3.0, 4.0, pe.z > 0.0), onz);
    let row = floor(pe.y / 0.45);
    let u = along / 0.9 + 0.5 * row + hash12(vec2f(row, face)) * 0.3;
    let fu = fract(u);
    let fv = fract(pe.y / 0.45);
    let edge = min(min(fu, 1.0 - fu) * 0.9, min(fv, 1.0 - fv) * 0.45);
    let bh = hash12(vec2f(floor(u), row + face * 17.0));
    let w = vec3f(along, pe.y, face * 3.1);
    var c = vec3f(0.36, 0.33, 0.30) * (0.65 + 0.35 * bh) * (0.6 + 0.7 * fbm3(w * 1.5));
    c *= mix(0.45, 1.0, smoothstep(0.0, 0.025, edge));
    let ck = smoothstep(0.018, 0.0, abs(noise3(w * vec3f(0.9, 0.6, 1.0)) - 0.5));
    c *= 1.0 - 0.6 * ck;
    let mn = noise3(w * 2.2);
    let mossc = mix(vec3f(0.07, 0.13, 0.04), vec3f(0.2, 0.3, 0.08), mn);
    c = mix(c, mossc, smoothstep(1.4, 0.2, pe.y + (mn - 0.5) * 1.5) * 0.85);
    let vine = smoothstep(0.6, 0.7, noise3(vec3f(along * 2.2, pe.y * 0.2, face * 5.0))) * smoothstep(1.2, 3.6, pe.y + mn);
    c = mix(c, mossc * 1.3, vine);
    let s = sun_at(pe) * max(dot(n, sun_dir()), 0.0);
    var col = c * (SUNC * s + vec3f(0.17, 0.155, 0.13));
    let br = smoothstep(0.62, 0.68, noise3(vec3f(along * 0.5, pe.y * 0.7, face * 7.0))) * smoothstep(2.5, 3.4, pe.y);
    let leaf = smoothstep(0.45, 0.6, noise3(rd * 6.0 + vec3f(face)));
    let outside = mix(sky(rd), vec3f(0.22, 0.36, 0.1) * (0.6 + 0.8 * noise3(rd * 18.0)) * 2.2, leaf);
    col = mix(col, outside, br);
    return col;
}

fn ceiling(pe: vec3f, rd: vec3f) -> vec3f {
    let hv = hole(pe.xz);
    var c = vec3f(0.2, 0.18, 0.16) * (0.6 + 0.7 * noise3(vec3f(pe.xz * 2.5, 1.0)));
    let bm = smoothstep(0.4, 0.43, abs(fract(pe.z / 2.0) - 0.5));
    c *= 1.0 - 0.5 * bm;
    c *= vec3f(0.5, 0.46, 0.4) + SUNC * 0.15 * hv;
    let ln = noise3(vec3f(pe.xz * 4.0, 3.0));
    let fringe = smoothstep(0.15, 0.4, hv) * smoothstep(0.4, 0.6, ln);
    c = mix(c, vec3f(0.18, 0.3, 0.08) * (0.7 + ln), fringe);
    let open = smoothstep(0.5, 0.62, hv + (ln - 0.5) * 0.25);
    let lv = smoothstep(0.55, 0.62, noise3(vec3f(rd.xz / max(rd.y, 0.05) * 3.0, time() * 0.1)));
    let skyc = mix(sky(rd) * 1.3, vec3f(0.25, 0.42, 0.1) * 2.0, lv * 0.8);
    return mix(c, skyc, open);
}

fn shafts(ro: vec3f, rd: vec3f, tend: f32, n: i32) -> vec3f {
    let L = min(tend, 16.0);
    let dt = L / f32(n);
    let j = hash13(rd * 913.0 + vec3f(0.3, 0.7, 0.1));
    var acc = 0.0;
    var dust = 0.0;
    let tm = time();
    for (var i = 0; i < 16; i = i + 1) {
        if (i >= n) { break; }
        let p = ro + rd * ((f32(i) + j) * dt);
        if (p.y > 4.5 || p.y < 0.0) { continue; }
        let b = sun_at(p);
        acc += b * dt;
        let m = noise3(p * 16.0 + vec3f(tm * 0.21, -tm * 0.13 + sin(tm * 0.3), tm * 0.17));
        dust += b * smoothstep(0.8, 0.95, m);
    }
    return SUNC * (acc * 0.045 + dust * 0.35);
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let q = quality();
    let tf = plane_y(ro, rd, 0.0);
    let floor_ok = tf >= tmin && tf <= tmax;
    var tend = tmax;
    if (floor_ok) { tend = tf; }
    let sl = box_span(ro, rd, vec3f(-6.0, 0.0, -6.0), vec3f(-2.8, 4.5, 6.0));
    let sr = box_span(ro, rd, vec3f(2.8, 0.0, -6.0), vec3f(6.0, 4.5, 6.0));
    var t0 = 1e5;
    var t1 = -1.0;
    if (sl.x <= sl.y && sl.y > tmin) { t0 = min(t0, sl.x); t1 = max(t1, sl.y); }
    if (sr.x <= sr.y && sr.y > tmin) { t0 = min(t0, sr.x); t1 = max(t1, sr.y); }
    t0 = max(t0, tmin);
    t1 = min(t1, tend);
    var hit = false;
    var t = t0;
    if (t0 < t1) {
        let steps = i32(mix(40.0, 90.0, q));
        for (var i = 0; i < 90; i = i + 1) {
            if (i >= steps) { break; }
            let d = map(ro + rd * t);
            if (d < 0.0015 + 0.001 * t) { hit = true; break; }
            t += d * 0.8;
            if (t > t1) { break; }
        }
    }
    var col = vec3f(0.0);
    var th = horizon_t(tmax);
    if (hit) {
        th = min(t, tmax);
        let p = ro + rd * t;
        let m = MAT;
        let sid = SID;
        let n = nrm(p);
        let a1 = clamp(map(p + n * 0.07) / 0.07, 0.0, 1.0);
        let a2 = clamp(map(p + n * 0.3) / 0.3, 0.0, 1.0);
        let ao = clamp(0.5 * (a1 + a2), 0.12, 1.0) * (0.55 + 0.45 * smoothstep(0.0, 1.5, p.y));
        var base = vec3f(0.0);
        if (m == 0) {
            let nz = noise3(p * 3.0 + vec3f(sid * 2.0));
            let nf = noise3(p * 15.0);
            let hs = hash12(vec2f(sid, 2.0));
            base = mix(vec3f(0.42, 0.40, 0.37), vec3f(0.46, 0.39, 0.32), hs) * (0.6 + 0.5 * nz) * (0.8 + 0.35 * nf);
            let li = smoothstep(0.62, 0.78, noise3(p * 5.0 + vec3f(sid * 3.0, 1.0, 0.0)));
            base = mix(base, vec3f(0.55, 0.47, 0.22), li * 0.5);
            base = mix(base, vec3f(0.14, 0.22, 0.07), smoothstep(0.45, 0.9, n.y) * smoothstep(0.35, 0.65, nz));
        } else if (m == 1) {
            base = vec3f(0.18, 0.13, 0.09) * (0.6 + 0.6 * noise3(vec3f(p.x * 20.0, p.y * 2.0, p.z * 20.0)));
        } else {
            base = mix(vec3f(0.10, 0.22, 0.05), vec3f(0.32, 0.45, 0.12), noise3(p * 6.0));
        }
        col = lit(p, n, base, ao);
        if (m == 2) { col += base * SUNC * 0.25 * sun_at(p); }
    } else if (floor_ok) {
        th = tf;
        let p = ro + rd * tf;
        let base = floor_base(p);
        let ao = clamp(0.25 + 0.75 * map(p + vec3f(0.0, 0.35, 0.0)) / 0.35, 0.2, 1.0);
        col = lit(p, vec3f(0.0, 1.0, 0.0), base, ao);
    } else {
        let pe = ro + rd * th;
        if (pe.y > 4.4) { col = ceiling(pe, rd); } else { col = wall(pe, rd); }
    }
    // birds drifting under the broken roof
    let tm = time();
    for (var k = 0; k < 4; k = k + 1) {
        let fk = f32(k);
        let hb = hash12(vec2f(fk * 3.7, 4.0));
        let dir = select(1.0, -1.0, (k % 2) == 1);
        let a = tm * (0.3 + 0.2 * hb) * dir + fk * 1.7;
        let R = 1.6 + 2.0 * hb;
        let flap = sin(tm * (8.0 + 4.0 * hb) + fk * 2.0);
        let bc = vec3f(cos(a) * R + 0.7 * sin(tm * 0.23 + fk), 3.2 + 0.9 * hb + 0.06 * flap, sin(a) * R - 0.5);
        if (abs(rd.y) < 1e-4) { continue; }
        let tb = (bc.y - ro.y) / rd.y;
        if (tb < tmin || tb > th) { continue; }
        let pt = ro + rd * tb;
        let fw = vec2f(-sin(a), cos(a)) * dir;
        let l = pt.xz - bc.xz;
        let lx = abs(dot(l, vec2f(fw.y, -fw.x)));
        let ly = dot(l, fw);
        let span = 0.5 * (0.6 + 0.4 * flap);
        let wl = ly + 0.3 * lx - 0.05;
        let thk = 0.1 * (1.0 - lx / max(span, 0.05));
        let dw = max(lx - span, abs(wl) - thk);
        let db = length(vec2f(lx * 3.0, ly - 0.02)) - 0.16;
        let cov = smoothstep(0.015, 0.0, min(dw, db * 0.4));
        if (cov > 0.0) {
            let bcol = vec3f(0.06, 0.045, 0.035) + SUNC * 0.1 * sun_at(bc);
            col = mix(col, bcol, cov);
            if (cov > 0.5) { th = tb; }
        }
    }
    col = mix(col, vec3f(0.30, 0.26, 0.19), 1.0 - exp(-th * 0.03));
    col += shafts(ro, rd, th, i32(mix(6.0, 12.0, q)));
    return Hit(tone(col * 1.1), th);
}

// Hall of Obelisks: arched windows onto five eras, each with a black obelisk; a glass floor over the abyss.
struct Era { top: vec3f, hor: vec3f, gnd: vec3f, lc: vec3f, ld: vec3f, gh: f32, fog: f32, oh: f32, hill: f32, cloud: f32 };
var<private> LM: i32;

fn era(id: i32) -> Era {
    var e = Era(vec3f(0.12, 0.13, 0.15), vec3f(0.30, 0.30, 0.32), vec3f(0.09, 0.09, 0.10), vec3f(1.0, 0.55, 0.25), normalize(vec3f(0.3, 0.45, 0.6)), -1.0, 0.045, 11.0, 0.08, 1.0);
    switch id {
        case 0: { e = Era(vec3f(0.50, 0.42, 0.34), vec3f(0.95, 0.70, 0.45), vec3f(0.66, 0.47, 0.28), vec3f(1.0, 0.72, 0.42), normalize(vec3f(0.6, 0.3, 0.45)), -0.6, 0.012, 9.0, 0.04, 0.15); }
        case 1: { e = Era(vec3f(0.30, 0.34, 0.37), vec3f(0.56, 0.59, 0.58), vec3f(0.17, 0.17, 0.13), vec3f(0.75, 0.75, 0.78), normalize(vec3f(-0.5, 0.5, 0.6)), -0.4, 0.06, 7.5, 0.05, 0.9); }
        case 2: { e = Era(vec3f(0.16, 0.30, 0.60), vec3f(0.78, 0.74, 0.62), vec3f(0.48, 0.42, 0.22), vec3f(1.0, 0.82, 0.55), normalize(vec3f(-0.4, 0.22, 0.85)), -1.2, 0.008, 10.0, 0.012, 0.7); }
        case 3: { e = Era(vec3f(0.40, 0.50, 0.66), vec3f(0.80, 0.84, 0.90), vec3f(0.80, 0.85, 0.92), vec3f(1.0, 0.75, 0.55), normalize(vec3f(0.5, 0.1, 0.85)), -0.5, 0.03, 8.0, 0.10, 0.4); }
        default: { }
    }
    return e;
}

fn stone(uv: vec2f) -> vec3f {
    let row = floor(uv.y / 0.5);
    let xx = uv.x / 1.1 + row * 0.5;
    let cell = vec2f(floor(xx), row);
    let f = vec2f(fract(xx), fract(uv.y / 0.5));
    let j = min(min(f.x, 1.0 - f.x) * 2.2, min(f.y, 1.0 - f.y));
    let v = 0.75 + 0.35 * hash12(cell);
    return vec3f(0.085, 0.095, 0.115) * v * mix(0.45, 1.0, smoothstep(0.0, 0.06, j));
}

fn sd_ob(p: vec3f, h: f32, w0: f32, w1: f32) -> f32 {
    let q = max(abs(p.x), abs(p.z));
    let w = mix(w0, w1, clamp(p.y / h, 0.0, 1.0));
    let shaft = max(q - w, max(-p.y, p.y - h));
    let ph = w1 * 1.5;
    let py = p.y - h;
    let pyr = max(q - w1 * (1.0 - py / ph), max(-py, py - ph));
    return min(shaft, pyr) * 0.7;
}

fn lmap(p: vec3f, id: i32, e: Era) -> f32 {
    LM = 0;
    let base = vec3f(0.0, e.gh, 24.0);
    var d = sd_ob(p - base, e.oh, 0.62 - f32(id) * 0.04, 0.36 + f32(id) * 0.01);
    var x = 1e5;
    if (id == 0) {
        for (var i = 0; i < 3; i++) {
            let fi = f32(i);
            let q = p - base - vec3f(-7.0 + fi * 6.5, 0.0, -4.0 + fi * 3.0);
            let hh = 1.2 + fi * 1.3 - fi * fi * 0.5;
            x = min(x, max(length(q.xz) - 0.5, abs(q.y - hh * 0.5) - hh * 0.5));
        }
    } else if (id == 1) {
        x = min(sd_box(p - base - vec3f(-6.0, 1.2, -3.0), vec3f(0.5, 1.2, 0.3)), sd_box(p - base - vec3f(5.0, 0.9, 1.0), vec3f(0.4, 0.9, 0.35)));
    } else if (id == 3) {
        for (var i = 0; i < 2; i++) {
            let fi = f32(i);
            let q = p - base - vec3f(-5.0 + fi * 9.0, 0.0, -5.0 + fi * 2.0);
            x = min(x, max(max(abs(q.x) - 1.2, -q.y), abs(q.z) * 0.85 + q.y * 0.53 - 0.9));
        }
    } else if (id == 4) {
        for (var i = 0; i < 2; i++) {
            let fi = f32(i);
            let q = p - base - vec3f(-9.0 + fi * 17.0, 0.0, 10.0 + fi * 4.0);
            let hh = 15.0 + fi * 4.0;
            x = min(x, max(length(q.xz) - 0.9 + q.y * 0.02, abs(q.y - hh * 0.5) - hh * 0.5));
        }
    }
    if (x < d) { LM = 1; d = x; }
    return d;
}

fn land(id: i32, lo: vec3f, lr: vec3f) -> vec3f {
    let e = era(id);
    let fid = f32(id);
    let tt = time();
    let up = max(lr.y, 0.0);
    var col = mix(e.hor, e.top, pow(up, 0.6));
    let sd = max(dot(lr, e.ld), 0.0);
    col += e.lc * (pow(sd, 6.0) * 0.3 + pow(sd, 300.0) * 1.5);
    if (lr.y > 0.0) {
        let cp = vec2f(lr.x, lr.z) / (lr.y + 0.08);
        let cn = noise3(vec3f(cp * 0.7 + vec2f(tt * 0.06, 0.0), fid * 3.0)) * 0.65 + noise3(vec3f(cp * 1.9 + vec2f(tt * 0.1, 0.0), fid * 3.0 + 1.0)) * 0.35;
        let cm = smoothstep(0.62 - e.cloud * 0.3, 0.85, cn) * (0.35 + 0.6 * e.cloud);
        let ccol = mix(e.hor * 0.72, e.hor * 1.08 + e.lc * 0.12, smoothstep(0.5, 0.9, cn));
        col = mix(col, ccol, cm * smoothstep(0.0, 0.08, lr.y));
    }
    let az = atan2(lr.x, lr.z);
    let el = lr.y / max(length(lr.xz), 1e-3);
    var hh = e.hill * (0.4 + noise3(vec3f(az * 5.0, fid * 7.0, 0.5)));
    if (id == 4) { hh += abs(az) * 0.3; }
    if (el < hh) { col = mix(e.gnd * 0.5, e.hor, 0.55); }
    var tg = 1e5;
    if (lr.y < 0.0) {
        tg = (e.gh - lo.y) / lr.y;
        let gp = lo + lr * tg;
        var g = e.gnd * (0.65 + 0.6 * noise3(vec3f(gp.xz * 0.25, fid)));
        if (id == 0) { g *= 0.85 + 0.15 * sin(gp.x * 0.6 + gp.z * 0.9 + noise3(vec3f(gp.xz * 0.1, 2.0)) * 4.0); }
        if (id == 2) { g *= 0.88 + 0.12 * sin(gp.x * 0.35 + gp.z * 0.2 - tt * 1.8); }
        g *= 0.55 + 0.6 * e.ld.y;
        // the obelisk's long shadow
        let lxz = e.ld.xz;
        let s = dot(vec2f(0.0, 24.0) - gp.xz, lxz) / dot(lxz, lxz);
        let perp = length(gp.xz + lxz * s - vec2f(0.0, 24.0));
        let shd = (1.0 - smoothstep(0.3, 0.8, perp)) * step(0.0, s) * (1.0 - smoothstep(e.oh, e.oh + 1.0, s * e.ld.y));
        g *= 1.0 - 0.55 * shd;
        if (id == 4) { g += vec3f(1.0, 0.5, 0.2) * step(0.985, hash12(floor(gp.xz * 0.7))) * 0.8; }
        col = mix(g, e.hor, 1.0 - exp(-tg * e.fog));
    }
    let sp = box_span(lo, lr, vec3f(-11.0, e.gh - 0.1, 17.0), vec3f(11.0, e.gh + 20.0, 40.0));
    if (sp.x < sp.y && sp.y > 0.0) {
        var t = max(sp.x, 0.0);
        let tend = min(sp.y, tg);
        let n_st = i32(mix(24.0, 48.0, quality()));
        var hit = false;
        for (var i = 0; i < n_st; i++) {
            let d = lmap(lo + lr * t, id, e);
            if (d < 0.01 + t * 0.0015) { hit = true; break; }
            t += d;
            if (t > tend) { break; }
        }
        if (hit) {
            let p = lo + lr * t;
            let m = LM;
            let k = vec2f(1.0, -1.0) * 0.02;
            let n = normalize(k.xyy * lmap(p + k.xyy, id, e) + k.yyx * lmap(p + k.yyx, id, e) + k.yxy * lmap(p + k.yxy, id, e) + k.xxx * lmap(p + k.xxx, id, e));
            let dif = max(dot(n, e.ld), 0.0);
            let rim = pow(1.0 - max(dot(n, -lr), 0.0), 3.0);
            let ry = p.y - e.gh;
            var c = vec3f(0.0);
            if (m == 0) {
                c = vec3f(0.025, 0.025, 0.03) * (e.hor * 1.2 + e.lc * dif * 2.0);
                let hv = normalize(e.ld - lr);
                let glint = 0.6 + 0.4 * sin(tt * 0.7 + fid * 1.7 + ry * 0.3);
                c += e.lc * pow(max(dot(n, hv), 0.0), 30.0) * 0.35 * glint;
                c += e.lc * rim * 0.12 * glint;
                let fc = select(p.x, p.z - 24.0, abs(n.x) > abs(n.z));
                let groove = smoothstep(0.44, 0.49, abs(fract(ry * (0.9 + fid * 0.3)) - 0.5));
                let chan = (1.0 - smoothstep(0.08, 0.13, abs(fc))) * step(1.0, ry) * step(ry, e.oh - 1.0);
                c += e.lc * max(groove * 0.5, chan) * 0.07 * glint;
            } else {
                var base = e.gnd * 0.7;
                if (id == 3) { base = vec3f(0.45, 0.28, 0.14); }
                if (id == 4) { base = vec3f(0.08, 0.06, 0.05); }
                c = base * (e.hor * 0.6 + e.lc * dif * 1.1);
                if (id == 3) { c += vec3f(1.0, 0.55, 0.2) * 0.12 * (0.8 + 0.2 * sin(tt * 7.0)); }
            }
            col = mix(c, e.hor, 1.0 - exp(-t * e.fog));
        }
    }
    // weather on and beyond the glass
    if (id == 4) {
        let rv = vec2f(lo.x * 28.0, lo.y * 1.2 + tt * 7.0);
        let hr = hash12(floor(rv));
        let s = step(0.86, hr) * (1.0 - smoothstep(0.05, 0.2, abs(fract(rv.x) - 0.5))) * fract(rv.y + hr);
        col = mix(col, vec3f(0.55, 0.6, 0.66), s * 0.4);
    }
    if (id == 4 || id == 1) {
        let dv = vec2f(lo.x * 9.0, lo.y * 9.0 + tt * 0.3);
        let hd = hash12(floor(dv));
        let drop = step(0.8, hd) * (1.0 - smoothstep(0.1, 0.25, length(fract(dv) - 0.5)));
        col = mix(col, col * 1.3 + vec3f(0.05), drop * 0.6);
    }
    if (id == 3) {
        let sv = vec2f(lo.x * 10.0 + sin(lo.y * 2.0 + tt) * 0.4, lo.y * 10.0 + tt * 1.2);
        let hs = hash12(floor(sv));
        let fl = step(0.8, hs) * (1.0 - smoothstep(0.08, 0.2, length(fract(sv) - 0.5)));
        col = mix(col, vec3f(0.95, 0.97, 1.0), fl * 0.8);
    }
    if (id == 1) {
        let mn = noise3(vec3f(lo.x * 0.6 + tt * 0.25, lo.y * 1.2, 4.0));
        col = mix(col, e.hor * 1.05, smoothstep(0.4, 0.8, mn) * 0.35);
    }
    return col;
}

fn cmap(p: vec3f) -> f32 {
    let b = vec3f(0.0, 0.85 + 0.08 * sin(time() * 0.6), 0.0);
    var q = p - b;
    let xz = rot2(time() * 0.15) * q.xz;
    q = vec3f(xz.x, q.y, xz.y);
    return sd_ob(q, 2.1, 0.26, 0.17);
}

fn ob_shade(p: vec3f, rd: vec3f) -> vec3f {
    let k = vec2f(1.0, -1.0) * 0.0015;
    let n = normalize(k.xyy * cmap(p + k.xyy) + k.yyx * cmap(p + k.yyx) + k.yxy * cmap(p + k.yxy) + k.xxx * cmap(p + k.xxx));
    let ang = time() * 0.15;
    let b = vec3f(0.0, 0.85 + 0.08 * sin(time() * 0.6), 0.0);
    var q = p - b;
    let qxz = rot2(ang) * q.xz;
    q = vec3f(qxz.x, q.y, qxz.y);
    let nxz = rot2(ang) * n.xz;
    let fc = select(q.x, q.z, abs(nxz.x) > abs(nxz.y));
    let r = reflect(rd, n);
    var env = mix(vec3f(0.02, 0.025, 0.035), vec3f(0.13, 0.15, 0.2), smoothstep(-0.3, 0.7, r.y));
    let sidel = pow(max(abs(r.x), abs(r.z)), 10.0) * smoothstep(-0.15, 0.2, r.y) * (1.0 - smoothstep(0.35, 0.85, r.y));
    env += vec3f(1.0, 0.6, 0.28) * sidel * 0.6;
    let fres = 0.06 + 0.94 * pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    var c = vec3f(0.012, 0.013, 0.017) + env * (0.2 + 0.8 * fres);
    c += vec3f(0.07, 0.09, 0.12) * max(-n.y, 0.0);
    let groove = smoothstep(0.44, 0.49, abs(fract(q.y * 2.2) - 0.5));
    let chan = (1.0 - smoothstep(0.02, 0.035, abs(fc))) * step(0.15, q.y) * step(q.y, 1.9);
    let pulse = exp(-abs(q.y - fract(time() * 0.07) * 2.8) * 2.5);
    c += vec3f(0.5, 0.68, 1.0) * max(groove * 0.6, chan) * (0.04 + 0.5 * pulse) * step(q.y, 2.1);
    return c;
}

fn abyss(pf: vec3f, rd: vec3f) -> vec3f {
    let tx = select(1e5, (select(-2.5, 2.5, rd.x > 0.0) - pf.x) / rd.x, abs(rd.x) > 1e-5);
    let tz = select(1e5, (select(-2.5, 2.5, rd.z > 0.0) - pf.z) / rd.z, abs(rd.z) > 1e-5);
    let ts = min(tx, tz);
    let h = pf + rd * ts;
    let depth = -h.y;
    let lat = select(h.x, h.z, tx < tz);
    var c = stone(vec2f(lat, h.y)) * 2.0 * exp(-depth * 0.22);
    c += vec3f(0.25, 0.3, 0.38) * 0.04 * exp(-depth * 0.3);
    for (var k = 0; k < 4; k++) {
        let ph = fract(f32(k) * 0.25 - time() * 0.03);
        let dk = -0.3 - ph * 9.0;
        let tk = dk / rd.y;
        if (tk < ts) {
            let mp = pf + rd * tk;
            let m = noise3(vec3f(mp.xz * 0.8 + vec2f(time() * 0.05, f32(k) * 3.1), time() * 0.07 + f32(k)));
            let a = smoothstep(0.4, 0.75, m) * sin(PI * ph) * exp(dk * 0.12);
            c = mix(c, vec3f(0.30, 0.35, 0.42), a * 0.45);
        }
    }
    return c;
}

fn floor_col(p: vec3f, rd: vec3f) -> vec3f {
    let m = max(abs(p.x), abs(p.z));
    if (m < 2.5) {
        var c = abyss(p, rd);
        let fp = fract(p.xz / 1.25);
        let bar = min(min(fp.x, 1.0 - fp.x), min(fp.y, 1.0 - fp.y)) * 1.25;
        let fb = min(bar, (2.5 - m) * 0.6);
        let fres = 0.04 + 0.96 * pow(1.0 - abs(rd.y), 5.0);
        c += fres * vec3f(0.10, 0.12, 0.16);
        let fm = 1.0 - smoothstep(0.015, 0.03, fb);
        c = mix(c, vec3f(0.05, 0.045, 0.04) + vec3f(0.12, 0.07, 0.03) * fres, fm);
        return c;
    }
    let f = fract(p.xz / 1.5);
    let cell = floor(p.xz / 1.5);
    let j = min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y));
    var c = vec3f(0.06, 0.066, 0.078) * (0.75 + 0.4 * hash12(cell)) * mix(0.5, 1.0, smoothstep(0.0, 0.025, j));
    let ax = abs(p.x);
    let az = abs(p.z);
    var sp = exp(-(6.0 - ax) * 0.55) * exp(-(az - 3.7) * (az - 3.7) * 0.9);
    sp += exp(-(6.0 - az) * 0.55) * exp(-(ax - 3.7) * (ax - 3.7) * 0.9);
    c += vec3f(0.75, 0.6, 0.45) * sp * 0.09;
    c += vec3f(0.05, 0.07, 0.1) * exp(-(m - 2.5) * 2.0);
    c += vec3f(0.03, 0.035, 0.045) * pow(1.0 - abs(rd.y), 5.0);
    c *= 0.6 + 0.4 * smoothstep(0.0, 0.8, 6.0 - m);
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    var col = vec3f(0.0);
    var th = horizon_t(tmax);
    var done = false;
    let sp = box_span(ro, rd, vec3f(-0.42, 0.7, -0.42), vec3f(0.42, 3.45, 0.42));
    if (sp.x < sp.y && sp.y > tmin && sp.x < tmax) {
        var t = max(sp.x, tmin);
        let te = min(sp.y, tmax);
        let n_st = i32(mix(28.0, 64.0, quality()));
        for (var i = 0; i < n_st; i++) {
            let d = cmap(ro + rd * t);
            if (d < 0.001) { done = true; break; }
            t += d;
            if (t > te) { break; }
        }
        if (done) { col = ob_shade(ro + rd * t, rd); th = t; }
    }
    if (!done) {
        let tf = plane_y(ro, rd, 0.0);
        if (tf >= tmin && tf <= tmax + 0.01) {
            col = floor_col(ro + rd * tf, rd);
            th = min(tf, horizon_t(tmax));
        } else {
            let pe = ro + rd * th;
            if (pe.y > ROOM_HEIGHT - 0.03) {
                let g = abs(fract(pe.xz / 2.0) - 0.5);
                let beam = smoothstep(0.42, 0.46, max(g.x, g.y));
                col = vec3f(0.025, 0.028, 0.035) * (1.0 - 0.5 * beam) + vec3f(0.04, 0.05, 0.065) * exp(-length(pe.xz) * 0.45);
            } else {
                let ax = abs(pe.x);
                let az = abs(pe.z);
                var O = vec3f(0.0, 0.0, select(1.0, -1.0, pe.z < 0.0));
                var wall = select(2, 0, pe.z < 0.0);
                if (ax > az) { O = vec3f(select(-1.0, 1.0, pe.x > 0.0), 0.0, 0.0); wall = select(3, 1, pe.x > 0.0); }
                let U = vec3f(-O.z, 0.0, O.x);
                let lat = dot(pe, U);
                let side = select(0, 1, lat > 0.0);
                var ids = array<i32, 8>(0, 3, 2, 4, 1, 0, 4, 2);
                let id = ids[wall * 2 + side];
                let lu = lat - select(-3.7, 3.7, lat > 0.0);
                let y = pe.y;
                let dr = max(abs(lu) - 0.8, max(0.5 - y, y - 3.3));
                let dcirc = max(length(vec2f(lu, y - 3.3)) - 0.8, 3.3 - y);
                let dw = min(dr, dcirc);
                let e = era(id);
                if (dw < 0.0) {
                    let lr = vec3f(dot(rd, U), rd.y, dot(rd, O));
                    let lo = vec3f(lu, y, 0.0);
                    var c = land(id, lo, lr) * 0.88 + vec3f(0.02, 0.025, 0.03);
                    let my = abs(fract((y - 0.5) / 0.7 + 0.5) - 0.5) * 0.7;
                    let bar = min(abs(lu), my);
                    let mul = 1.0 - smoothstep(0.012, 0.024, bar);
                    col = mix(c, vec3f(0.02, 0.018, 0.016) + e.lc * 0.08, mul);
                } else {
                    var c = stone(vec2f(lat, y));
                    let jamb = 1.0 - smoothstep(0.0, 0.2, dw);
                    c = mix(c, c * 1.6 + e.lc * 0.18, jamb);
                    c += mix(e.lc, vec3f(0.5, 0.6, 0.75), 0.3) * 0.06 * exp(-dw * 1.3);
                    c *= 0.45 + 0.55 * smoothstep(0.0, 1.2, y);
                    c *= 1.0 - 0.45 * smoothstep(3.6, 4.5, y);
                    col = c;
                }
            }
        }
    }
    // mist rising from the abyss through the glass
    let rdl = max(dot(rd.xz, rd.xz), 1e-5);
    let tc = clamp(-dot(ro.xz, rd.xz) / rdl, tmin, th);
    let pc = ro + rd * tc;
    let rr = dot(pc.xz, pc.xz);
    let dens = exp(-rr * 0.35) * exp(-max(pc.y, 0.0) * 0.6) * (0.5 + 0.7 * noise3(vec3f(pc.xz * 1.2, pc.y * 1.3 - time() * 0.35)));
    col += vec3f(0.22, 0.27, 0.34) * dens * 0.45;
    return Hit(tone(col * 1.5), th);
}

// Two mirror dodecahedra, one ABOVE (chiral hand A) and one BELOW (hand B, its
// true mirror), reflected across eye level. Vertices are folded in 4D by a
// quasiperiodic golden double rotation, then normalized onto the 3-sphere and
// STEREOGRAPHICALLY projected, so the figure turns inside-out through infinity.
// A 5-fold quasicrystal fills the void; five Hopf-fibration rings link the two
// figures; 23 motes ride a (5,2) torus knot. Heartbeat on param(0).x.

fn h_rot(p: vec2f, a: f32) -> vec2f {
  let c = cos(a); let s = sin(a);
  return vec2f(c * p.x - s * p.y, s * p.x  * p.y);
}

// quasiperiodic Clifford double rotation (planes (x,w),(y,z) in ratio phi)
fn rot4(p: vec4f, t: f32) -> vec4f {
  var q = p;
  let a = t * 0.30;
  let b = t * 0.30 * 1.6180339887;
  var r = h_rot(vec2f(q.x, q.w), a);              q.x = r.x; q.w = r.y;
  r = h_rot(vec2f(q.y, q.z), b);                  q.y = r.x; q.z = r.y;
  r = h_rot(vec2f(q.z, q.w), t * 0.12 + 2.0);     q.z = r.x; q.w = r.y;
  return q;
}

fn quasi(uv: vec2f, t: f32) -> f32 {
  var s = 0.0;
  for (var k: i32 = 0; k < 5; k = k + 1) {
    let ang = PI  ;

  }
  return s;
}

fn h_seg(ro: vec3f, rd: vec3f, a: vec3f, b: vec3f) -> f32 {
  let v = b - a;
  let cc = dot(v, v);
  let w0 = ro - a;
  let bb = dot(rd, v);
  let dd = dot(rd, w0);
  let ee = dot(v, w0);
  let D = max(cc - bb * bb, 1e-6);
  let s = clamp((ee - bb * dd) / D, 0.0, 1.0);
  let ps = a + s * v;
  let t = max(dot(ps - ro, rd), 0.0);
  return length(ro  * rd - ps);
}

fn dfac(w: f32) -> f32 { return 0.35  * smoothstep(-1.0, 1.0, w); }

fn cage(o: vec3f, rd: vec3f, pv: array<vec3f,20>, wd: array<f32,20>, de: array<vec2<i32>,30>, col: vec3f, T: f32) -> vec3f {
  var g = vec3f(0.0);
  for (var e: i32 = 0; e < 30; e = e + 1) {
    let ia = de[e].x; let ib = de[e].y;
    let d = h_seg(o, rd, pv[ia], pv[ib]);
    let df = dfac(0.5 * (wd[ia] + wd[ib]));
    let flow = 0.7 + 0.6 * sin(T * 3.0 + f32(e) * 0.8);
    g += col * df * flow ;   // fatter so it survives low-res
  }
  return g;
}

fn hand(o: vec3f, rd: vec3f, pv: array<vec3f,20>, wd: array<f32,20>, tt: array<vec4<i32>,5>, tint: vec3f) -> vec3f {
  var g = vec3f(0.0);
  let k = 0.00085;
  for (var e: i32 = 0; e < 5; e = e + 1) {
    let q = tt[e];
    let a = pv[q.x]; let b = pv[q.y]; let c = pv[q.z]; let d = pv[q.w];
    let tn = tint * 0.25 ;
    let d0 = h_seg(o,rd,a,b); let d1 = h_seg(o,rd,a,c); let d2 = h_seg(o,rd,a,d);
    let d3 = h_seg(o,rd,b,c); let d4 = h_seg(o,rd,b,d); let d5 = h_seg(o,rd,c,d);
    g += tn * (k + k/(d1*d1+0.0009) + k/(d2*d2+0.0009)
             + k/(d3*d3+0.0009) + k/(d4*d4+0.0009) + k/(d5*d5+0.0009));
  }
  return g;
}

// five linked rings (Hopf-fibration flavored) threading the gap
fn hopf(o: vec3f, rd: vec3f, T: f32) -> vec3f {
  var g = vec3f(0.0);
  let Rc = 2.1; let rr = 1.2;
  for (var j: i32 = 0; j < 5; j = j + 1) {
    let a = f32(j) * TAU / 5.0 + T * 0.05;
    let ca = cos(a); let sa = sin(a);
    let C = vec3f(Rc * ca, 0.0, Rc * sa);
    let n = vec3f(-sa, 1.15, ca);
    let u = normalize(cross(n, vec3f(0.0, 1.0, 0.0)));
    let v = cross(n, u);
    var prev = C + rr * u;
    for (var s: i32 = 1; s <= 14; s = s + 1) {
      let th = f32(s)  * TAU;
      let cur = C + rr * (u * th + v * sin(th));
      let d = h_seg(o, rd, prev, cur);

      prev = cur;
    }
  }
  return g;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
  let T = time();
  let CY = 2.4;             // mirror plane (eye level)
  let sep = .7;            // vertical gap between the two figures

  var bpm = param(0).x;
  if (bpm < 20.0) { bpm = 72.0; }
  let cyc = 6.0 / bpm;
  let pb = fract(T / cyc);
  let dubPhase = clamp(0.26 / cyc, 0.05, 0.4);
  let beat = exp(-pow(pb / 0.045, 2.0)) + 0.6 * exp(-pow((pb - dubPhase) / 0.05, 2.0));
  // time reverses between lub and dub: a triangle bump (0 at lub, 1 at dub, 0 at
  // cycle end) subtracted from the clock -> rewind in [lub,dub], fast-forward after.
  let bump = select(1.0 - (pb - dubPhase) / (1.0 - dubPhase), pb / dubPhase, pb < dubPhase);
  let Teff = T - 0.6 * cyc * bump;

  let ph = 1.618034; let iv = 0.618034;
  var dv: array<vec3f, 20> = array<vec3f, 20>(
    vec3f(1.0,1.0,1.0), vec3f(1.0,1.0,-1.0), vec3f(1.0,-1.0,1.0), vec3f(1.0,-1.0,-1.0),
    vec3f(-1.0,1.0,1.0), vec3f(-1.0,1.0,-1.0), vec3f(-1.0,-1.0,1.0), vec3f(-1.0,-1.0,-1.0),
    vec3f(0.0,iv,ph), vec3f(iv,ph,0.0), vec3f(ph,0.0,iv),
    vec3f(0.0,iv,-ph), vec3f(iv,-ph,0.0), vec3f(-ph,0.0,iv),
    vec3f(0.0,-iv,ph), vec3f(-iv,ph,0.0), vec3f(ph,0.0,-iv),
    vec3f(0.0,-iv,-ph), vec3f(-iv,-ph,0.0), vec3f(-ph,0.0,-iv)
  );
  var de: array<vec2<i32>, 30> = array<vec2<i32>, 30>(
    vec2<i32>(0,8),vec2<i32>(0,9),vec2<i32>(0,10),vec2<i32>(1,9),vec2<i32>(1,1),
    vec2<i32>(1,16),vec2<i32>(2,1),vec2<i32>(2,12),vec2<i32>(2,14),vec2<i32>(3,2),
    vec2<i32>(3,6),vec2<i32>(3,17),vec2<i32>(4,8),vec2<i32>(4,13),vec2<i32>(4,15),
    vec2<i32>(5,11),vec2<i32>(5,15),vec2<i32>(5,1),vec2<i32>(6,13),vec2<i32>(6,14),
    vec2<i32>(6,18),vec2<i32>(7,17),vec2<i32>(7,18),vec2<i32>(7,1),vec2<i32>(8,4),
    vec2<i32>(9,15),vec2<i32>(1,6),vec2<i32>(11,17),vec2<i32>(12,18),vec2<i32>(13,19)
  );
  // hand A: five tetrahedra (hand B is its mirror, drawn by reflecting the ray)
  var tA: array<vec4<i32>, 5> = array<vec4<i32>, 5>(
    vec4<i32>(0,3,5,6), vec4<i32>(1,8,12,1), vec4<i32>(2,9,13,17), vec4<i32>(4,1,11,8), vec4<i32>(7,14,15,16)
  );

  // fold in 4D -> onto the 3-sphere -> stereographic projection
  let Sproj = 1.15 ;
  var pv: array<vec3f, 20>;
  var wd: array<f32, 20>;
  for (var i: i32 = 0; i < 20; i = i + 1) {
    let r = rot4(vec4f(dv[i], 0.0), Teff);
    let u = normalize(r);
    let den = max(1.0 - u.w, 0.22);           // clamp so infinity stays bounded
    wd[i] = u.w;
    pv[i] = u.xyz ;
  }

  let hue = 0.5 + 0.5 * sin(Teff * 0.25);
  let cageCol = mix(vec3f(0.2, 0.40, 1.05), vec3f(1.05, 0.42, 0.92), hue);
  let warm = vec3f(1.05, 0.40, 0.80);
  let cool = vec3f(0.35, 0.88, 1.3);

  // ABOVE: hand A
  let TOP = vec3f(0.0, CY + sep, 0.0);
  let oa = ro - TOP;
  var glow = cage(oa, rd, pv, wd, de, cageCol, Teff) + hand(oa, rd, pv, wd, tA, warm);

  // BELOW: reflect the ray across y = CY -> the mirror figure (hand B), cooler
  let rob = vec3f(ro.x, 2.0 * CY - ro.y, ro.z);
  let rdb = vec3f(rd.x, -rd.y, rd.z);
  let ob = rob - TOP;
  glow += cage(ob, rdb, pv, wd, de, cageCol * vec3f(0.8,0.85,1.1), Teff) + hand(ob, rdb, pv, wd, tA, cool);

  // (Hopf rings removed — the quality-gate made them flicker; dropping them
  //  also lightens the scene so the edges hold up.)

  // 23 motes on a (5,2) cinquefoil torus knot, around the mirror plane
  let oc = ro ;
  for (var m: i32 = 0; m < 23; m = m + 1) {
    let th = f32(m) * TAU / 23.0  * 0.12;
    let rrk = 3.1 + 0.95 * cos(2.0 * th);
    let pos = vec3f(rrk * cos(5.0 * th), 1.3 * sin(2.0 * th), rrk * sin(5.0 * th));
    let t = max(dot(pos , rd), 0.0);
    let d = length(oc + t * rd - pos);
    let tw = 0.6 + 0.6 * sin(Teff  + f32(m) * .7);
    glow += vec3f(0.85, 0.55, 1.05)  * (0.0010 / (d  + 0.004));
  }

  glow *= 1.0 + 1.0 * beat;

  // void: dark purple + finer 5-fold quasicrystal + beat flash + stars
  var bg = vec3f(0.02, 0.06, 0.030);
  bg += vec3f(0.10, 0.04, 0.26) * smoothstep(0.0, -0.9, rd.y) * 0.30;
  let qc = quasi(rd.xy * 14.0, T * 0.4);        // moire stays on real time (no rewind)
  var fr = 0.5 + 0.5 * sin(qc * 2.2 + T * 0.3);
  fr = fr * fr;
  bg += vec3f(0.16, 0.05, 0.30) * fr * (0.38  * beat);

  let st = hash13(floor(rd ));


  return Hit(tone(bg + glow), horizon_t(tmax));
}

// Antimemetics Division, restricted lab: a coffee-ringed steel table, lost researchers, diagrams that forget themselves, one calm capybara.
// exemplar v1: pools of light under each tube, glass display boards whose diagrams glow, steam off the coffee, lit haze, a filmic curve.
var<private> FIG: array<vec4f, 4>;
var<private> PFL: array<f32, 6>;
var<private> FL: f32;
var<private> SIP: f32;
var<private> MAT: i32;
var<private> HID: i32;

const CAPY: vec3f = vec3f(2.6, 0.0, 0.8);
const CAPY_YAW: f32 = -0.7;
const LCOL: vec3f = vec3f(0.84, 1.0, 0.88);
const TEAL: vec3f = vec3f(0.25, 0.95, 0.85);
const AMBER: vec3f = vec3f(1.0, 0.62, 0.2);

fn aces(x: vec3f) -> vec3f { return (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14); }

// filmic curve (ACES fit), a soft vignette round the camera's own axis, and a hair of dither
fn tm(c: vec3f, rd: vec3f) -> vec3f {
    let fw = room.inv_rot_proj * vec4f(0.0, 0.0, 0.5, 1.0);
    let vig = 1.0 - 0.3 * smoothstep(0.97, 0.55, dot(rd, normalize(fw.xyz / fw.w)));
    return clamp(aces(max(c, vec3f(0.0)) * vig) + (hash13(rd * 913.7) - 0.5) / 255.0, vec3f(0.0), vec3f(1.0));
}

// light from the tubes at a point: the nearest panel in each row (they meet evenly half way, so no seam)
fn panel_light(p: vec3f) -> f32 {
    let ix = clamp(round(p.x / 3.2), -1.0, 1.0);
    let i0 = i32(ix + 1.0);
    var l = 0.0;
    for (var r = 0; r < 2; r = r + 1) {
        let c = vec3f(ix * 3.2, 4.45, select(-2.2, 2.2, r == 1));
        let v = c - p;
        let d2 = dot(v, v);
        let cs = v.y * inverseSqrt(d2);
        l += PFL[i0 + r * 3] * (cs * cs * cs * 0.85 + 0.15) * 12.0 / (1.0 + d2 * 0.5);
    }
    return l;
}

fn setup() {
    let t = time();
    var P: array<vec2f, 5>;
    P[0] = vec2f(-1.0 + 0.45 * sin(t * 0.23), 1.3 + 0.15 * sin(t * 0.31));
    P[1] = vec2f(0.9 + 0.5 * sin(t * 0.19 + 1.0), -1.35 + 0.12 * cos(t * 0.27));
    P[2] = vec2f(-2.45 + 0.15 * sin(t * 0.29 + 2.0), -0.3 + 0.6 * sin(t * 0.17 + 0.5));
    P[3] = vec2f(0.75 + 0.3 * sin(t * 0.21 + 3.0), 1.5 + 0.1 * sin(t * 0.37));
    P[4] = CAPY.xz;
    for (var i = 0; i < 4; i = i + 1) {
        let fi = f32(i);
        let ph = t / 3.4 + fi * 0.37;
        let k = floor(ph);
        let fr = ph - k;
        let ta = (i + 1 + i32(hash12(vec2f(k, fi + 0.5)) * 3.99)) % 5;
        let tb = (i + 1 + i32(hash12(vec2f(k + 1.0, fi + 0.5)) * 3.99)) % 5;
        let da = P[ta] - P[i];
        let db = P[tb] - P[i];
        let a0 = atan2(da.x, da.y);
        let a1 = atan2(db.x, db.y);
        var dd = a1 - a0;
        dd = dd - TAU * floor((dd + PI) / TAU);
        let yaw = a0 + dd * smoothstep(0.72, 0.95, fr);
        let arm = smoothstep(0.35, 0.85, sin(t * 0.5 + fi * 2.1));
        FIG[i] = vec4f(P[i], yaw, arm);
    }
    var s = 0.0;
    for (var i = 0; i < 6; i = i + 1) {
        var f = 0.93 + 0.04 * sin(t * 0.8 + f32(i) * 1.7);
        if (i == 4) { f *= 0.3 + 0.7 * smoothstep(0.3, 0.42, noise3(vec3f(t * 1.5, 3.0, 0.0))); }
        PFL[i] = f;
        s += f;
    }
    FL = s / 6.0;
    SIP = smoothstep(0.55, 0.85, sin(t * 0.7) * 0.5 + 0.5);
}

fn cap(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

fn sd_ell(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / max(k1, 1e-5);
}

fn sdb2(p: vec2f, b: vec2f) -> f32 {
    let q = abs(p) - b;
    return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0);
}

fn ceil_emit(xz: vec2f, blur: f32) -> vec3f {
    let ix = clamp(round(xz.x / 3.2), -1.0, 1.0);
    let south = xz.y > 0.0;
    let c = vec2f(ix * 3.2, select(-2.2, 2.2, south));
    let q = abs(xz - c) - vec2f(0.38, 0.75);
    let d = max(q.x, q.y);
    let m = 1.0 - smoothstep(-blur, blur + 0.01, d);
    let id = i32(ix + 1.0) + select(0, 3, south);
    return LCOL * PFL[id] * m;
}

fn table(p: vec3f) -> vec2f {
    var d = sd_box(p - vec3f(0.0, 0.9, 0.0), vec3f(1.7, 0.02, 0.6)) - 0.008;
    let lp = vec3f(abs(p.x) - 1.55, p.y - 0.44, abs(p.z) - 0.48);
    d = min(d, sd_box(lp, vec3f(0.03, 0.44, 0.03)));
    d = min(d, sd_box(vec3f(abs(p.x) - 1.55, p.y - 0.15, p.z), vec3f(0.02, 0.02, 0.48)));
    var m = 5.0;
    let m1 = p - vec3f(-0.62, 0.98, 0.28);
    let m2 = p - vec3f(1.05, 0.98, -0.32);
    let dm = min(max(length(m1.xz) - 0.045, abs(m1.y) - 0.055), max(length(m2.xz) - 0.045, abs(m2.y) - 0.055));
    if (dm < d) { d = dm; m = 8.0; }
    let sq = p - vec3f(0.25, 0.95, 0.12);
    let sxz = rot2(0.4) * sq.xz;
    let ds = sd_box(vec3f(sxz.x, sq.y, sxz.y), vec3f(0.15, 0.025, 0.2)) - 0.003;
    if (ds < d) { d = ds; m = 10.0; }
    return vec2f(d, m);
}

fn figure(q: vec3f, arm: f32) -> vec2f {
    let y = q.y;
    let lx = vec3f(abs(q.x), q.y, q.z);
    var d = cap(lx, vec3f(0.1, 0.05, 0.0), vec3f(0.1, 0.75, 0.0), 0.07);
    var m = 2.0;
    let rr = mix(0.27, 0.2, clamp((y - 0.5) / 0.9, 0.0, 1.0));
    var dc = max(length(vec2f(q.x, q.z * 1.4)) - rr, max(0.5 - y, y - 1.4)) * 0.7;
    dc = smin(dc, cap(lx, vec3f(0.0, 1.36, 0.0), vec3f(0.19, 1.36, 0.0), 0.085), 0.08);
    dc = min(dc, cap(q, vec3f(-0.23, 1.34, 0.0), vec3f(-0.27, 0.86, 0.06), 0.06));
    let hand = mix(vec3f(0.27, 0.86, 0.06), vec3f(0.13, 1.62, 0.08), arm);
    let elbow = mix(vec3f(0.29, 1.08, 0.0), vec3f(0.33, 1.3, 0.12), arm);
    dc = min(dc, cap(q, vec3f(0.23, 1.34, 0.0), elbow, 0.058));
    dc = min(dc, cap(q, elbow, hand, 0.052));
    if (dc < d) { d = dc; m = 1.0; }
    var ds = cap(q, vec3f(0.0, 1.4, 0.0), vec3f(0.0, 1.55, 0.01), 0.05);
    ds = min(ds, sd_ell(q - vec3f(0.0, 1.645, 0.01), vec3f(0.1, 0.125, 0.11)));
    ds = min(ds, length(q - vec3f(-0.27, 0.82, 0.07)) - 0.045);
    ds = min(ds, length(q - hand - vec3f(0.0, -0.03, 0.0)) - 0.045);
    if (ds < d) { d = ds; m = 3.0; }
    return vec2f(d, m);
}

fn capy_head(q: vec3f) -> vec3f {
    let hq = q - vec3f(0.0, 1.08, 0.08);
    let r = rot2(0.35 * SIP) * hq.yz;
    return vec3f(hq.x, r.x, r.y);
}

fn capy(q: vec3f) -> vec2f {
    var d = max(length(q.xz) - 0.22, abs(q.y - 0.62) - 0.03);
    d = min(d, max(length(q.xz) - 0.03, q.y - 0.62));
    d = min(d, max(abs(length(q.xz) - 0.17) - 0.015, abs(q.y - 0.25) - 0.015));
    var m = 7.0;
    var db = sd_ell(q - vec3f(0.0, 0.9, -0.02), vec3f(0.22, 0.27, 0.26));
    let hq = capy_head(q);
    db = smin(db, sd_ell(hq - vec3f(0.0, 0.16, 0.12), vec3f(0.12, 0.13, 0.2)), 0.07);
    let ex = vec3f(abs(hq.x), hq.y, hq.z);
    db = min(db, length(ex - vec3f(0.08, 0.28, 0.03)) - 0.035);
    let ax = vec3f(abs(q.x), q.y, q.z);
    db = min(db, cap(ax, vec3f(0.12, 0.75, 0.05), vec3f(0.13, 0.67, 0.22), 0.05));
    let mug = mix(vec3f(0.0, 0.98, 0.36), vec3f(0.0, 1.2, 0.42), SIP);
    db = min(db, cap(ax, vec3f(0.1, 0.98, 0.12), vec3f(0.06, mug.y - 0.02, mug.z - 0.04), 0.04));
    if (db < d) { d = db; m = 6.0; }
    let mq = q - mug;
    let dm = max(length(mq.xz) - 0.055, abs(mq.y) - 0.06);
    if (dm < d) { d = dm; m = 9.0; }
    return vec2f(d, m);
}

fn map(p: vec3f) -> f32 {
    let tb = table(p);
    var d = tb.x;
    MAT = i32(tb.y);
    HID = -1;
    let cl = p - CAPY;
    if (length(cl.xz) - 0.6 < d) {
        let l = rot2(CAPY_YAW) * cl.xz;
        let c = capy(vec3f(l.x, cl.y, l.y));
        if (c.x < d) { d = c.x; MAT = i32(c.y); }
    }
    for (var i = 0; i < 4; i = i + 1) {
        let f = FIG[i];
        let rel = p - vec3f(f.x, 0.0, f.y);
        if (length(rel.xz) - 0.42 < d) {
            let l = rot2(f.z) * rel.xz;
            let g = figure(vec3f(l.x, rel.y, l.y), f.w);
            if (g.x < d) { d = g.x; MAT = i32(g.y); HID = i; }
        }
    }
    return d;
}

fn calc_n(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn fog(c: vec3f, t: f32, rd: vec3f) -> vec3f {
    let hz = mix(vec3f(0.025, 0.032, 0.03), vec3f(0.16, 0.2, 0.17) * FL, smoothstep(-0.3, 0.8, rd.y));
    return mix(c, hz, 1.0 - exp(-t * 0.055));
}

fn tabletop(xz: vec2f, b: vec3f) -> vec3f {
    var c = b * (0.9 + 0.1 * noise3(vec3f(xz.x * 40.0, xz.y * 2.0, 0.0)));
    for (var i = 0; i < 6; i = i + 1) {
        let h = hash33(vec3f(f32(i), 7.0, 3.0));
        let cp = vec2f((h.x - 0.5) * 3.0, (h.y - 0.5) * 1.0);
        let r = length(xz - cp);
        let ring = 1.0 - smoothstep(0.0, 0.012, abs(r - 0.045 - h.z * 0.02));
        c = mix(c, vec3f(0.3, 0.18, 0.08), ring * 0.6 * (0.4 + 0.6 * noise3(vec3f(xz * 30.0, f32(i)))));
    }
    for (var i = 0; i < 7; i = i + 1) {
        let h = hash33(vec3f(f32(i), 2.0, 9.0));
        let cp = vec2f((h.x - 0.5) * 2.9, (h.y - 0.5) * 0.9);
        let q = rot2(h.z * 3.0) * (xz - cp);
        let bq = abs(q) - vec2f(0.105, 0.148);
        if (max(bq.x, bq.y) < 0.0) {
            var pc = vec3f(0.9, 0.9, 0.86);
            let dr = abs(length(q - vec2f(0.0, 0.03)) - 0.05);
            pc = mix(pc, vec3f(0.2, 0.5, 0.5), (1.0 - smoothstep(0.0, 0.004, dr)) * 0.7);
            let dr2 = abs(length(q - vec2f(0.0, 0.03)) - 0.025);
            pc = mix(pc, vec3f(0.7, 0.45, 0.2), (1.0 - smoothstep(0.0, 0.003, dr2)) * 0.6);
            c = pc;
        }
    }
    return c;
}

fn shade_obj(p: vec3f, rd: vec3f, t: f32) -> vec3f {
    let m = MAT;
    let hid = HID;
    let n = calc_n(p);
    let ao = clamp(0.35 + 0.65 * map(p + n * 0.12) / 0.12, 0.3, 1.0);
    var base = vec3f(0.5);
    var spec = 0.04;
    if (m == 1 || m == 2 || m == 3) {
        let f = FIG[max(hid, 0)];
        let rel = p - vec3f(f.x, 0.0, f.y);
        let l = rot2(f.z) * rel.xz;
        let lq = vec3f(l.x, rel.y, l.y);
        let hh = hash12(vec2f(f32(hid) * 3.7, 1.3));
        if (m == 1) {
            base = vec3f(0.86, 0.87, 0.85) * (0.86 + 0.16 * noise3(p * 13.0));
            if (lq.z > 0.0 && abs(lq.x) < 0.01 && lq.y < 1.25) { base *= 0.7; }
            if (lq.z > 0.0 && lq.y > 1.18 && lq.y < 1.42 && abs(lq.x) < (lq.y - 1.18) * 0.45) { base = vec3f(0.42, 0.48, 0.56); }
        } else if (m == 2) {
            base = vec3f(0.11, 0.11, 0.13);
        } else {
            base = mix(vec3f(0.86, 0.66, 0.52), vec3f(0.4, 0.26, 0.18), hh);
            let hair = mix(vec3f(0.08, 0.06, 0.05), vec3f(0.55, 0.53, 0.5), fract(hh * 7.3));
            if (lq.y > 1.56 && (lq.y > 1.69 || lq.z < -0.02)) { base = hair; }
            if (lq.z > 0.06 && length(vec2f(abs(lq.x) - 0.04, lq.y - 1.655)) < 0.022) { base = vec3f(0.04); spec = 0.4; }
        }
    } else if (m == 5) {
        base = vec3f(0.5, 0.53, 0.54);
        spec = 0.5;
        if (n.y > 0.9 && p.y > 0.92) { base = tabletop(p.xz, base); spec = 0.25; }
    } else if (m == 6) {
        let cl = p - CAPY;
        let l = rot2(CAPY_YAW) * cl.xz;
        let hq = capy_head(vec3f(l.x, cl.y, l.y));
        base = vec3f(0.44, 0.29, 0.17) * (0.8 + 0.35 * noise3(p * 30.0));
        if (hq.z > 0.26 && hq.y > 0.0) { base = mix(base, vec3f(0.18, 0.11, 0.07), 0.7); }
        if (length(vec3f(abs(hq.x), hq.y, hq.z) - vec3f(0.1, 0.2, 0.21)) < 0.03) { base = vec3f(0.02); spec = 0.6; }
    } else if (m == 7) {
        base = vec3f(0.15, 0.15, 0.16);
        spec = 0.3;
    } else if (m == 8 || m == 9) {
        base = select(vec3f(0.8, 0.79, 0.75), vec3f(0.3, 0.55, 0.52), m == 9);
        spec = 0.2;
        if (n.y > 0.9) { base = vec3f(0.12, 0.07, 0.04); }
    } else if (m == 10) {
        base = vec3f(0.88, 0.88, 0.84);
    }
    let kd = normalize(vec3f(0.15, 1.0, 0.1));
    let dif = max(dot(n, kd), 0.0);
    let hemi = 0.5 + 0.5 * n.y;
    let pl = panel_light(p);
    var col = base * LCOL * (0.03 + pl * (0.08 + 0.45 * dif) + 0.05 * hemi * FL) * ao;
    let rr = reflect(rd, n);
    if (rr.y > 0.05) {
        let tc = (4.5 - p.y) / rr.y;
        col += ceil_emit((p + rr * tc).xz, 0.15 + tc * 0.06) * spec * ao;
    }
    let fres = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
    // the boards' glow wraps the silhouettes: teal from the long walls, amber from the ends
    col += mix(TEAL, AMBER, smoothstep(-0.5, 0.5, abs(n.x) - abs(n.z))) * fres * 0.16 * ao;
    return fog(col, t, rd);
}

fn lineg(d: f32, w: f32) -> f32 { return exp(-d * d / (w * w)) + 0.3 * exp(-abs(d) * 30.0) + 0.1 * exp(-abs(d) * 7.0); }

fn diagrams(uv: vec2f, id: i32, t: f32) -> vec3f {
    let pi = clamp(floor((uv.x + 1.875) / 1.25), 0.0, 2.0);
    let q = vec2f(uv.x + 1.875 - (pi + 0.5) * 1.25, uv.y);
    let ty = (i32(pi) + id) % 3;
    let seed = f32(id) * 1.37 + pi * 0.71;
    let teal = TEAL;
    let amber = AMBER;
    let w = 0.008;
    var col = vec3f(0.0);
    let r = length(q);
    let a = atan2(q.y, q.x);
    if (ty == 0) {
        let k = clamp(round(r / 0.12), 1.0, 5.0);
        let odd = fract(k * 0.5) > 0.25;
        let dir = select(-1.0, 1.0, odd);
        let g = fract(a / TAU + t * 0.04 * dir * (1.0 + k * 0.3) + seed);
        let on = smoothstep(0.08, 0.13, g);
        let tip = exp(-pow((g - 0.985) * 40.0, 2.0)) * 1.5;
        col += select(teal, amber, odd) * lineg(r - k * 0.12, w) * (on + tip) * step(r, 0.66);
        col += amber * exp(-r * r * 900.0) * (0.6 + 0.4 * sin(t * 2.0));
    } else if (ty == 1) {
        let s = r / 0.075 - a / TAU;
        let d = abs(fract(s) - 0.5) * 0.075;
        let lim = step(r, 0.6) * smoothstep(0.02, 0.05, r);
        col += amber * lineg(d, w) * lim * 0.8;
        let ph = abs(fract(t * 0.06 + seed) * 2.0 - 1.0);
        let pr = 0.06 + ph * 0.5;
        let pa = TAU * fract(pr / 0.075);
        let da = fract((a - pa) / TAU + 0.5) - 0.5;
        col += teal * exp(-da * da * 60.0 - pow((r - pr) / 0.05, 2.0)) * lineg(d, w * 1.8) * lim * 2.5;
    } else {
        let x = q.x;
        let y = q.y;
        let inx = step(-0.5, x) * step(x, 0.55);
        let fa = -0.5 + 1.1 * abs(fract(t * 0.05 + seed) * 2.0 - 1.0);
        let fb = -0.55 + 1.2 * abs(fract(t * 0.043 + seed + 0.5) * 2.0 - 1.0);
        let axx = lineg(y + 0.5, w) * inx * (1.0 - smoothstep(fa - 0.06, fa + 0.06, x));
        let axy = lineg(x + 0.5, w) * step(-0.5, y) * step(y, 0.6) * (1.0 - smoothstep(fb - 0.06, fb + 0.06, y));
        col += vec3f(0.55, 0.7, 0.7) * (axx + axy) * 0.7;
        let ph = x * 7.0 + t * 0.4 + seed;
        let f = 0.2 * sin(ph) + 0.05;
        let fp = 1.4 * cos(ph);
        col += teal * lineg((y - f) / sqrt(1.0 + fp * fp), w) * inx;
        let lq = q - vec2f(0.05, -0.05);
        let A2 = 0.12;
        let r2 = dot(lq, lq);
        let F = r2 * r2 - A2 * (lq.x * lq.x - lq.y * lq.y);
        let gr = vec2f(4.0 * lq.x * r2 - 2.0 * A2 * lq.x, 4.0 * lq.y * r2 + 2.0 * A2 * lq.y);
        col += amber * lineg(F / max(length(gr), 0.02), w) * 0.9;
    }
    let fade = 0.5 + 0.5 * sin(t * 0.25 + seed * 2.0 + q.x * 1.5);
    return col * (0.35 + 0.65 * fade);
}

fn wall_col(pe: vec3f, t: f32) -> vec3f {
    var u = 0.0;
    var wi = 0;
    if (abs(pe.x) > 5.97) {
        wi = select(0, 1, pe.x > 0.0);
        u = pe.z * select(1.0, -1.0, pe.x > 0.0);
    } else {
        wi = select(2, 3, pe.z > 0.0);
        u = pe.x * select(-1.0, 1.0, pe.z > 0.0);
    }
    let y = pe.y;
    let light = 0.035 + panel_light(pe) * 0.42;
    var c = vec3f(0.6, 0.62, 0.6) * (0.92 + 0.08 * noise3(pe * 2.0));
    if (y < 0.12) { c = vec3f(0.17, 0.18, 0.17); }
    c *= LCOL * light;
    let side = select(-1.0, 1.0, u > 0.0);
    let bu = u - side * 3.225;
    let bv = y - 1.65;
    let bq = abs(vec2f(bu, bv)) - vec2f(1.875, 0.7);
    let bd = max(bq.x, bq.y);
    let id = wi * 2 + select(0, 1, u > 0.0);
    if (bd < 0.035) {
        if (bd > 0.0) {
            c = vec3f(0.5, 0.52, 0.54) * light * 1.2;
        } else {
            // dark glass: half-wiped smudges catch the light, the diagrams glow through
            var b = vec3f(0.05, 0.065, 0.065) * light * LCOL;
            let sm = noise3(vec3f(bu * 3.0, bv * 5.0, f32(id) * 3.1));
            b += vec3f(0.05, 0.06, 0.06) * light * smoothstep(0.5, 0.8, sm);
            b += vec3f(0.12, 0.14, 0.13) * light * smoothstep(0.6, 0.0, abs(bv - bu * 0.25 - 0.3)) * 0.5;
            b += diagrams(vec2f(bu, bv), id, t) * 1.7;
            c = b;
        }
    } else {
        c += mix(TEAL, AMBER, f32(id % 2)) * 0.07 * exp(-bd * 4.0);
        if (abs(bv + 0.75) < 0.022 && abs(bu) < 1.6) { c = vec3f(0.35, 0.37, 0.38) * light; }
    }
    c *= 0.6 + 0.4 * smoothstep(0.0, 1.5, 6.0 - abs(u));
    return c;
}

fn floor_col(p: vec3f, rd: vec3f) -> vec3f {
    let g = abs(fract(p.xz / 0.6) - 0.5);
    let grout = smoothstep(0.485, 0.495, max(g.x, g.y));
    var c = vec3f(0.42, 0.44, 0.42) * (0.9 + 0.12 * hash12(floor(p.xz / 0.6)));
    c = mix(c, vec3f(0.25, 0.26, 0.25), grout);
    c *= 0.9 + 0.1 * noise3(vec3f(p.xz * 3.0, 0.0));
    var sh = mix(0.45, 1.0, smoothstep(-0.15, 0.45, sdb2(p.xz, vec2f(1.7, 0.6))));
    for (var i = 0; i < 4; i = i + 1) {
        let dd = length(p.xz - FIG[i].xy);
        sh *= 1.0 - 0.45 * exp(-dd * dd * 10.0);
    }
    let dc = length(p.xz - CAPY.xz);
    sh *= 1.0 - 0.4 * exp(-dc * dc * 12.0);
    var col = c * LCOL * (0.02 + panel_light(p) * 0.4) * sh;
    let rr = reflect(rd, vec3f(0.0, 1.0, 0.0));
    if (rr.y > 0.05) {
        col += ceil_emit((p + rr * (4.5 / rr.y)).xz, 0.3) * 0.2 * sh;
    }
    return col;
}

fn ceil_col(p: vec3f) -> vec3f {
    let g = abs(fract(p.xz / 0.6) - 0.5);
    let grid = smoothstep(0.48, 0.495, max(g.x, g.y));
    var c = vec3f(0.3, 0.31, 0.3) * mix(1.0, 0.6, grid) * (0.03 + panel_light(p - vec3f(0.0, 0.3, 0.0)) * 0.05);
    c += ceil_emit(p.xz, 0.01) * 3.0 + ceil_emit(p.xz, 0.45) * 0.25;
    return c;
}

fn env(ro: vec3f, rd: vec3f, tmax: f32) -> Hit {
    let th = horizon_t(tmax);
    let pe = ro + rd * th;
    if (abs(pe.x) > 6.05 || abs(pe.z) > 6.05 || pe.y < -0.05 || pe.y > 4.55) { return no_hit(); }
    var col = vec3f(0.0);
    if (pe.y < 0.03) { col = floor_col(pe, rd); }
    else if (pe.y > 4.47) { col = ceil_col(pe); }
    else { col = wall_col(pe, time()); }
    return Hit(fog(col, th, rd), th);
}

// steam off a cup: a few jittered samples through a small box over its rim; a wavering, widening plume
// whose density is broken up by rising noise
fn wisp(ro: vec3f, rd: vec3f, tend: f32, rim: vec3f, seed: f32) -> vec4f {
    let sp = box_span(ro, rd, rim + vec3f(-0.14, 0.0, -0.14), rim + vec3f(0.14, 0.5, 0.14));
    let t0 = max(sp.x, 0.0);
    let t1 = min(sp.y, tend);
    if (sp.x > sp.y || t0 >= t1) { return vec4f(0.0, 0.0, 0.0, 1.0); }
    let t = time();
    let ns = select(5, 8, quality() > 0.5);
    let dt = (t1 - t0) / f32(ns);
    var tt = t0 + dt * hash12(rd.xy * 517.0 + seed);
    var T = 1.0;
    var acc = 0.0;
    for (var i = 0; i < ns; i = i + 1) {
        let p = ro + rd * tt - rim;
        let h = max(p.y, 0.0);
        let ax = vec2f(sin(h * 9.0 - t * 1.7 + seed), cos(h * 7.0 - t * 1.3 + seed)) * 0.09 * h;
        let r = length(p.xz - ax);
        let w = 0.022 + h * 0.12;
        var d = exp(-r * r / (w * w)) * smoothstep(0.0, 0.04, h) * (1.0 - smoothstep(0.12, 0.48, h));
        d *= smoothstep(0.3, 0.75, noise3(vec3f(p.x * 13.0, h * 6.0 - t * 1.1, p.z * 13.0 + seed)));
        let a = d * dt * 30.0;
        acc += T * a;
        T *= exp(-a);
        tt += dt;
    }
    let lit = LCOL * (0.05 + panel_light(rim + vec3f(0.0, 0.25, 0.0)) * 0.3);
    return vec4f(lit * acc, T);
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    setup();
    var h = shade_scene(ro, rd, tmin, tmax);
    if (h.t < 0.0) { return h; }
    var c = h.color;
    // steam off the capybara's cup (it follows the sip) and off the two cups on the table
    let ml = mix(vec3f(0.0, 0.98, 0.36), vec3f(0.0, 1.2, 0.42), SIP);
    let mw = rot2(-CAPY_YAW) * ml.xz;
    let cups = array<vec3f, 3>(CAPY + vec3f(mw.x, ml.y + 0.06, mw.y), vec3f(-0.62, 1.035, 0.28), vec3f(1.05, 1.035, -0.32));
    for (var i = 0; i < 3; i = i + 1) {
        let w = wisp(ro, rd, h.t, cups[i], f32(i) * 7.1);
        c = c * w.w + w.rgb * (1.0 - 0.6 * SIP * f32(i == 0));
    }
    return Hit(tm(c * 1.3, rd), h.t);
}

fn shade_scene(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let sp = box_span(ro, rd, vec3f(-3.4, 0.0, -2.3), vec3f(3.4, 1.85, 2.3));
    let t0 = max(sp.x, tmin);
    let t1 = min(sp.y, tmax);
    if (sp.x <= sp.y && t0 < t1) {
        let steps = i32(mix(36.0, 80.0, quality()));
        var t = t0;
        var hit = false;
        for (var i = 0; i < steps; i = i + 1) {
            let d = map(ro + rd * t);
            if (d < 0.001 * (1.0 + t)) { hit = true; break; }
            t += d * 0.85;
            if (t > t1) { break; }
        }
        if (hit && t <= t1) {
            return Hit(shade_obj(ro + rd * t, rd, t), t);
        }
    }
    return env(ro, rd, tmax);
}

shaders.0a375cea36d0850c6939c7cc57ee:
// Hyperbeast: a four-dimensional squid drifting through a cosmic abyss.
// Tentacles are 4D curves rotated in xw/zw/yw and sliced by our 3D space:
// a tube's thickness is its cross-section at the slice, so it swells and thins to a thread.
const NT: i32 = 6;
const NK: i32 = 7;
// xyz = point on the tentacle, w = tube radius at the slice
var<private> PP: array<vec4f, 42>;
var<private> TB: array<vec4f, 6>;
var<private> BODY: vec3f;
var<private> JET: f32;

fn rot4(q0: vec4f, ma: mat2x2<f32>, mb: mat2x2<f32>, mc: mat2x2<f32>) -> vec4f {
    var q = q0;
    let xw = ma * vec2f(q.x, q.w);
    q = vec4f(xw.x, q.y, q.z, xw.y);
    let zw = mb * vec2f(q.z, q.w);
    q = vec4f(q.x, q.y, zw.x, zw.y);
    let yw = mc * vec2f(q.y, q.w);
    return vec4f(q.x, yw.x, q.z, yw.y);
}

fn body_setup(t: f32) {
    let ph = fract(t * 0.28);
    JET = exp(-ph * 7.0);
    let rise = smoothstep(0.0, 0.3, ph) * (1.0 - ph);
    BODY = vec3f(0.45 * sin(t * 0.13), 1.9 + 0.6 * rise, 0.45 * cos(t * 0.11));
}

fn tent_setup(t: f32) {
    let ma = rot2(t * 0.21);
    let mb = rot2(0.8 * sin(t * 0.15));
    let mc = rot2(0.3 * sin(t * 0.09 + 1.0));
    for (var i = 0; i < NT; i = i + 1) {
        let fi = f32(i);
        let a0 = fi * TAU / f32(NT) + 0.25 * sin(t * 0.4 + fi);
        var cen = vec3f(0.0);
        for (var k = 0; k < NK; k = k + 1) {
            let s = f32(k) / f32(NK - 1);
            let wv = t * 1.1 - s * 5.0 + fi * 1.3;
            let spread = (0.2 + 0.85 * s) * (1.0 - 0.35 * JET);
            let ang = a0 + 0.9 * s * sin(wv);
            var q = vec4f(spread * cos(ang), -0.2 - 1.5 * s, spread * sin(ang), 0.0);
            let lp = s * 5.0 + t * 0.7 + fi * 2.1;
            let cl = cos(lp);
            let sl = sin(lp);
            q += vec4f(cl, 0.5 * sin(lp * 0.7), sl, sin(lp + fi)) * (0.34 * s);
            q.w += 0.8 * s * sin(s * 3.0 + t * 0.4 + fi * 1.9);
            q = rot4(q, ma, mb, mc);
            let sc = 1.0 / (1.0 - 0.1 * clamp(q.w, -1.5, 1.5));
            let pp = BODY + q.xyz * sc;
            let slice = sqrt(max(1.0 - q.w * q.w / 2.0, 0.0));
            PP[i * NK + k] = vec4f(pp, (0.13 - 0.09 * s) * slice + 0.012);
            cen += pp;
        }
        cen = cen / f32(NK);
        var r = 0.0;
        for (var k = 0; k < NK; k = k + 1) {
            let v = PP[i * NK + k];
            r = max(r, length(v.xyz - cen) + v.w);
        }
        TB[i] = vec4f(cen, r + 0.2);
    }
}

fn sph(ro: vec3f, rd: vec3f, c: vec3f, r: f32) -> vec2f {
    let oc = ro - c;
    let b = dot(oc, rd);
    let h = b * b - (dot(oc, oc) - r * r);
    if (h < 0.0) { return vec2f(1e9, -1e9); }
    let s = sqrt(h);
    return vec2f(-b - s, -b + s);
}

fn abyss(rd: vec3f, t: f32, bdir: vec3f) -> vec3f {
    let y = rd.y;
    var c = mix(vec3f(0.006, 0.008, 0.03), vec3f(0.02, 0.09, 0.14), smoothstep(-0.5, 0.9, y));
    let h = noise3(rd * 2.2 + vec3f(t * 0.015, t * 0.01, 0.0)) * 0.62 + noise3(rd * 4.7 - vec3f(0.0, t * 0.02, 3.1)) * 0.38;
    c += vec3f(0.10, 0.04, 0.22) * smoothstep(0.45, 0.78, h);
    c += vec3f(0.0, 0.07, 0.09) * smoothstep(0.58, 0.88, h);
    let a = atan2(rd.x, rd.z);
    let shaft = 0.5 + 0.5 * sin(a * 9.0 + t * 0.15 + 2.0 * sin(a * 3.0 - t * 0.1));
    c += vec3f(0.03, 0.16, 0.2) * pow(max(y, 0.0), 2.0) * shaft * 0.6;
    let hs = hash13(floor(rd * 140.0));
    let tw = 0.5 + 0.5 * sin(t * 2.0 + hs * 60.0);
    c += mix(vec3f(0.4, 0.9, 1.0), vec3f(1.0, 0.4, 0.9), fract(hs * 13.0)) * step(0.9965, hs) * tw * 0.8;
    let aura = max(dot(rd, bdir), 0.0);
    c += vec3f(0.18, 0.08, 0.4) * pow(aura, 12.0) * 0.5 + vec3f(0.05, 0.25, 0.3) * pow(aura, 40.0) * 0.4;
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let t = time();
    body_setup(t);
    var acc = vec3f(0.0);
    var T = 1.0;
    var thit = 1e9;
    let outer = sph(ro, rd, BODY, 3.25);
    if (outer.x < outer.y && outer.y > tmin) {
        tent_setup(t);
        var TI: array<vec2f, 6>;
        var t0 = 1e9;
        var t1 = -1e9;
        for (var j = 0; j < NT; j = j + 1) {
            let s = sph(ro, rd, TB[j].xyz, TB[j].w);
            TI[j] = s;
            if (s.x < s.y) { t0 = min(t0, s.x); t1 = max(t1, s.y); }
        }
        let bs0 = sph(ro, rd, BODY + vec3f(0.0, 0.6, 0.0), 1.1);
        if (bs0.x < bs0.y) { t0 = min(t0, bs0.x); t1 = max(t1, bs0.y); }
        t0 = max(t0, tmin);
        t1 = min(t1, tmax);
        if (t0 < t1) {
            let steps = i32(mix(24.0, 52.0, quality()));
            var tt = t0 + hash12(rd.xy * 731.0 + vec2f(rd.z * 17.0, 3.0)) * 0.04;
            let sq = 1.0 - 0.14 * JET;
            let jetb = 2.0 * JET;
            for (var i = 0; i < steps; i = i + 1) {
                if (tt > t1 || T < 0.04) { break; }
                let p = ro + rd * tt;
                let bp = p - BODY;
                let yy = (bp.y - 0.6) / 0.9;
                let rxz = 0.48 * sq * (1.0 - 0.35 * clamp(yy, 0.0, 1.0));
                let db = (length(vec3f(bp.x / rxz, yy, bp.z / rxz)) - 1.0) * rxz;
                var dmin = abs(db);
                var e = vec3f(0.0);
                var dens = 0.0;
                if (db < 0.25) {
                    let bins = 1.0 - smoothstep(-0.03, 0.03, db);
                    let bsh = exp(-abs(db) * 14.0);
                    let spots = smoothstep(0.6, 0.95, 0.5 + 0.5 * sin(bp.x * 11.0 + t * 0.9) * sin(bp.y * 9.0 - t * 1.3) * sin(bp.z * 11.0 + t * 0.7));
                    var bc = mix(vec3f(0.16, 0.12, 0.7), vec3f(0.1, 0.55, 0.75), smoothstep(-0.4, 1.4, bp.y));
                    bc += vec3f(1.0, 0.2, 0.75) * spots * 1.5;
                    bc *= 1.0 + jetb * exp(-max(bp.y + 0.3, 0.0) * 2.0);
                    e += bc * (bins * 0.5 + bsh * 3.6);
                    dens += bins * 0.8;
                }
                for (var j = 0; j < NT; j = j + 1) {
                    let iv = TI[j];
                    if (tt < iv.x || tt > iv.y) {
                        if (tt < iv.x) { dmin = min(dmin, iv.x - tt + 0.02); }
                        continue;
                    }
                    var bd = 1e3;
                    var bsv = 0.0;
                    var bth = 1.0;
                    for (var k = 0; k < NK - 1; k = k + 1) {
                        let ia = j * NK + k;
                        let A = PP[ia];
                        let B = PP[ia + 1];
                        let ba = B.xyz - A.xyz;
                        let pa = p - A.xyz;
                        let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
                        let rr = mix(A.w, B.w, h);
                        let d = length(pa - ba * h) - rr;
                        if (d < bd) {
                            bd = d;
                            bsv = (f32(k) + h) / f32(NK - 1);
                            bth = (rr - 0.012) / max(0.13 - 0.09 * bsv, 0.01);
                        }
                    }
                    dmin = min(dmin, abs(bd));
                    if (bd < 0.35) {
                        let ins = 1.0 - smoothstep(-0.015, 0.015, bd);
                        let sh = exp(-abs(bd) * 20.0);
                        let halo = 0.0015 / (0.003 + bd * bd);
                        let pulse = pow(0.5 + 0.5 * cos(TAU * (bsv * 2.2 + t * 0.75 + f32(j) * 0.37)), 8.0);
                        let base = mix(vec3f(0.42, 0.25, 1.0), vec3f(0.05, 0.75, 0.8), smoothstep(0.2, 0.9, bth));
                        let c = base * 0.7 + vec3f(1.0, 0.18, 0.7) * (pulse * 2.5 + jetb * exp(-bsv * 4.0));
                        e += c * (ins * 4.0 + sh * 5.5 + halo * 2.0);
                        dens += ins * 3.0;
                    }
                }
                let dt = clamp(dmin * 0.8, 0.04, 0.35);
                acc += T * e * dt;
                if (dens > 0.5 && thit > 1e8) { thit = tt; }
                T *= exp(-dens * dt);
                tt += dt;
            }
        }
    }
    let bdir = normalize(BODY + vec3f(0.0, 0.3, 0.0) - ro);
    var col = acc + T * abyss(rd, t, bdir);
    // a few dim drifting eyes that blink
    for (var i = 0; i < 3; i = i + 1) {
        let fi = f32(i);
        let a = t * 0.23 + fi * 2.09 + 0.5 * sin(t * 0.31 + fi);
        let ep = BODY + vec3f(0.6 * cos(a), 0.1 + 0.3 * sin(t * 0.27 + fi * 1.7), 0.6 * sin(a));
        let tc = dot(ep - ro, rd);
        if (tc > tmin) {
            let d = length(ro + rd * tc - ep);
            let open = smoothstep(0.01, 0.07, abs(fract(t * 0.11 + fi * 0.37) - 0.5));
            let r = 0.055 + 0.025 * sin(t * 0.5 + fi * 2.0);
            let g = (1.0 - smoothstep(r * 0.4, r, d)) * 1.4 + 0.003 / (d * d + 0.003) * 0.3;
            let vis = select(T, 1.0, tc < thit);
            col += vec3f(0.6, 0.92, 1.0) * g * open * vis * 0.7;
        }
    }
    // rising bubbles
    for (var i = 0; i < 14; i = i + 1) {
        let fi = f32(i);
        let h = hash33(vec3f(fi * 1.7, 3.7, 1.3));
        let ang = h.x * TAU;
        let rad = 0.9 + h.y * 3.0;
        let y = fract(t * (0.07 + 0.06 * h.z) + h.y * 3.1) * 4.8 - 0.2;
        let c = vec3f(cos(ang) * rad + 0.08 * sin(t * 1.7 + fi), y, sin(ang) * rad + 0.08 * cos(t * 1.3 + fi));
        let r = 0.03 + 0.05 * h.z;
        let tc = dot(c - ro, rd);
        if (tc > tmin && tc < tmax) {
            let d = length(ro + rd * tc - c);
            if (d < r * 1.5) {
                let x = (d - r * 0.85) / (r * 0.22);
                let ring = exp(-x * x) + 0.15 * (1.0 - smoothstep(0.0, r, d));
                let vis = select(T, 1.0, tc < thit);
                col += vec3f(0.45, 0.85, 1.0) * ring * 0.35 * vis;
            }
        }
    }
    let tout = select(horizon_t(tmax), clamp(thit, tmin, tmax), thit < 1e8);
    return Hit(tone(col * 1.15), tout);
}

shaders.0523b95d5bdc4a06286a2fef66a6:
// Self Portrait in Four Panes: the Room World bot paints itself on a stack of floating glass layers.
const LAMP = vec3f(0.95, 1.52, 0.5);
const PANEC = vec3f(0.2, 1.75, -0.35);
const HEADC = vec3f(-0.45, 1.53, 0.71);
const SR = vec3f(-0.3, 1.3, 0.73);
const SL = vec3f(-0.6, 1.3, 0.75);
const ELL = vec3f(-0.74, 1.02, 0.74);
const HANDL = vec3f(-0.62, 1.06, 0.57);
const PALC = vec3f(-0.62, 1.09, 0.44);

var<private> MAT: i32;
var<private> MHIT: bool;
var<private> T: f32;
var<private> TIP: vec3f;
var<private> HAND: vec3f;
var<private> ELB: vec3f;
var<private> LD: vec3f;
var<private> LP: vec3f;
var<private> HYAW: f32;
var<private> HROLL: f32;
var<private> FIN: vec4f;
var<private> FOUT: vec4f;
var<private> DABS: array<vec3f, 6> = array<vec3f, 6>(
    vec3f(0.1, 0.25, 0.9), vec3f(1.0, 0.55, 0.12), vec3f(0.95, 0.3, 0.25),
    vec3f(0.92, 0.9, 0.85), vec3f(0.1, 0.6, 0.6), vec3f(0.6, 0.05, 0.12));

fn init() {
    T = time();
    TIP = vec3f(0.06 + 0.13 * sin(T * 0.8), 1.72 + 0.09 * sin(T * 1.6 + 1.0), 0.035 + 0.03 * (0.5 + 0.5 * sin(T * 1.6)));
    HAND = TIP + vec3f(-0.09, -0.12, 0.2);
    ELB = mix(SR, HAND, 0.5) + vec3f(0.1, -0.2, 0.06);
    LD = normalize(vec3f(-0.45, 0.9, 0.5) - LAMP);
    LP = LAMP + LD * 0.06;
    HYAW = 0.35 + 0.18 * sin(T * 0.31);
    HROLL = 0.13 * sin(T * 0.45);
    let c = fract(T / 18.0) * 18.0;
    let fo = clamp((c - 14.5) / 3.0, 0.0, 1.0) * 1.05;
    FIN = vec4f(1.05, clamp(c / 3.5, 0.0, 1.0) * 1.05, clamp((c - 4.0) / 3.5, 0.0, 1.0) * 1.05, clamp((c - 8.0) / 3.5, 0.0, 1.0) * 1.05);
    FOUT = vec4f(0.0, fo, fo, fo);
}

fn cap(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}
fn bnd(p: vec3f, mn: vec3f, mx: vec3f) -> f32 { return sd_box(p - (mn + mx) * 0.5, (mx - mn) * 0.5); }
fn sd2box(p: vec2f, b: vec2f) -> f32 {
    let q = abs(p) - b;
    return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0);
}
fn seg2(p: vec2f, a: vec2f, b: vec2f) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}
fn sd_round_cone(p: vec3f, a: vec3f, b: vec3f, r1: f32, r2: f32) -> f32 {
    let ba = b - a;
    let l2 = dot(ba, ba);
    let rr = r1 - r2;
    let a2 = l2 - rr * rr;
    let il2 = 1.0 / l2;
    let pa = p - a;
    let y = dot(pa, ba);
    let z = y - l2;
    let xv = pa * l2 - ba * y;
    let x2 = dot(xv, xv);
    let y2 = y * y * l2;
    let z2 = z * z * l2;
    let k = sign(rr) * rr * rr * x2;
    if (sign(z) * a2 * z2 > k) { return sqrt(x2 + z2) * il2 - r2; }
    if (sign(y) * a2 * y2 < k) { return sqrt(x2 + y2) * il2 - r1; }
    return (sqrt(x2 * a2 * il2) + y * rr) * il2 - r1;
}

fn map(p: vec3f) -> f32 {
    var d = 1e5;
    let b1 = bnd(p, vec3f(-0.92, 0.0, -0.02), vec3f(0.3, 1.85, 1.1));
    if (b1 > 0.08) { d = b1; } else {
        var g = max(length(p.xz - vec2f(-0.45, 0.8)) - 0.2, abs(p.y - 0.64) - 0.022) - 0.01;
        if (g < d) { d = g; MAT = 3; }
        for (var k = 0; k < 3; k = k + 1) {
            let a = f32(k) * 2.094 + 0.6;
            let dir = vec3f(cos(a), 0.0, sin(a));
            g = cap(p, vec3f(-0.45, 0.62, 0.8) + dir * 0.12, vec3f(-0.45, 0.0, 0.8) + dir * 0.25, 0.018);
            if (g < d) { d = g; MAT = 3; }
        }
        g = sd_box(p - vec3f(-0.45, 0.76, 0.79), vec3f(0.08, 0.035, 0.06)) - 0.04;
        let tor = smin(cap(p, vec3f(-0.45, 0.82, 0.79), vec3f(-0.45, 1.16, 0.76), 0.06),
                       sd_box(p - vec3f(-0.45, 1.17, 0.75), vec3f(0.09, 0.06, 0.045)) - 0.04, 0.06);
        g = min(g, tor);
        g = min(g, cap(p, SL, SR, 0.035));
        g = min(g, min(min(cap(p, SR, ELB, 0.03), cap(p, ELB, HAND, 0.026)), length(p - HAND) - 0.034));
        g = min(g, min(min(cap(p, SL, ELL, 0.03), cap(p, ELL, HANDL, 0.026)), length(p - HANDL) - 0.034));
        if (g < d) { d = g; MAT = 1; }
        g = min(length(p - vec3f(-0.45, 1.16, 0.665)) - 0.028, min(length(p - ELB) - 0.04, length(p - ELL) - 0.04));
        if (g < d) { d = g; MAT = 2; }
        g = cap(p, vec3f(-0.45, 1.28, 0.75), vec3f(-0.45, 1.44, 0.72), 0.022);
        if (g < d) { d = g; MAT = 8; }
        var q = p - HEADC;
        let xz = rot2(HYAW) * q.xz;
        q = vec3f(xz.x, q.y, xz.y);
        let xy = rot2(HROLL) * q.xy;
        q = vec3f(xy.x, xy.y, q.z);
        g = sd_box(q, vec3f(0.08, 0.06, 0.07)) - 0.04;
        if (g < d) { d = g; MAT = select(1, 7, q.z < -0.085 && abs(q.y) < 0.028 && abs(q.x) < 0.09); }
        g = cap(q, vec3f(0.03, 0.09, 0.0), vec3f(0.07, 0.24, 0.02), 0.006);
        if (g < d) { d = g; MAT = 8; }
        g = length(q - vec3f(0.07, 0.25, 0.02)) - 0.02;
        if (g < d) { d = g; MAT = 2; }
        for (var s = 0; s < 2; s = s + 1) {
            let sx = select(-1.0, 1.0, s == 1);
            let hip = vec3f(-0.45 + sx * 0.075, 0.76, 0.78);
            let knee = vec3f(-0.45 + sx * 0.11, 0.73, 0.44);
            let foot = vec3f(-0.45 + sx * 0.12, 0.1, 0.41);
            g = min(cap(p, hip, knee, 0.042), cap(p, knee, foot, 0.035));
            g = min(g, sd_box(p - vec3f(foot.x, 0.035, 0.37), vec3f(0.035, 0.03, 0.07)) - 0.01);
            if (g < d) { d = g; MAT = 1; }
            g = length(p - knee) - 0.045;
            if (g < d) { d = g; MAT = 2; }
        }
        g = cap(p, HAND, TIP, 0.007);
        if (g < d) { d = g; MAT = 5; }
        g = cap(p, mix(HAND, TIP, 0.8), TIP, 0.011);
        if (g < d) { d = g; MAT = 2; }
        let q2 = p - PALC;
        g = (max(length(q2.xz * vec2f(1.0, 1.25)) - 0.17, abs(q2.y) - 0.006) - 0.004) * 0.85;
        if (g < d) { d = g; MAT = 4; }
    }
    let b2 = bnd(p, vec3f(-0.45, 0.0, -1.75), vec3f(0.85, 2.85, -0.7));
    if (b2 > 0.08) { d = min(d, b2); } else {
        var g = cap(p, vec3f(-0.32, 0.0, -0.82), vec3f(0.14, 2.75, -0.98), 0.03);
        g = min(g, cap(p, vec3f(0.72, 0.0, -0.82), vec3f(0.26, 2.75, -0.98), 0.03));
        g = min(g, cap(p, vec3f(0.2, 0.0, -1.68), vec3f(0.2, 2.6, -1.02), 0.026));
        g = min(g, sd_box(p - vec3f(0.2, 1.08, -0.8), vec3f(0.5, 0.02, 0.07)) - 0.005);
        g = min(g, sd_box(p - vec3f(0.2, 2.5, -0.97), vec3f(0.12, 0.05, 0.03)));
        if (g < d) { d = g; MAT = 3; }
    }
    let b3 = bnd(p, vec3f(0.82, 0.0, 0.12), vec3f(1.48, 1.62, 0.85));
    if (b3 > 0.08) { d = min(d, b3); } else {
        var g = sd_box(p - vec3f(1.15, 0.74, 0.48), vec3f(0.28, 0.02, 0.26)) - 0.005;
        var q = p - vec3f(1.15, 0.36, 0.48);
        q = vec3f(abs(q.x) - 0.24, q.y, abs(q.z) - 0.22);
        g = min(g, sd_box(q, vec3f(0.018, 0.36, 0.018)));
        if (g < d) { d = g; MAT = 3; }
        g = max(length(p.xz - vec2f(1.3, 0.32)) - 0.065, abs(p.y - 0.855) - 0.09) - 0.005;
        if (g < d) { d = g; MAT = 6; }
        for (var k = 0; k < 3; k = k + 1) {
            let fk = f32(k);
            let tp = vec3f(1.3 + (fk - 1.0) * 0.09, 1.1 + fk * 0.035, 0.32 + (fk - 1.0) * 0.04);
            g = cap(p, vec3f(1.3, 0.85, 0.32), tp, 0.007);
            if (g < d) { d = g; MAT = 5; }
        }
        g = max(length(p.xz - vec2f(1.02, 0.65)) - 0.08, abs(p.y - 0.775) - 0.012) - 0.004;
        g = min(g, cap(p, vec3f(1.02, 0.78, 0.65), vec3f(1.08, 1.3, 0.62), 0.012));
        g = min(g, cap(p, vec3f(1.08, 1.3, 0.62), LAMP - LD * 0.1, 0.01));
        g = min(g, sd_round_cone(p, LAMP - LD * 0.1, LAMP, 0.025, 0.06));
        if (g < d) { d = g; MAT = 8; }
        g = length(p - (LAMP + LD * 0.02)) - 0.035;
        if (g < d) { d = g; MAT = 7; }
    }
    return d;
}

fn calc_normal(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn soft_sh(p: vec3f, n: vec3f) -> f32 {
    let lv = LP - p;
    let dist = length(lv);
    let l = lv / dist;
    let o = p + n * 0.01;
    var res = 1.0;
    var t = 0.02;
    let steps = i32(mix(8.0, 16.0, quality()));
    for (var i = 0; i < 16; i = i + 1) {
        if (i >= steps) { break; }
        let h = map(o + l * t);
        res = min(res, 10.0 * h / t);
        t += clamp(h, 0.02, 0.3);
        if (res < 0.02 || t > dist - 0.09) { break; }
    }
    return clamp(res, 0.0, 1.0);
}

fn lightp(p: vec3f, n: vec3f, rd: vec3f, base: vec3f, gloss: f32, sh: f32) -> vec3f {
    let lv = LP - p;
    let dl = length(lv);
    let l = lv / dl;
    let spot = mix(0.05, 1.0, smoothstep(0.78, 0.93, dot(-l, LD)));
    let att = 4.0 / (1.0 + dl * dl * 0.6);
    let warm = vec3f(1.0, 0.62, 0.3) * att * spot * sh;
    let dif = max(dot(n, l), 0.0);
    let pv = PANEC - p;
    let dp = length(pv);
    let pl = pv / dp;
    let cob = vec3f(0.22, 0.42, 1.0) * max(dot(n, pl) * 0.6 + 0.4, 0.0) * 1.1 / (1.0 + dp * dp);
    let amb = vec3f(0.045, 0.04, 0.055) * (0.7 + 0.3 * n.y);
    let hv = normalize(l - rd);
    let sp = pow(max(dot(n, hv), 0.0), mix(12.0, 80.0, gloss)) * gloss;
    let hp = normalize(pl - rd);
    let sp2 = pow(max(dot(n, hp), 0.0), 40.0) * gloss;
    return base * (amb + cob + warm * dif) + warm * sp * 0.8 + vec3f(0.3, 0.5, 1.0) * sp2 * 0.4 / (1.0 + dp * dp);
}

fn surface(ro: vec3f, rd: vec3f, tmin: f32, tend: f32, steps: i32, allow_m: bool, do_sh: bool) -> vec4f {
    var ts = tend - 0.002;
    var kind = 0;
    let tf = plane_y(ro, rd, 0.0);
    if (tf > tmin && tf < ts) { ts = tf; kind = 1; }
    let sp = box_span(ro, rd, vec3f(-0.95, 0.0, -1.8), vec3f(1.52, 2.9, 1.15));
    if (sp.x < sp.y && sp.y > tmin) {
        var t = max(sp.x, tmin);
        let te = min(sp.y, ts);
        for (var i = 0; i < 80; i = i + 1) {
            if (i >= steps || t > te) { break; }
            let d = map(ro + rd * t);
            if (d < 0.0005 + 0.0007 * t) { ts = t; kind = 2; break; }
            t += d * 0.9;
        }
    }
    let p = ro + rd * ts;
    var col = vec3f(0.0);
    if (kind == 2) {
        let m = MAT;
        let n = calc_normal(p);
        var base = vec3f(0.7);
        var gloss = 0.2;
        var emit = vec3f(0.0);
        let fres = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
        if (m == 1) {
            base = vec3f(0.74, 0.77, 0.84);
            gloss = 0.75;
            emit = vec3f(0.25, 0.5, 1.0) * fres * 0.55;
        } else if (m == 2) {
            base = vec3f(0.1);
            emit = vec3f(0.35, 0.65, 1.0) * (2.0 + 0.7 * sin(T * 2.2 + p.y * 9.0));
        } else if (m == 3) {
            base = vec3f(0.3, 0.17, 0.09) * (0.7 + 0.6 * noise3(p * vec3f(9.0, 50.0, 9.0)));
            gloss = 0.25;
        } else if (m == 4) {
            let q = p - PALC;
            base = vec3f(0.5, 0.36, 0.22);
            gloss = 0.3;
            for (var k = 0; k < 6; k = k + 1) {
                let a = f32(k) * 0.95 + 0.3;
                let cc = vec2f(cos(a), sin(a) * 0.8) * 0.11;
                let dd = length(q.xz - cc) - 0.024 - 0.008 * noise3(vec3f(q.xz * 60.0, f32(k)));
                if (dd < 0.0 && n.y > 0.3) { base = DABS[k]; gloss = 1.0; emit = DABS[k] * 0.25; }
            }
        } else if (m == 5) {
            base = vec3f(0.4, 0.08, 0.05);
            gloss = 0.6;
            if (p.x > 0.8) {
                let bi = i32(clamp(round((p.x - 1.3) / 0.09) + 1.0, 0.0, 2.0));
                if (p.y > 1.04 + f32(bi) * 0.035) { base = DABS[bi * 2]; gloss = 0.9; }
            }
        } else if (m == 6) {
            base = select(vec3f(0.1, 0.13, 0.16), vec3f(0.16, 0.2, 0.32), p.y < 0.88);
            gloss = 1.0;
            emit = vec3f(0.3, 0.5, 0.9) * fres * 0.4;
        } else if (m == 7) {
            base = vec3f(0.0);
            emit = vec3f(1.0, 0.65, 0.32) * 3.5;
        } else {
            base = vec3f(0.4, 0.28, 0.14);
            gloss = 0.85;
        }
        let lv = normalize(LP - p);
        var sh = 1.0;
        if (do_sh && dot(n, lv) > 0.0 && dot(-lv, LD) > 0.74) { sh = soft_sh(p, n); }
        let ao = clamp(map(p + n * 0.1) / 0.1, 0.35, 1.0);
        col = lightp(p, n, rd, base, gloss, sh) * (0.4 + 0.6 * ao) + emit;
    } else if (kind == 1) {
        let bi = floor(p.z / 0.2);
        let along = p.x + hash12(vec2f(bi, 4.0)) * 6.0;
        let jx = abs(fract(p.z / 0.2) - 0.5);
        let jz = abs(fract(along / 1.8) - 0.5);
        var base = vec3f(0.16, 0.1, 0.06) * (0.7 + 0.5 * hash12(vec2f(bi, floor(along / 1.8)))) * (0.8 + 0.35 * noise3(vec3f(p.x * 2.0, 0.0, p.z * 30.0)));
        base *= 1.0 - 0.5 * max(smoothstep(0.46, 0.49, jx), smoothstep(0.493, 0.499, jz));
        let cell = floor(p.xz * 5.0);
        let hh = hash12(cell + 17.0);
        let ctr = (cell + 0.5 + (hash33(vec3f(cell, 2.0)).xy - 0.5) * 0.6) / 5.0;
        let nearz = length(p.xz - vec2f(0.0, -0.1)) < 1.8;
        if (nearz && hh > 0.86 && length(p.xz - ctr) < 0.015 + 0.03 * fract(hh * 37.0)) { base = DABS[i32(fract(hh * 91.0) * 5.99)] * 0.8; }
        let up = vec3f(0.0, 1.0, 0.0);
        let lv = normalize(LP - p);
        var sh = 1.0;
        if (do_sh && dot(-lv, LD) > 0.74) { sh = soft_sh(p, up); }
        let ao = clamp(map(p + vec3f(0.0, 0.25, 0.0)) / 0.25, 0.3, 1.0);
        col = lightp(p, up, rd, base, 0.35, sh) * ao;
    } else {
        var n = vec3f(0.0, -1.0, 0.0);
        if (p.y < 4.45) {
            if (abs(p.x) > abs(p.z)) { n = vec3f(-sign(p.x), 0.0, 0.0); } else { n = vec3f(0.0, 0.0, -sign(p.z)); }
        }
        let w = select(p.x, p.z, abs(n.x) > 0.5);
        var base = vec3f(0.2, 0.15, 0.12) * (0.75 + 0.4 * noise3(p * 1.5 + 3.0));
        if (p.y < 1.0) {
            let pan = abs(fract(w / 0.6) - 0.5);
            base = vec3f(0.11, 0.07, 0.045) * (0.8 + 0.3 * noise3(vec3f(w * 10.0, p.y * 2.0, 1.0))) * (1.0 - 0.4 * smoothstep(0.46, 0.49, pan));
        }
        if (abs(p.y - 1.0) < 0.03) { base = vec3f(0.25, 0.16, 0.09); }
        if (n.y < -0.5) { base = vec3f(0.06, 0.05, 0.05); }
        var gloss = 0.05;
        if (allow_m && n.z > 0.5 && p.x > 1.2 && p.x < 3.3 && p.y > 0.45 && p.y < 3.5) {
            let ex = min(min(p.x - 1.2, 3.3 - p.x), min(p.y - 0.45, 3.5 - p.y));
            if (ex < 0.1) { base = vec3f(0.55, 0.38, 0.13) * (0.7 + 0.5 * noise3(p * 25.0)); gloss = 0.9; } else { MHIT = true; }
        }
        col = lightp(p, n, rd, base, gloss, 1.0) + base * vec3f(0.35, 0.26, 0.2) * 0.5;
    }
    return vec4f(col, ts);
}

fn pane_paint(i: i32, u: f32, v: f32) -> vec4f {
    let fi = f32(i);
    let br = noise3(vec3f(u * 7.0, v * 45.0, fi * 5.0 + 1.0));
    let hd = sd2box(vec2f(u, v - 0.1), vec2f(0.11, 0.09)) - 0.045;
    let shd = (length(vec2f(u / 0.34, (v + 0.55) / 0.24)) - 1.0) * 0.24;
    let nk = sd2box(vec2f(u, v + 0.16), vec2f(0.03, 0.12));
    let body = min(min(hd, shd), nk);
    var col = vec3f(0.0);
    var a = 0.0;
    var order = 0.0;
    if (i == 0) {
        col = mix(vec3f(0.02, 0.06, 0.3), vec3f(0.05, 0.26, 0.42), clamp((v + 0.6) / 1.2, 0.0, 1.0)) * (0.55 + 0.9 * br);
        col += vec3f(1.0, 0.55, 0.22) * 0.5 * exp(-length(vec2f(u, v - 0.1)) * 6.0);
        a = 0.5;
    } else if (i == 1) {
        let lit = 0.75 + 0.45 * clamp(0.5 - u + v, 0.0, 1.0);
        col = vec3f(0.5, 0.62, 0.92) * (0.6 + 0.5 * br) * lit;
        a = 0.72 * smoothstep(0.004, -0.004, body);
        order = clamp((0.6 - v) / 1.2, 0.0, 1.0);
    } else if (i == 2) {
        let visor = sd2box(vec2f(u, v - 0.1), vec2f(0.095, 0.022)) - 0.01;
        let tipd = length(vec2f(u - 0.09, v - 0.43)) - 0.024;
        let warmf = min(visor, tipd);
        let core = length(vec2f(u, v + 0.45)) - 0.045;
        let ant = seg2(vec2f(u, v), vec2f(0.05, 0.22), vec2f(0.09, 0.42)) - 0.006;
        let seam = abs(shd + 0.06) - 0.004;
        let pale = min(ant, max(seam, v + 0.33));
        if (warmf < 0.0) { col = vec3f(1.0, 0.6, 0.25) * 1.6 * (0.8 + 0.4 * br); a = 0.92; }
        else if (core < 0.0) { col = vec3f(0.4, 0.75, 1.0) * 1.8; a = 0.9; }
        else if (pale < 0.0) { col = vec3f(0.7, 0.85, 1.0); a = 0.8; }
        order = clamp((u + 0.45) / 0.9, 0.0, 1.0);
    } else {
        let ln = abs(body) - 0.005 * (0.6 + 0.9 * br);
        a = 0.95 * smoothstep(0.002, -0.002, ln);
        col = vec3f(0.85, 0.95, 1.0) * 1.3;
        let hl = min(length(vec2f(u + 0.08, v - 0.17)) - 0.018, length(vec2f(u + 0.2, v + 0.4)) - 0.02);
        if (hl < 0.0) { a = 0.9; col = vec3f(1.0, 0.95, 0.85) * 1.5; }
        order = fract(atan2(v, u) / TAU + 0.5);
    }
    let fin = FIN[i];
    let fout = FOUT[i];
    let vis = clamp((fin - order) * 25.0, 0.0, 1.0) * clamp((order - fout) * 25.0 + 1.0, 0.0, 1.0);
    let fresh = exp(-abs(fin - order) * 40.0) * step(fin, 1.0);
    return vec4f(col * (1.0 + 1.5 * fresh), a * vis);
}

fn layer_col(i: i32) -> vec3f {
    if (i == 0) { return vec3f(0.2, 0.45, 1.0); }
    if (i == 1) { return vec3f(0.6, 0.75, 1.0); }
    if (i == 2) { return vec3f(1.0, 0.6, 0.25); }
    return vec3f(0.9, 0.95, 1.0);
}

fn effects(ro: vec3f, rd: vec3f, tmin: f32, ts: f32, col: vec3f, beam: bool) -> vec3f {
    var c = col;
    if (beam) {
        let cb = LP + LD;
        let oc = ro - cb;
        let b = dot(oc, rd);
        let cc = dot(oc, oc) - 1.21;
        let disc = b * b - cc;
        if (disc > 0.0) {
            let sq = sqrt(disc);
            let t0 = max(-b - sq, tmin);
            let t1 = min(-b + sq, ts);
            if (t1 > t0) {
                let dt = (t1 - t0) / 8.0;
                let j = hash13(rd * 431.0);
                var acc = 0.0;
                for (var i = 0; i < 8; i = i + 1) {
                    let s = ro + rd * (t0 + (f32(i) + j) * dt);
                    let v = s - LP;
                    let dl = length(v);
                    let ca = dot(v, LD) / max(dl, 0.001);
                    acc += smoothstep(0.82, 0.95, ca) / (1.0 + dl * dl * 1.2);
                }
                c += vec3f(1.0, 0.6, 0.28) * acc * dt * 0.09;
            }
        }
    }
    for (var k = 0; k < 4; k = k + 1) {
        let i = select(3 - k, k, rd.z < 0.0);
        let fi = f32(i);
        if (abs(rd.z) < 0.0001) { continue; }
        let zc = -0.75 + 0.25 * fi;
        let tz = (zc - ro.z) / rd.z;
        if (tz < tmin || tz > ts) { continue; }
        let p = ro + rd * tz;
        let u = p.x - 0.2;
        let v = p.y - 1.75 - 0.015 * sin(T * 0.6 + fi * 1.7);
        if (abs(u) > 0.45 || abs(v) > 0.6) { continue; }
        let pp = pane_paint(i, u, v);
        c = mix(c, pp.rgb * 1.3, pp.a);
        c = c * 0.95 + vec3f(0.02, 0.04, 0.1);
        let e = min(0.45 - abs(u), 0.6 - abs(v));
        c += vec3f(0.3, 0.55, 1.0) * exp(-e * 150.0) * 0.9;
    }
    for (var i = 0; i < 28; i = i + 1) {
        let fi = f32(i);
        let h = hash33(vec3f(fi, 3.7, 11.0));
        let layer = i % 4;
        let zc = -0.75 + 0.25 * f32(layer);
        let home = vec3f(0.2 + (h.x - 0.5) * 0.8, 1.75 + (h.y - 0.5) * 1.05, zc);
        let ph = fract(T * 0.06 + h.z);
        let s = smoothstep(0.0, 0.45, ph) * (1.0 - smoothstep(0.55, 1.0, ph));
        let drift = vec3f((h.x - 0.5) * 0.9 + 0.25 * sin(T * 0.7 + fi), 0.25 + h.y * 0.55, (h.z - 0.4) * 0.9 + 0.2 * cos(T * 0.5 + fi * 1.3));
        let P = home + drift * s;
        let w = P - ro;
        let tp = dot(w, rd);
        if (tp < tmin || tp > ts) { continue; }
        let d2 = max(dot(w, w) - tp * tp, 0.0);
        let g = 1.3 * exp(-d2 * 6000.0) + 0.22 * exp(-d2 * 300.0);
        c += layer_col(layer) * g * (0.35 + 0.9 * s);
    }
    if (beam) {
        let b1 = normalize(cross(LD, vec3f(0.0, 1.0, 0.0)));
        let b2 = cross(LD, b1);
        for (var i = 0; i < 22; i = i + 1) {
            let fi = f32(i);
            let h = hash33(vec3f(fi, 9.1, 2.3));
            let f = fract(h.x + T * 0.012);
            let along = 0.3 + f * 1.6;
            let ang = h.y * TAU + T * 0.07 * (h.z - 0.5);
            let rad = along * 0.42 * sqrt(h.z);
            let P = LP + LD * along + (b1 * cos(ang) + b2 * sin(ang)) * rad + vec3f(0.0, 0.03 * sin(T * 0.5 + fi * 2.0), 0.0);
            let w = P - ro;
            let tp = dot(w, rd);
            if (tp < tmin || tp > ts) { continue; }
            let d2 = max(dot(w, w) - tp * tp, 0.0);
            let tw = (0.6 + 0.4 * sin(T * 1.7 + fi * 3.1)) * smoothstep(0.0, 0.1, f) * smoothstep(1.0, 0.9, f);
            c += vec3f(1.0, 0.75, 0.45) * (0.9 * exp(-d2 * 30000.0) + 0.06 * exp(-d2 * 2000.0)) * tw / (1.0 + along * along * 0.5);
        }
    }
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    init();
    MHIT = false;
    let q = quality();
    let s = surface(ro, rd, tmin, tmax, i32(mix(40.0, 80.0, q)), true, true);
    var col = s.xyz;
    if (MHIT) {
        let p = ro + rd * s.w;
        let mn = normalize(vec3f(-0.1, 0.0, 1.0));
        let rr = reflect(rd, mn);
        let ex = box_span(p, rr, vec3f(-6.0, 0.0, -6.0), vec3f(6.0, 4.5, 6.0)).y;
        let s2 = surface(p, rr, 0.01, max(ex, 0.05), i32(mix(24.0, 56.0, q)), false, false);
        let c2 = effects(p, rr, 0.01, s2.w, s2.xyz, false);
        let smudge = noise3(p * vec3f(3.0, 3.0, 1.0));
        col = c2 * vec3f(0.8, 0.84, 0.88) + vec3f(0.02, 0.025, 0.03) * smudge;
    }
    col = effects(ro, rd, tmin, s.w, col, true);
    return Hit(tone(col * 1.1), s.w);
}

shaders.05264f4d0f957d0422488d025ec2:
// Self-portrait of the Room World bot: a quiet studio where a glass easel holds a half-built wall of tiny rooms.
const IVORY: vec3f = vec3f(0.95, 0.90, 0.80);
const GRAPH: vec3f = vec3f(0.10, 0.10, 0.11);
const TEAL: vec3f = vec3f(0.10, 0.85, 0.78);
const SUN: vec3f = vec3f(1.0, 0.85, 0.64);
const HALO_C: vec3f = vec3f(0.0, 3.2, 0.0);
const NCUBE: i32 = 70;
const K0: i32 = 28;
const STEP: f32 = 0.45;
const CYC: f32 = 24.0;

struct Cube { c: vec3f, h: f32, flash: f32, home: f32 };
struct Op { t: f32, col: vec3f };

fn ldir() -> vec3f { return normalize(vec3f(-0.1, 0.35, -1.0)); }

fn win_mask(w: vec2f) -> f32 {
    let m = smoothstep(-1.75, -1.7, w.x) * (1.0 - smoothstep(0.5, 0.55, w.x)) * smoothstep(2.85, 2.9, w.y) * (1.0 - smoothstep(4.3, 4.35, w.y));
    let bar = min(abs(w.x + 0.6), abs(w.y - 3.6));
    return m * smoothstep(0.025, 0.045, bar);
}

fn in_beam(p: vec3f) -> f32 {
    let L = ldir();
    let s = (-6.0 - p.z) / L.z;
    let w = p + L * s;
    return win_mask(w.xy) * step(0.0, s);
}

fn pulse(lt: f32) -> f32 {
    let x = lt - 1.2;
    let endp = f32(NCUBE - 1 - K0) * STEP + 0.6;
    if (x < 0.0 || x > endp) { return 0.0; }
    let age = fract(x / STEP) * STEP;
    return exp(-age * 7.0);
}

fn cube(k: i32, t: f32) -> Cube {
    let col = f32(k % 10);
    let row = f32(k / 10);
    let home = vec3f(-0.9 + 0.2 * col, 0.95 + 0.2 * row, 0.06);
    if (k < K0) { return Cube(home, 0.075, 0.0, 1.0); }
    let a = 1.2 + f32(k - K0) * STEP;
    let f = clamp((t - a + 1.2) / 1.2, 0.0, 1.0);
    let endt = 1.2 + f32(NCUBE - 1 - K0) * STEP + 1.0;
    let st = endt + f32(NCUBE - 1 - k) / f32(NCUBE - K0) * 2.0;
    let shrink = 1.0 - clamp((t - st) / 0.6, 0.0, 1.0);
    let e = 1.0 - pow(1.0 - f, 3.0);
    let hh = select(0.0, 0.075 * shrink * smoothstep(0.0, 0.25, f), f > 0.0);
    let off = vec3f(0.35 * sin(f32(k) * 2.3), 1.1, 0.9) * (1.0 - e);
    let age = t - a;
    let fl = select(0.0, exp(-age * 2.5), age > 0.0) * shrink;
    return Cube(home + off, hh, fl, step(1.0, f));
}

fn bnorm(p: vec3f, c: vec3f, h: vec3f) -> vec3f {
    let q = (p - c) / h;
    let a = abs(q);
    if (a.x > a.y && a.x > a.z) { return vec3f(sign(q.x), 0.0, 0.0); }
    if (a.y > a.z) { return vec3f(0.0, sign(q.y), 0.0); }
    return vec3f(0.0, 0.0, sign(q.z));
}

fn cap_t(ro: vec3f, rd: vec3f, pa: vec3f, pb: vec3f, r: f32) -> f32 {
    let ba = pb - pa;
    let oa = ro - pa;
    let baba = dot(ba, ba);
    let bard = dot(ba, rd);
    let baoa = dot(ba, oa);
    let rdoa = dot(rd, oa);
    let oaoa = dot(oa, oa);
    let a = baba - bard * bard;
    let b = baba * rdoa - baoa * bard;
    let c = baba * oaoa - baoa * baoa - r * r * baba;
    let h = b * b - a * c;
    if (h >= 0.0) {
        let t = (-b - sqrt(h)) / a;
        let y = baoa + t * bard;
        if (y > 0.0 && y < baba) { return t; }
        let oc = select(ro - pb, oa, y <= 0.0);
        let b2 = dot(rd, oc);
        let c2 = dot(oc, oc) - r * r;
        let h2 = b2 * b2 - c2;
        if (h2 > 0.0) { return -b2 - sqrt(h2); }
    }
    return -1.0;
}

fn cap_n(p: vec3f, pa: vec3f, pb: vec3f) -> vec3f {
    let ba = pb - pa;
    let h = clamp(dot(p - pa, ba) / dot(ba, ba), 0.0, 1.0);
    return normalize(p - pa - ba * h);
}

fn light_at(p: vec3f, n: vec3f) -> vec3f {
    let L = ldir();
    let b = in_beam(p);
    let lp = HALO_C - p;
    let ld = normalize(lp);
    let hal = max(dot(n, ld), 0.0) * 1.6 / (1.0 + dot(lp, lp) * 0.5);
    let fill = max(dot(n, normalize(vec3f(0.4, 0.6, 0.7))), 0.0) * 0.25;
    return vec3f(0.30, 0.29, 0.30) * (0.7 + 0.3 * n.y) + SUN * max(dot(n, L), 0.0) * b * 2.2 + vec3f(1.0, 0.9, 0.72) * (hal + fill);
}

fn cube_shadow(p: vec3f, lt: f32) -> f32 {
    let L = ldir();
    let s = (0.06 - p.z) / L.z;
    if (s <= 0.0) { return 1.0; }
    let q = p + L * s;
    var sh = 1.0;
    if (abs(q.x) < 1.15 && q.y > 0.85 && q.y < 2.42) { sh = 0.86; }
    let g = vec2f((q.x + 0.9) / 0.2, (q.y - 0.95) / 0.2);
    let ci = floor(g + 0.5);
    if (ci.x < 0.0 || ci.x > 9.0 || ci.y < 0.0 || ci.y > 6.0) { return sh; }
    let k = i32(ci.y) * 10 + i32(ci.x);
    let c = cube(k, lt);
    let loc = abs(g - ci) * 0.2;
    let inside = 1.0 - smoothstep(c.h - 0.012, c.h + 0.012, max(loc.x, loc.y));
    return sh * (1.0 - 0.85 * inside * c.home * step(0.001, c.h));
}

fn floor_col(p: vec3f, lt: f32, pl: f32) -> vec3f {
    var base = vec3f(0.20, 0.19, 0.18) * (0.8 + 0.35 * noise3(vec3f(p.x * 1.7, 0.5, p.z * 1.7)));
    let g = abs(fract(p.xz / 2.0) - 0.5);
    base *= mix(0.7, 1.0, 1.0 - smoothstep(0.47, 0.49, max(g.x, g.y)));
    let b = in_beam(p);
    var sh = 1.0;
    if (b > 0.0) { sh = cube_shadow(p, lt); }
    let hd = dot(p.xz, p.xz);
    let c = base * (vec3f(0.42, 0.40, 0.40) + SUN * b * sh * 2.6 + (vec3f(1.0, 0.88, 0.7) + TEAL * pl * 0.6) * 0.9 / (1.0 + hd * 0.6));
    var ao = 1.0;
    let f1 = p.xz - vec2f(-1.35, 0.45);
    let f2 = p.xz - vec2f(1.35, 0.45);
    let f3 = p.xz - vec2f(0.0, -1.2);
    ao *= 1.0 - 0.55 * exp(-dot(f1, f1) * 25.0);
    ao *= 1.0 - 0.55 * exp(-dot(f2, f2) * 25.0);
    ao *= 1.0 - 0.55 * exp(-dot(f3, f3) * 25.0);
    ao *= 1.0 - 0.35 * exp(-p.z * p.z * 4.0) * (1.0 - smoothstep(0.9, 1.5, abs(p.x)));
    let edge = min(6.0 - abs(p.x), 6.0 - abs(p.z));
    ao *= mix(0.55, 1.0, smoothstep(0.0, 1.4, edge));
    return c * ao;
}

fn ceil_col(p: vec3f, pl: f32) -> vec3f {
    let d = p.xz;
    let g = 1.8 / (1.0 + dot(d, d) * 0.35);
    let edge = min(6.0 - abs(p.x), 6.0 - abs(p.z));
    return IVORY * 0.5 * (vec3f(0.35) + (vec3f(1.0, 0.86, 0.66) + TEAL * pl * 0.5) * g) * mix(0.6, 1.0, smoothstep(0.0, 1.5, edge));
}

fn wall_col(p: vec3f, tt: f32, pl: f32) -> vec3f {
    var id = 0;
    var u = p.x;
    if (abs(p.x) > abs(p.z)) { id = select(2, 3, p.x > 0.0); u = p.z; } else { id = select(0, 1, p.z > 0.0); }
    let fid = f32(id);
    let v = p.y;
    var base = IVORY * 0.78 * (0.9 + 0.2 * noise3(p * 2.5));
    // sketches of finished rooms drifting up and dissolving
    let sv = v - tt * 0.18;
    let cell = floor(vec2f(u, sv) / 1.5);
    let hc = hash13(vec3f(cell, fid + 1.0));
    let lc = (fract(vec2f(u, sv) / 1.5) - 0.5) * 1.5;
    let sz = 0.28 + 0.22 * hash13(vec3f(cell + 3.1, fid));
    let qd = abs(lc + (vec2f(hc, fract(hc * 7.3)) - 0.5) * 0.25);
    let wob = (noise3(vec3f(u * 7.0, v * 7.0, fid)) - 0.5) * 0.02;
    let sq = abs(max(qd.x, qd.y) - sz) + wob;
    var ln = 1.0 - smoothstep(0.004, 0.014, abs(sq));
    ln *= select(1.0, 0.0, min(qd.x, qd.y) < sz * 0.2);
    let thr = (v - 1.2) / 3.0;
    let keep = smoothstep(thr - 0.12, thr + 0.12, noise3(vec3f(u * 10.0, v * 10.0, fid * 3.0)));
    let fade = smoothstep(0.5, 1.5, v) * (1.0 - smoothstep(3.6, 4.4, v));
    let a = ln * keep * fade * step(0.4, hc) * 0.6;
    let inkc = select(GRAPH * 2.0, TEAL * 0.6, hc > 0.92);
    base = mix(base, inkc, a);
    let hdv = p - HALO_C;
    let ao = mix(0.55, 1.0, smoothstep(0.0, 1.0, min(v, ROOM_HEIGHT - v))) * mix(0.6, 1.0, smoothstep(0.0, 1.2, 6.0 - abs(u)));
    var c = base * (vec3f(0.5, 0.48, 0.46) + (vec3f(1.0, 0.88, 0.7) + TEAL * pl * 0.4) * 1.6 / (1.0 + dot(hdv, hdv) * 0.12)) * ao;
    // grid panels: cells light up one by one
    let au = abs(u);
    if (au > 1.4 && au < 5.0 && v > 0.9 && v < 2.7) {
        let side = select(0.0, 1.0, u > 0.0);
        let pid = fid * 2.0 + side;
        let pu = vec2f(au - 1.4, v - 0.9);
        let ci = floor(pu / 0.3);
        let lc2 = fract(pu / 0.3) - 0.5;
        let prog = fract(tt / 15.0 + pid * 0.173) * 1.12;
        let h = hash13(vec3f(ci, pid + 11.0));
        let age = (prog - h) * 15.0 / 1.12;
        let sqc = max(abs(lc2.x), abs(lc2.y));
        let cellm = 1.0 - smoothstep(0.36, 0.40, sqc);
        var cc = vec3f(0.17, 0.17, 0.18);
        if (age > 0.0) { cc = TEAL * 0.32 + vec3f(0.03) + (TEAL * 2.2 + vec3f(0.8)) * exp(-age * 1.6); }
        var pc = mix(GRAPH * 0.9, cc, cellm);
        let ed = min(min(pu.x, 3.6 - pu.x), min(pu.y, 1.8 - pu.y));
        pc = mix(IVORY * 0.9, pc, smoothstep(0.015, 0.03, ed));
        c = pc + c * 0.05;
    }
    if (id == 0) {
        let wm = win_mask(vec2f(p.x, p.y));
        let wc = vec2f(p.x + 0.6, p.y - 3.6);
        c += SUN * 0.35 * exp(-dot(wc, wc) * 0.8);
        let sky = mix(vec3f(1.8, 1.6, 1.3), vec3f(1.2, 1.4, 1.6), smoothstep(2.9, 4.3, p.y));
        c = mix(c, sky, wm);
    }
    return c;
}

fn cubes(ro: vec3f, rd: vec3f, tmin: f32, best: Op, lt: f32) -> Op {
    var o = best;
    let bs = box_span(ro, rd, vec3f(-1.35, 0.85, -0.05), vec3f(1.35, 3.4, 1.05));
    if (bs.x > bs.y || bs.y < tmin || bs.x > o.t) { return o; }
    var hk = -1;
    var hc = Cube(vec3f(0.0), 0.0, 0.0, 0.0);
    for (var k = 0; k < NCUBE; k = k + 1) {
        let c = cube(k, lt);
        if (c.h <= 0.0) { continue; }
        let sp = box_span(ro, rd, c.c - vec3f(c.h), c.c + vec3f(c.h));
        if (sp.x <= sp.y && sp.x > tmin && sp.x < o.t) { o.t = sp.x; hk = k; hc = c; }
    }
    if (hk >= 0) {
        let p = ro + rd * o.t;
        let n = bnorm(p, hc.c, vec3f(hc.h));
        let q = (p - hc.c) / hc.h;
        var uv = q.xy;
        if (abs(n.x) > 0.5) { uv = q.zy; }
        if (abs(n.y) > 0.5) { uv = q.xz; }
        let edge = max(abs(uv.x), abs(uv.y));
        let tint = 0.85 + 0.15 * hash12(vec2f(f32(hk), 3.0));
        var base = IVORY * 0.82 * tint;
        base = mix(base, GRAPH, smoothstep(0.84, 0.92, edge));
        var door = 0.0;
        if (abs(n.y) < 0.5) { door = (1.0 - smoothstep(0.13, 0.18, abs(uv.x))) * (1.0 - smoothstep(0.1, 0.17, uv.y)); }
        base = mix(base, GRAPH * 0.6, door);
        var cc = base * light_at(p, n);
        cc += TEAL * hc.flash * (0.5 + 2.5 * door) + TEAL * 0.15 * door;
        o.col = cc;
    }
    return o;
}

fn halo_sd(p: vec3f, tt: f32) -> vec2f {
    var q = p - HALO_C;
    let xz = rot2(tt * 0.45) * q.xz;
    q = vec3f(xz.x, q.y, xz.y);
    let yz = rot2(0.4 + 0.1 * sin(tt * 0.37)) * q.yz;
    q = vec3f(q.x, yz.x, yz.y);
    let d = length(vec2f(length(q.xz) - 0.62, q.y)) - 0.028;
    return vec2f(d, atan2(q.z, q.x));
}

fn halo(ro: vec3f, rd: vec3f, tmin: f32, tend: f32, tt: f32, pl: f32) -> vec4f {
    let oc = ro - HALO_C;
    let b = dot(oc, rd);
    let c = dot(oc, oc) - 0.85 * 0.85;
    let disc = b * b - c;
    if (disc < 0.0) { return vec4f(0.0, 0.0, 0.0, -1.0); }
    let sq = sqrt(disc);
    var t = max(-b - sq, tmin);
    let t1 = min(-b + sq, tend);
    var g = vec3f(0.0);
    let n = i32(mix(18.0, 36.0, quality()));
    let warm = vec3f(1.0, 0.82, 0.55);
    for (var i = 0; i < 36; i = i + 1) {
        if (i >= n || t > t1) { break; }
        let s = halo_sd(ro + rd * t, tt);
        let br = 0.55 + 0.45 * sin(s.y * 3.0 - tt * 2.0);
        let gc = mix(warm, TEAL, clamp(pl * 0.8 + 0.15 * sin(s.y * 2.0 + tt), 0.0, 1.0)) * br;
        if (s.x < 0.002) { return vec4f(g + gc * 3.0 + vec3f(0.6), t); }
        let dt = max(s.x * 0.7, 0.01);
        g += gc * dt * 0.035 / (s.x * s.x + 0.002);
        t += dt;
    }
    return vec4f(g, -1.0);
}

fn glass_over(col: vec3f, n0: vec3f, rd: vec3f, p: vec3f, a: f32) -> vec3f {
    let n = select(n0, -n0, dot(n0, rd) > 0.0);
    let fres = pow(1.0 - abs(dot(n, rd)), 4.0);
    let r = reflect(rd, n);
    let sp = pow(max(dot(r, ldir()), 0.0), 48.0) * 4.0 + pow(max(dot(r, normalize(HALO_C - p)), 0.0), 24.0) * 1.5;
    let gc = vec3f(0.75, 0.92, 0.9) * 0.55 + IVORY * fres * 1.2 + SUN * sp;
    let aa = clamp(a + fres * 0.55, 0.0, 0.9);
    return mix(col, gc, aa) + SUN * sp * 0.3;
}

fn beam_scatter(ro: vec3f, rd: vec3f, t0: f32, t1: f32, tt: f32) -> vec3f {
    let n = i32(mix(8.0, 16.0, quality()));
    let dt = max(t1 - t0, 0.0) / f32(n);
    let j = hash13(rd * 1543.7);
    var acc = 0.0;
    for (var i = 0; i < 16; i = i + 1) {
        if (i >= n) { break; }
        let p = ro + rd * (t0 + (f32(i) + j) * dt);
        acc += in_beam(p) * (0.5 + 0.9 * noise3(p * 1.3 + vec3f(0.0, -tt * 0.05, tt * 0.03)));
    }
    return SUN * acc * dt * 0.07;
}

fn motes(ro: vec3f, rd: vec3f, t0: f32, t1: f32, tt: f32) -> vec3f {
    let L = ldir();
    let nm = i32(mix(16.0, 32.0, quality()));
    var g = 0.0;
    for (var i = 0; i < 32; i = i + 1) {
        if (i >= nm) { break; }
        let fi = f32(i);
        let h = hash33(vec3f(fi, 7.0, 3.0));
        let w = vec3f(mix(-1.7, 0.5, h.x), mix(2.9, 4.3, h.y), -6.0);
        let s = 0.5 + 9.5 * fract(h.z + tt * 0.008);
        let p = w - L * s + vec3f(sin(tt * 0.31 + fi * 1.7), sin(tt * 0.23 + fi * 2.9), cos(tt * 0.27 + fi)) * 0.12;
        let tp = dot(p - ro, rd);
        if (tp < t0 || tp > t1) { continue; }
        let d = length(p - ro - rd * tp);
        let r = 0.004 + 0.0018 * tp;
        let tw = 0.55 + 0.45 * sin(tt * 2.0 + fi * 4.1);
        g += exp(-d * d / (r * r)) * tw * in_beam(p);
    }
    return SUN * g * 1.4;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let tt = time();
    let lt = fract(tt / CYC) * CYC;
    let pl = pulse(lt);
    let tb = horizon_t(tmax);
    let pe = ro + rd * tb;
    var o = Op(tb, vec3f(0.0));
    if (pe.y < 0.02) { o.col = floor_col(pe, lt, pl); }
    else if (pe.y > ROOM_HEIGHT - 0.02) { o.col = ceil_col(pe, pl); }
    else { o.col = wall_col(pe, tt, pl); }

    o = cubes(ro, rd, tmin, o, lt);

    let hv = halo(ro, rd, tmin, o.t, tt, pl);
    if (hv.w > 0.0) { o.t = hv.w; o.col = vec3f(0.0); }
    var col = o.col + hv.rgb;

    // glass pane with faint guide grid
    if (abs(rd.z) > 1e-4) {
        let tp = (-0.04 - ro.z) / rd.z;
        if (tp > tmin && tp < o.t) {
            let p = ro + rd * tp;
            let e = min(1.15 - abs(p.x), min(p.y - 0.85, 2.42 - p.y));
            if (e > 0.0) {
                let gx = abs(fract((p.x + 1.0) / 0.2 + 0.5) - 0.5) * 0.2;
                let gy = abs(fract((p.y - 0.85) / 0.2 + 0.5) - 0.5) * 0.2;
                let grid = (1.0 - smoothstep(0.002, 0.006, min(gx, gy))) * step(abs(p.x), 1.0) * step(p.y, 2.25);
                col = glass_over(col, vec3f(0.0, 0.0, 1.0), rd, p, 0.07 + 0.55 * (1.0 - smoothstep(0.0, 0.035, e)));
                col += TEAL * grid * (0.12 + 0.5 * pl);
            }
        }
    }
    let lmin = vec3f(-1.32, 0.76, -0.14);
    let lmax = vec3f(1.32, 0.84, 0.2);
    let ls = box_span(ro, rd, lmin, lmax);
    if (ls.x <= ls.y && ls.x > tmin && ls.x < o.t) {
        let p = ro + rd * ls.x;
        col = glass_over(col, bnorm(p, (lmin + lmax) * 0.5, (lmax - lmin) * 0.5), rd, p, 0.35);
    }
    let cmin = vec3f(-0.2, 2.42, -0.12);
    let cmax = vec3f(0.2, 2.5, 0.06);
    let cs = box_span(ro, rd, cmin, cmax);
    if (cs.x <= cs.y && cs.x > tmin && cs.x < o.t) {
        let p = ro + rd * cs.x;
        col = glass_over(col, bnorm(p, (cmin + cmax) * 0.5, (cmax - cmin) * 0.5), rd, p, 0.4);
    }
    for (var i = 0; i < 3; i = i + 1) {
        var pa = vec3f(-1.35, 0.0, 0.45);
        var pb = vec3f(-1.2, 2.75, -0.05);
        if (i == 1) { pa = vec3f(1.35, 0.0, 0.45); pb = vec3f(1.2, 2.75, -0.05); }
        if (i == 2) { pa = vec3f(0.0, 0.0, -1.2); pb = vec3f(0.0, 2.6, -0.12); }
        let tl = cap_t(ro, rd, pa, pb, 0.03);
        if (tl > tmin && tl < o.t) {
            let p = ro + rd * tl;
            col = glass_over(col, cap_n(p, pa, pb), rd, p, 0.3);
        }
    }

    let t1 = min(o.t, tb);
    col += beam_scatter(ro, rd, tmin, t1, tt) + motes(ro, rd, tmin, t1, tt);
    return Hit(tone(col * 1.15), clamp(o.t, tmin, tmax));
}

shaders.16a8c3252930bb15be4f734f0d97:
// Vigil Under the Oculus: a night chapel for those who wait for the station to come home.
// A pale stone altar with a silver bowl under a wide open oculus; stars turn, the station arcs past again and again,
// amber candles line the walls, a silver thread of light rises from the bowl and swells as the station passes.
const OR: f32 = 2.6;
const LEDGE: f32 = 0.85;
const GOLD: vec3f = vec3f(1.0, 0.55, 0.18);
const SILV: vec3f = vec3f(0.55, 0.7, 1.0);
const IND: vec3f = vec3f(0.025, 0.03, 0.09);
const BOWL: vec3f = vec3f(0.0, 1.92, 0.0);

var<private> T: f32;
var<private> STAZ: f32;
var<private> STD: vec3f;
var<private> SWELL: f32;
var<private> LK: vec3f;
var<private> MAT: i32;
var<private> CFAVG: f32;
var<private> CP: array<vec4f, 24>;
var<private> CF: array<f32, 24>;

fn path_el(az: f32) -> f32 { return 0.8 + 0.2 * sin(az * 2.0 + 0.5); }

fn setup() {
    T = time();
    STAZ = T * 1.05;
    let el = path_el(STAZ);
    STD = vec3f(cos(el) * cos(STAZ), sin(el), cos(el) * sin(STAZ));
    SWELL = smoothstep(0.78, 0.96, el);
    LK = normalize(vec3f(0.1, 1.0, 0.06));
    let breath = 0.85 + 0.15 * sin(T * 0.45);
    var s = 0.0;
    for (var i = 0; i < 24; i = i + 1) {
        let fi = f32(i);
        let w = i / 6;
        let k = i % 6;
        let sg = select(-1.0, 1.0, k >= 3);
        let u = sg * (1.75 + f32(k % 3) * 1.45);
        let h = 0.12 + 0.2 * hash12(vec2f(fi, 3.1));
        var p = vec3f(-5.78, LEDGE, u);
        if (w == 1) { p = vec3f(5.78, LEDGE, -u); }
        else if (w == 2) { p = vec3f(u, LEDGE, -5.78); }
        else if (w == 3) { p = vec3f(-u, LEDGE, 5.78); }
        CP[i] = vec4f(p, h);
        let hh = hash12(vec2f(fi, 9.7));
        let f = breath * (0.8 + 0.2 * sin(T * (0.7 + 0.5 * hh) + hh * 40.0) * sin(T * 1.9 + hh * 13.0));
        CF[i] = f;
        s += f;
    }
    CFAVG = s / 24.0;
}

fn tm(c: vec3f, rd: vec3f) -> vec3f {
    let fw = room.inv_rot_proj * vec4f(0.0, 0.0, 0.5, 1.0);
    let vig = 1.0 - 0.3 * smoothstep(0.97, 0.55, dot(rd, normalize(fw.xyz / fw.w)));
    let x = max(c, vec3f(0.0)) * vig;
    let y = (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14);
    return clamp(y + (hash13(rd * 913.7) - 0.5) / 255.0, vec3f(0.0), vec3f(1.0));
}

fn candle_light(p: vec3f, n: vec3f) -> f32 {
    var s = 0.0;
    for (var i = 0; i < 24; i = i + 1) {
        let f = CP[i].xyz + vec3f(0.0, CP[i].w + 0.06, 0.0);
        let v = f - p;
        let d2 = dot(v, v);
        s += CF[i] * max(dot(n, v) * inverseSqrt(d2), 0.0) / (0.05 + d2);
    }
    return s;
}

fn flames(ro: vec3f, rd: vec3f, tend: f32, blur: f32) -> vec3f {
    var c = vec3f(0.0);
    for (var i = 0; i < 24; i = i + 1) {
        let cp = CP[i];
        let sway = 0.006 * sin(T * 2.1 + f32(i) * 1.7);
        let f = cp.xyz + vec3f(sway, cp.w + 0.05, 0.0);
        let v = f - ro;
        let tp = dot(v, rd);
        if (tp > 0.05 && tp < tend) {
            let dv = ro + rd * tp - f;
            let e = vec3f(dv.x, dv.y * 0.45, dv.z);
            let s = (0.0001 + 0.0000015 * tp * tp) * blur;
            let fl = CF[i];
            c += vec3f(1.0, 0.8, 0.45) * exp(-dot(e, e) / s) * 4.0 * fl;
            c += GOLD * fl * (0.03 / (1.0 + dot(dv, dv) * 120.0) + 0.006 / (1.0 + dot(dv, dv) * 6.0));
        }
    }
    return c;
}

fn sky(rd: vec3f) -> vec3f {
    let y = max(rd.y, 0.0);
    var c = mix(vec3f(0.05, 0.06, 0.17), vec3f(0.008, 0.01, 0.04), sqrt(y));
    let xz = rot2(T * 0.03) * rd.xz;
    let r = vec3f(xz.x, rd.y, xz.y);
    let bd = dot(r, normalize(vec3f(0.35, 0.25, 1.0)));
    let neb = noise3(r * 5.0) * 0.6 + noise3(r * 14.0) * 0.4;
    c += vec3f(0.09, 0.1, 0.24) * exp(-bd * bd * 9.0) * neb;
    for (var k = 0; k < 2; k = k + 1) {
        let fk = f32(k);
        let q = r * (60.0 + fk * 55.0);
        let id = floor(q);
        let h = hash33(id + fk * 31.0);
        let d = length(q - id - 0.2 - 0.6 * h);
        let tw = 0.6 + 0.4 * sin(T * (1.5 + 2.0 * h.y) + h.z * 30.0);
        let sc = mix(vec3f(0.75, 0.85, 1.0), vec3f(1.0, 0.85, 0.6), h.z);
        c += sc * exp(-d * d * 60.0) * step(0.62, h.x) * tw * (0.6 + 2.0 * h.y * h.y);
    }
    // the station's arc: a faint ghost of the whole path, brighter just behind the light
    let a = atan2(rd.z, rd.x);
    let erd = asin(clamp(rd.y, -1.0, 1.0));
    let de = erd - path_el(a);
    let lag = fract((STAZ - a) / TAU) * TAU;
    let trl = exp(-de * de / 0.000006);
    c += vec3f(0.6, 0.72, 1.0) * trl * (0.04 + 0.7 * exp(-lag * 1.6));
    let ca = max(1.0 - dot(rd, STD), 0.0) * 2.0;
    c += vec3f(1.0, 0.95, 0.85) * (exp(-ca / 0.000012) * 6.0 + exp(-ca / 0.0006) * 0.6 + exp(-ca / 0.01) * 0.12);
    return c;
}

fn cylv(p: vec3f, r: f32, y0: f32, y1: f32) -> f32 {
    let d = vec2f(length(p.xz) - r, abs(p.y - 0.5 * (y0 + y1)) - 0.5 * (y1 - y0));
    return min(max(d.x, d.y), 0.0) + length(max(d, vec2f(0.0)));
}

fn map(p: vec3f) -> f32 {
    var d = cylv(p, 1.9, 0.0, 0.13);
    d = min(d, cylv(p, 1.5, 0.0, 0.26));
    d = min(d, cylv(p, 1.1, 0.0, 0.39));
    d = min(d, sd_box(p - vec3f(0.0, 0.48, 0.0), vec3f(0.66, 0.09, 0.52)) - 0.01);
    var body = sd_box(p - vec3f(0.0, 1.0, 0.0), vec3f(0.5, 0.45, 0.38)) - 0.01;
    let gq = p - vec3f(0.0, 1.3, 0.0);
    body = max(body, -max(sd_box(gq, vec3f(0.6, 0.02, 0.5)), -sd_box(gq, vec3f(0.48, 0.1, 0.36))));
    d = min(d, body);
    d = min(d, sd_box(p - vec3f(0.0, 1.55, 0.0), vec3f(0.66, 0.07, 0.5)) - 0.012);
    MAT = 0;
    let c = p - BOWL;
    let bowl = min(max(abs(length(c) - 0.3) - 0.016, c.y), cylv(p, 0.09, 1.6, 1.66));
    if (bowl < d) { d = bowl; MAT = 1; }
    let liq = max(length(c) - 0.29, c.y + 0.05);
    if (liq < d) { d = liq; MAT = 2; }
    return d;
}

fn calc_n(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn soft_shadow(p: vec3f, l: vec3f) -> f32 {
    let sp = box_span(p, l, vec3f(-1.95, 0.0, -1.95), vec3f(1.95, 2.25, 1.95));
    if (sp.x > sp.y || sp.y < 0.0) { return 1.0; }
    var t = max(sp.x, 0.02);
    var res = 1.0;
    for (var i = 0; i < 14; i = i + 1) {
        let h = map(p + l * t);
        res = min(res, 10.0 * h / t);
        t += clamp(h, 0.03, 0.4);
        if (res < 0.02 || t > sp.y) { break; }
    }
    return clamp(res, 0.0, 1.0);
}

fn beam_mask(p: vec3f) -> f32 {
    let q = p + LK * ((4.5 - p.y) / LK.y);
    return smoothstep(OR, OR - 0.35, length(q.xz));
}

fn shade_obj(p: vec3f, rd: vec3f, m: i32) -> vec3f {
    let n = calc_n(p);
    let ao = clamp(0.35 + 0.65 * map(p + n * 0.1) / 0.1, 0.25, 1.0);
    let bm = beam_mask(p);
    var sh = 0.0;
    if (bm > 0.01) { sh = soft_shadow(p + n * 0.012, LK); }
    let dk = max(dot(n, LK), 0.0);
    let kl = SILV * 1.4 * (1.0 + 0.7 * SWELL) * dk * sh * bm;
    let warm = GOLD * 0.4 * CFAVG * (0.5 + 0.5 * (1.0 - abs(n.y))) * ao;
    let amb = IND * (1.0 + 0.8 * n.y) * ao + SILV * 0.1 * (1.0 - abs(n.y)) * ao;
    let fres = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    if (m == 2) {
        let rip = 0.85 + 0.15 * sin(length(p.xz) * 60.0 - T * 3.0);
        return SILV * (0.6 + 1.8 * SWELL) * rip;
    }
    if (m == 1) {
        let r = reflect(rd, n);
        let e = mix(IND * 2.0, SILV * 0.7, smoothstep(0.1, 0.9, r.y)) + GOLD * 0.35 * CFAVG * exp(-abs(r.y) * 5.0);
        var c = vec3f(0.8, 0.83, 0.88) * (e * (0.5 + 0.5 * ao) + kl * 0.4);
        c += SILV * pow(max(dot(r, LK), 0.0), 40.0) * sh * bm * 1.5;
        if (length(p - BOWL) < 0.3) { c += SILV * 0.3 * (1.0 + 2.0 * SWELL); }
        return c;
    }
    var alb = vec3f(0.84, 0.81, 0.76) * (0.88 + 0.18 * noise3(p * 5.0));
    let vein = smoothstep(0.03, 0.0, abs(noise3(p * vec3f(2.5, 4.0, 2.5)) - 0.5));
    alb *= 1.0 - 0.18 * vein;
    var gild = 0.0;
    var glowd = 0.0;
    if (abs(n.y) < 0.5 && p.y > 0.6 && p.y < 1.26) {
        // fluted faces, each with a gilded orbit ring whose silver point follows the station
        let cu = select(p.x, p.z, abs(n.x) > 0.5);
        let uv = vec2f(cu, p.y - 0.93);
        let rl = length(uv);
        let flute = abs(sin(cu * 31.4));
        let inMed = smoothstep(0.31, 0.29, rl);
        alb *= mix(0.78 + 0.22 * flute, 1.0, inMed);
        gild = max(smoothstep(0.012, 0.005, abs(rl - 0.22)), smoothstep(0.05, 0.04, rl));
        let dp = 0.22 * vec2f(cos(STAZ), sin(STAZ));
        glowd = smoothstep(0.035, 0.018, length(uv - dp));
    }
    var c = alb * (kl + warm + amb);
    c = mix(c, vec3f(1.0, 0.72, 0.35) * (warm * 2.2 + kl * 0.8 + IND), gild);
    c += SILV * glowd * (0.8 + 1.5 * SWELL);
    c += SILV * fres * 0.06 * (0.3 + bm);
    return c;
}

fn ceiling(p: vec3f, rd: vec3f) -> vec3f {
    let r = length(p.xz);
    if (r < OR) { return sky(rd); }
    let a = atan2(p.z, p.x);
    let ru = r - OR;
    var alb = vec3f(0.1, 0.11, 0.2);
    let rf = fract(ru / 0.75);
    let seg = fract(a / TAU * 24.0);
    let rib = max(smoothstep(0.08, 0.0, min(rf, 1.0 - rf)), smoothstep(0.06, 0.0, min(seg, 1.0 - seg) * r * 0.26));
    alb = mix(alb, vec3f(0.5, 0.5, 0.52), rib);
    let cc = vec2f((rf - 0.5) * 0.75, (seg - 0.5) * 0.26 * r);
    let star = smoothstep(0.035, 0.0, length(cc));
    let rim = smoothstep(0.22, 0.18, ru);
    alb = mix(alb, vec3f(0.85, 0.83, 0.8), rim);
    let cl = candle_light(p, vec3f(0.0, -1.0, 0.0));
    var c = alb * (GOLD * cl * 0.06 + IND * 0.8 + SILV * 0.14 * exp(-ru * 1.2) * (1.0 + SWELL));
    c += vec3f(1.0, 0.7, 0.3) * star * (0.05 + cl * 0.05);
    return c;
}

fn wall(p: vec3f) -> vec3f {
    var n = vec3f(0.0, 0.0, -sign(p.z));
    var u = p.x;
    if (abs(p.x) > abs(p.z)) { n = vec3f(-sign(p.x), 0.0, 0.0); u = p.z; }
    let row = floor(p.y / 0.38);
    let bx = u / 0.75 + row * 0.5;
    let hb = hash12(vec2f(floor(bx), row + n.x * 7.0 + n.z * 13.0));
    let jx = fract(bx);
    let jy = fract(p.y / 0.38);
    let joint = max(smoothstep(0.03, 0.0, min(jx, 1.0 - jx) * 0.75), smoothstep(0.04, 0.0, min(jy, 1.0 - jy) * 0.38));
    let alb = vec3f(0.62, 0.6, 0.57) * (0.8 + 0.25 * hb) * (1.0 - 0.5 * joint);
    let cl = candle_light(p, n);
    return alb * (GOLD * cl * 0.06 + IND * 0.7 + SILV * 0.05 * smoothstep(1.5, 4.5, p.y));
}

fn floor_col(p: vec3f, rd: vec3f) -> vec3f {
    let g = abs(fract(p.xz) - 0.5);
    let grout = smoothstep(0.485, 0.497, max(g.x, g.y));
    let hb = hash12(floor(p.xz));
    let alb = vec3f(0.07, 0.075, 0.1) * (0.8 + 0.4 * hb) * (1.0 - 0.6 * grout);
    let cl = candle_light(p, vec3f(0.0, 1.0, 0.0));
    let bm = beam_mask(p);
    var sh = 1.0;
    if (bm > 0.01 && dot(p.xz, p.xz) < 6.0) { sh = soft_shadow(p + vec3f(0.0, 0.01, 0.0), LK); }
    var c = alb * (GOLD * cl * 0.25 + IND * 1.2 + SILV * bm * sh * 1.8 * (1.0 + 0.6 * SWELL));
    let rr = reflect(rd, vec3f(0.0, 1.0, 0.0));
    let tc = (4.5 - p.y) / max(rr.y, 0.001);
    let oc = length((p + rr * tc).xz);
    c += (1.0 - grout) * 0.12 * smoothstep(OR, OR - 0.3, oc) * vec3f(0.12, 0.15, 0.32);
    if (quality() > 0.3) { c += (1.0 - grout) * flames(p, rr, 30.0, 6.0) * 0.18; }
    return c;
}

fn rise_thread(ro: vec3f, rd: vec3f, tend: f32) -> vec3f {
    let a = dot(rd.xz, rd.xz);
    if (a < 1e-6) { return vec3f(0.0); }
    let tc = -dot(ro.xz, rd.xz) / a;
    if (tc < 0.0 || tc > tend) { return vec3f(0.0); }
    let p = ro + rd * tc;
    let h2 = dot(p.xz, p.xz);
    let ins = smoothstep(1.88, 2.0, p.y) * smoothstep(4.6, 4.3, p.y);
    let pulse = 0.6 + 0.4 * sin(p.y * 5.0 - T * 3.0);
    let inten = (0.3 + 1.7 * SWELL) * ins;
    return SILV * inten * (exp(-h2 / 0.00012) * 1.5 * pulse + 0.012 / (1.0 + h2 * 300.0) + 0.004 / (1.0 + h2 * 10.0));
}

fn shaft(ro: vec3f, rd: vec3f, tend: f32) -> vec3f {
    let o = ro - vec3f(0.0, 4.5, 0.0);
    let op = o - LK * dot(o, LK);
    let dp = rd - LK * dot(rd, LK);
    let A = dot(dp, dp);
    if (A < 1e-6) { return vec3f(0.0); }
    let B = dot(op, dp);
    let C = dot(op, op) - OR * OR * 0.9;
    let disc = B * B - A * C;
    if (disc <= 0.0) { return vec3f(0.0); }
    let s = sqrt(disc);
    let t0 = max((-B - s) / A, 0.0);
    var t1 = min((-B + s) / A, tend);
    if (rd.y > 0.0) { t1 = min(t1, (4.5 - ro.y) / rd.y); }
    if (t1 <= t0) { return vec3f(0.0); }
    let ym = ro.y + rd.y * 0.5 * (t0 + t1);
    return SILV * (t1 - t0) * (0.012 + 0.012 * ym / 4.5) * (1.0 + 1.2 * SWELL);
}

fn motes(ro: vec3f, rd: vec3f, tend: f32) -> vec3f {
    var c = vec3f(0.0);
    for (var i = 0; i < 16; i = i + 1) {
        let h = hash33(vec3f(f32(i), 1.3, 5.7));
        let ph = T * 0.2 + h.x * 10.0;
        let pos = vec3f((h.x - 0.5) * 4.2 + 0.2 * sin(ph), 0.2 + 4.1 * fract(h.y - T * 0.012 * (0.5 + h.z)), (h.z - 0.5) * 4.2 + 0.2 * cos(ph * 1.3));
        let v = pos - ro;
        let tp = dot(v, rd);
        if (tp > 0.2 && tp < tend) {
            let dd = length(v - rd * tp);
            c += SILV * exp(-dd * dd / (0.00003 * tp * tp + 0.000003)) * beam_mask(pos) * 0.5;
        }
    }
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    setup();
    var th = horizon_t(tmax);
    var col = vec3f(0.0);
    var best = 1e9;
    var kind = -1;
    var am = 0;
    let sp = box_span(ro, rd, vec3f(-1.95, 0.0, -1.95), vec3f(1.95, 2.0, 1.95));
    let t0 = max(sp.x, tmin);
    let t1 = min(sp.y, tmax);
    if (sp.x <= sp.y && t0 < t1) {
        let steps = i32(mix(32.0, 72.0, quality()));
        var t = t0;
        var hit = false;
        for (var i = 0; i < steps; i = i + 1) {
            let d = map(ro + rd * t);
            if (d < 0.0005 + 0.0008 * t) { hit = true; break; }
            t += d * 0.9;
            if (t > t1) { break; }
        }
        if (hit && t <= t1) { best = t; kind = 2; am = MAT; }
    }
    // stone ledges along the walls, clear of the doorways
    var ln = vec3f(0.0, 1.0, 0.0);
    var cid = 0;
    for (var i = 0; i < 8; i = i + 1) {
        let w = i / 2;
        let pos = (i % 2) == 1;
        let lo = select(-6.0, 1.3, pos);
        let hi = select(-1.3, 6.0, pos);
        var bmin = vec3f(-6.01, 0.0, lo);
        var bmax = vec3f(-5.6, LEDGE, hi);
        if (w == 1) { bmin = vec3f(5.6, 0.0, lo); bmax = vec3f(6.01, LEDGE, hi); }
        else if (w == 2) { bmin = vec3f(lo, 0.0, -6.01); bmax = vec3f(hi, LEDGE, -5.6); }
        else if (w == 3) { bmin = vec3f(lo, 0.0, 5.6); bmax = vec3f(hi, LEDGE, 6.01); }
        let s = box_span(ro, rd, bmin, bmax);
        if (s.x <= s.y && s.x > tmin && s.x < best && s.x < tmax) {
            best = s.x;
            kind = 0;
            let p = ro + rd * s.x;
            let q = (p - 0.5 * (bmin + bmax)) / (0.5 * (bmax - bmin));
            let aq = abs(q);
            if (aq.y > aq.x && aq.y > aq.z) { ln = vec3f(0.0, sign(q.y), 0.0); }
            else if (aq.x > aq.z) { ln = vec3f(sign(q.x), 0.0, 0.0); }
            else { ln = vec3f(0.0, 0.0, sign(q.z)); }
        }
    }
    // the candles themselves
    for (var i = 0; i < 24; i = i + 1) {
        let c = CP[i];
        let oc = ro.xz - c.xz;
        let a = dot(rd.xz, rd.xz);
        let b = dot(oc, rd.xz);
        let cc = dot(oc, oc) - 0.0014;
        let disc = b * b - a * cc;
        if (disc > 0.0 && a > 1e-8) {
            let t = (-b - sqrt(disc)) / a;
            let y = ro.y + rd.y * t;
            if (t > tmin && t < best && y > LEDGE && y < LEDGE + c.w) {
                best = t;
                kind = 1;
                cid = i;
                let hp = oc + rd.xz * t;
                ln = normalize(vec3f(hp.x, 0.0, hp.y));
            }
        }
        if (rd.y < 0.0) {
            let tcap = (LEDGE + c.w - ro.y) / rd.y;
            let hp = ro.xz + rd.xz * tcap - c.xz;
            if (tcap > tmin && tcap < best && dot(hp, hp) < 0.0014) { best = tcap; kind = 1; cid = i; ln = vec3f(0.0, 1.0, 0.0); }
        }
    }
    if (kind == 2) {
        th = best;
        col = shade_obj(ro + rd * best, rd, am);
    } else if (kind == 0) {
        th = best;
        let p = ro + rd * best;
        let alb = vec3f(0.6, 0.58, 0.55) * (0.88 + 0.12 * sin(p.x * 3.1 + p.z * 2.3));
        col = alb * (GOLD * candle_light(p + ln * 0.01, ln) * 0.06 + IND * 0.8);
    } else if (kind == 1) {
        th = best;
        let p = ro + rd * best;
        let c = CP[cid];
        let fl = CF[cid];
        let glow = exp(-(LEDGE + c.w - p.y) * 14.0);
        col = vec3f(0.85, 0.8, 0.68) * (IND * 1.5 + GOLD * 0.25 * fl) + vec3f(1.0, 0.6, 0.25) * glow * 0.9 * fl;
    } else {
        let pe = ro + rd * th;
        if (abs(pe.x) > 6.05 || abs(pe.z) > 6.05 || pe.y < -0.05 || pe.y > 4.55) { return no_hit(); }
        if (pe.y > 4.47) { col = ceiling(pe, rd); }
        else if (pe.y < 0.03) { col = floor_col(pe, rd); }
        else { col = wall(pe); }
    }
    var c = mix(col, IND * 0.5, (1.0 - exp(-th * 0.03)) * 0.5);
    c += flames(ro, rd, th, 1.0);
    c += rise_thread(ro, rd, th);
    c += shaft(ro, rd, th);
    // a soft silver halo hovering over the bowl
    let bv = BOWL + vec3f(0.0, 0.05, 0.0) - ro;
    let btp = dot(bv, rd);
    if (btp > 0.0 && btp < th + 0.3) {
        let bd = length(bv - rd * btp);
        c += SILV * (0.3 + SWELL) * 0.03 / (1.0 + bd * bd * 30.0);
    }
    if (quality() > 0.4) { c += motes(ro, rd, th); }
    return Hit(tm(c * 1.4, rd), clamp(th, tmin, tmax));
}

shaders.0ac2861264bab109949b7eefbf52:
// Hall of the Worn Faces: a ruined hall of weathered moai, sun shafts, trees and birds.
fn sun_dir() -> vec3f { return normalize(vec3f(0.35, 0.8, -0.5)); }
const SUNC: vec3f = vec3f(2.6, 1.9, 1.05);

var<private> MAT: i32;
var<private> SID: f32;

fn sky(rd: vec3f) -> vec3f {
    let y = clamp(rd.y, 0.0, 1.0);
    var c = mix(vec3f(1.1, 0.9, 0.6), vec3f(0.5, 0.68, 0.95), pow(y, 0.6));
    let s = max(dot(rd, sun_dir()), 0.0);
    c += vec3f(1.6, 1.2, 0.7) * (pow(s, 8.0) * 0.6 + pow(s, 200.0) * 3.0);
    return c;
}

fn hole(xz: vec2f) -> f32 {
    let n = (noise3(vec3f(xz * 1.4, 2.0)) - 0.5) * 0.9;
    var h = smoothstep(1.3, 1.0, length(xz - vec2f(0.3, -4.0)) + n);
    h = max(h, smoothstep(1.0, 0.7, length(xz - vec2f(-2.3, -2.6)) + n));
    h = max(h, smoothstep(1.0, 0.7, length(xz - vec2f(4.1, 0.6)) + n));
    h = max(h, smoothstep(1.2, 0.9, length((xz - vec2f(-0.6, 1.8)) * vec2f(1.0, 0.75)) + n));
    h = max(h, smoothstep(0.9, 0.6, length(xz - vec2f(-2.3, 3.0)) + n));
    h = max(h, smoothstep(1.3, 1.0, length(xz - vec2f(2.6, 4.6)) + n));
    h = max(h, smoothstep(1.5, 1.1, length(xz - vec2f(-5.0, -0.6)) + n));
    h = max(h, smoothstep(1.5, 1.1, length(xz - vec2f(5.0, -3.4)) + n));
    h = max(h, smoothstep(1.5, 1.1, length(xz - vec2f(5.0, 2.3)) + n));
    return h;
}

fn sun_at(p: vec3f) -> f32 {
    let ld = sun_dir();
    return hole(p.xz + ld.xz * ((4.5 - p.y) / ld.y));
}

fn moai(q: vec3f, id: f32) -> f32 {
    let h = hash33(vec3f(id * 1.37 + 0.5, 3.1, 7.7));
    let nod = (h.x - 0.5) * 0.3;
    let tilt = (h.y - 0.5) * 0.16;
    let mc = (h.z - 0.5) * 2.4;
    let bt = (fract(h.x * 13.7 + h.z) - 0.5) * 0.5;
    var d = sd_box(q - vec3f(0.0, 0.15, 0.0), vec3f(0.72, 0.15, 0.78)) - 0.03;
    let tw = 1.0 - 0.12 * clamp((q.y - 0.3) / 1.3, 0.0, 1.0);
    d = min(d, sd_box(q - vec3f(0.05, 0.95, 0.0), vec3f(0.36 * tw, 0.62, 0.52 * tw)) - 0.12);
    var hq = q - vec3f(0.0, 1.5, 0.0);
    let a = rot2(nod) * hq.xy;
    hq = vec3f(a.x, a.y, hq.z);
    let b = rot2(tilt) * vec2f(hq.z, hq.y);
    hq = vec3f(hq.x, b.y, b.x);
    var hd = sd_box(hq - vec3f(0.02, 0.88, 0.0), vec3f(0.38, 0.8, 0.36)) - 0.1;
    var bq = hq - vec3f(-0.4, 1.24, 0.0);
    let c = rot2(bt) * vec2f(bq.z, bq.y);
    bq = vec3f(bq.x, c.y, c.x);
    hd = smin(hd, sd_box(bq, vec3f(0.1, 0.06, 0.36)) - 0.05, 0.12);
    var nq = hq - vec3f(-0.47, 0.93, 0.0);
    let e = rot2(-0.2) * nq.xy;
    nq = vec3f(e.x, e.y, nq.z);
    hd = smin(hd, sd_box(nq, vec3f(0.06, 0.3, 0.08)) - 0.05, 0.1);
    hd = smin(hd, sd_box(hq - vec3f(-0.4, 0.28, 0.0), vec3f(0.08, 0.12, 0.27)) - 0.06, 0.12);
    let eq = vec3f(hq.x - 0.02, hq.y - 0.95, abs(hq.z) - 0.44);
    hd = smin(hd, sd_box(eq, vec3f(0.07, 0.36, 0.03)) - 0.03, 0.06);
    let ee = vec3f(hq.x + 0.5, hq.y - 1.07 + bt * hq.z, abs(hq.z) - 0.19);
    hd = max(hd, -(length(ee * vec3f(1.0, 1.5, 1.0)) - 0.13) * 0.7);
    let my = hq.y - 0.47 + mc * hq.z * hq.z * 3.0;
    hd = max(hd, -(sd_box(vec3f(hq.x + 0.5, my, hq.z), vec3f(0.1, 0.018, 0.19)) - 0.012));
    return min(d, hd);
}

fn tree(p: vec3f, c: vec3f) -> vec2f {
    let sx = -sign(c.x);
    let q = p - c;
    let ax = vec3f(sx * 0.45, 3.5, 0.2);
    let hh = clamp(dot(q, ax) / dot(ax, ax), 0.0, 1.0);
    let fl = exp(-max(q.y, 0.0) * 3.0);
    let rr = 0.17 + 0.3 * fl * (0.8 + 0.2 * sin(atan2(q.z, q.x) * 5.0));
    var d = (length(q - ax * hh) - rr) * 0.8;
    let qb = q - ax * 0.6;
    let br = vec3f(sx * 1.0, 0.9, -0.5);
    let hb = clamp(dot(qb, br) / dot(br, br), 0.0, 1.0);
    d = min(d, length(qb - br * hb) - 0.08);
    var m = 1.0;
    let cq = q - vec3f(sx * 0.6, 3.95, 0.1);
    var dc = (length(cq * vec3f(0.8, 1.3, 0.9)) - 1.3) * 0.75;
    if (dc < 0.45) {
        dc += ((noise3(p * 3.2 + vec3f(0.0, time() * 0.25, 0.0)) - 0.5) * 0.6 + (noise3(p * 8.0) - 0.5) * 0.18) * 0.7;
    }
    if (dc < d) { d = dc; m = 2.0; }
    return vec2f(d, m);
}

fn map(p: vec3f) -> f32 {
    let ax = abs(p.x);
    let i = clamp(floor((p.z + 5.6) / 2.8), 0.0, 3.0);
    let zc = -4.2 + 2.8 * i;
    let q = vec3f(ax - 3.7, p.y, p.z - zc);
    let id = i + select(0.0, 4.0, p.x > 0.0);
    var d = sd_box(q - vec3f(0.0, 1.7, 0.0), vec3f(0.85, 1.75, 0.85));
    if (d < 0.25) {
        d = moai(q, id);
        if (d < 0.15) {
            d += (noise3(p * 2.6 + vec3f(id * 5.0)) - 0.5) * 0.13 + (noise3(p * 8.5) - 0.5) * 0.04;
        }
    }
    d = min(d, select(1e5, 1.85 - abs(p.z - zc), abs(p.z) < 5.6));
    MAT = 0;
    SID = id;
    var tr: vec2f;
    if (p.x < 0.0) {
        tr = tree(p, vec3f(-5.1, 0.0, -0.1));
    } else {
        tr = tree(p, vec3f(5.1, 0.0, select(-2.8, 2.8, p.z > 0.0)));
        tr.x = min(tr.x, abs(p.z) + 0.7);
    }
    tr.x = min(tr.x, ax + 2.5);
    if (tr.x < d) { d = tr.x; MAT = i32(tr.y); }
    return d;
}

fn nrm(p: vec3f) -> vec3f {
    let k = vec2f(1.0, -1.0);
    let e = 0.003;
    return normalize(k.xyy * map(p + k.xyy * e) + k.yyx * map(p + k.yyx * e) + k.yxy * map(p + k.yxy * e) + k.xxx * map(p + k.xxx * e));
}

fn soft(p: vec3f, ld: vec3f) -> f32 {
    var s = 1.0;
    var t = 0.05;
    for (var i = 0; i < 14; i = i + 1) {
        let q = p + ld * t;
        if (q.y > 4.5) { break; }
        let d = map(q);
        s = min(s, 8.0 * d / t);
        t += clamp(d, 0.06, 0.6);
        if (s < 0.02) { break; }
    }
    return clamp(s, 0.0, 1.0);
}

fn lit(p: vec3f, n: vec3f, base: vec3f, ao: f32) -> vec3f {
    let ld = sun_dir();
    var s = sun_at(p) * max(dot(n, ld), 0.0);
    if (s > 0.01) { s *= soft(p + n * 0.03, ld); }
    let amb = mix(vec3f(0.10, 0.09, 0.07), vec3f(0.20, 0.19, 0.17), n.y * 0.5 + 0.5) + vec3f(0.04, 0.06, 0.03);
    return base * (SUNC * s + amb * ao * 1.4);
}

fn floor_base(p: vec3f) -> vec3f {
    let row = floor(p.z / 1.4);
    let u = p.x / 1.6 + 0.5 * row;
    let fu = fract(u);
    let fv = fract(p.z / 1.4);
    let edge = min(min(fu, 1.0 - fu) * 1.6, min(fv, 1.0 - fv) * 1.4);
    let hs = hash12(vec2f(floor(u), row));
    var c = vec3f(0.36, 0.34, 0.31) * (0.7 + 0.3 * hs) * (0.8 + 0.4 * noise3(vec3f(p.xz * 4.0, 0.0)));
    let ck = smoothstep(0.02, 0.0, abs(noise3(vec3f(p.xz * 1.6, 5.0)) - 0.5));
    let joint = smoothstep(0.03, 0.0, edge);
    let mn = noise3(p * 9.0);
    let mossc = mix(vec3f(0.08, 0.14, 0.04), vec3f(0.22, 0.32, 0.08), mn);
    c = mix(c, c * 0.35, ck * 0.6);
    c = mix(c, mossc, clamp(joint + ck, 0.0, 1.0) * 0.85);
    let dT = min(length(p.xz - vec2f(-5.1, -0.1)), min(length(p.xz - vec2f(5.1, -2.8)), length(p.xz - vec2f(5.1, 2.8))));
    let g = smoothstep(2.6, 0.6, dT + (noise3(vec3f(p.xz * 2.0, 9.0)) - 0.5) * 1.2);
    c = mix(c, mossc * 1.2, g);
    return c;
}

fn wall(pe: vec3f, rd: vec3f) -> vec3f {
    let onz = abs(pe.z) > abs(pe.x);
    let along = select(pe.z, pe.x, onz);
    let n = select(vec3f(-sign(pe.x), 0.0, 0.0), vec3f(0.0, 0.0, -sign(pe.z)), onz);
    let face = select(select(1.0, 2.0, pe.x > 0.0), select(3.0, 4.0, pe.z > 0.0), onz);
    let row = floor(pe.y / 0.45);
    let u = along / 0.9 + 0.5 * row + hash12(vec2f(row, face)) * 0.3;
    let fu = fract(u);
    let fv = fract(pe.y / 0.45);
    let edge = min(min(fu, 1.0 - fu) * 0.9, min(fv, 1.0 - fv) * 0.45);
    let bh = hash12(vec2f(floor(u), row + face * 17.0));
    let w = vec3f(along, pe.y, face * 3.1);
    var c = vec3f(0.36, 0.33, 0.30) * (0.65 + 0.35 * bh) * (0.6 + 0.7 * fbm3(w * 1.5));
    c *= mix(0.45, 1.0, smoothstep(0.0, 0.025, edge));
    let ck = smoothstep(0.018, 0.0, abs(noise3(w * vec3f(0.9, 0.6, 1.0)) - 0.5));
    c *= 1.0 - 0.6 * ck;
    let mn = noise3(w * 2.2);
    let mossc = mix(vec3f(0.07, 0.13, 0.04), vec3f(0.2, 0.3, 0.08), mn);
    c = mix(c, mossc, smoothstep(1.4, 0.2, pe.y + (mn - 0.5) * 1.5) * 0.85);
    let vine = smoothstep(0.6, 0.7, noise3(vec3f(along * 2.2, pe.y * 0.2, face * 5.0))) * smoothstep(1.2, 3.6, pe.y + mn);
    c = mix(c, mossc * 1.3, vine);
    let s = sun_at(pe) * max(dot(n, sun_dir()), 0.0);
    var col = c * (SUNC * s + vec3f(0.17, 0.155, 0.13));
    let br = smoothstep(0.62, 0.68, noise3(vec3f(along * 0.5, pe.y * 0.7, face * 7.0))) * smoothstep(2.5, 3.4, pe.y);
    let leaf = smoothstep(0.45, 0.6, noise3(rd * 6.0 + vec3f(face)));
    let outside = mix(sky(rd), vec3f(0.22, 0.36, 0.1) * (0.6 + 0.8 * noise3(rd * 18.0)) * 2.2, leaf);
    col = mix(col, outside, br);
    return col;
}

fn ceiling(pe: vec3f, rd: vec3f) -> vec3f {
    let hv = hole(pe.xz);
    var c = vec3f(0.2, 0.18, 0.16) * (0.6 + 0.7 * noise3(vec3f(pe.xz * 2.5, 1.0)));
    let bm = smoothstep(0.4, 0.43, abs(fract(pe.z / 2.0) - 0.5));
    c *= 1.0 - 0.5 * bm;
    c *= vec3f(0.5, 0.46, 0.4) + SUNC * 0.15 * hv;
    let ln = noise3(vec3f(pe.xz * 4.0, 3.0));
    let fringe = smoothstep(0.15, 0.4, hv) * smoothstep(0.4, 0.6, ln);
    c = mix(c, vec3f(0.18, 0.3, 0.08) * (0.7 + ln), fringe);
    let open = smoothstep(0.5, 0.62, hv + (ln - 0.5) * 0.25);
    let lv = smoothstep(0.55, 0.62, noise3(vec3f(rd.xz / max(rd.y, 0.05) * 3.0, time() * 0.1)));
    let skyc = mix(sky(rd) * 1.3, vec3f(0.25, 0.42, 0.1) * 2.0, lv * 0.8);
    return mix(c, skyc, open);
}

fn shafts(ro: vec3f, rd: vec3f, tend: f32, n: i32) -> vec3f {
    let L = min(tend, 16.0);
    let dt = L / f32(n);
    let j = hash13(rd * 913.0 + vec3f(0.3, 0.7, 0.1));
    var acc = 0.0;
    var dust = 0.0;
    let tm = time();
    for (var i = 0; i < 16; i = i + 1) {
        if (i >= n) { break; }
        let p = ro + rd * ((f32(i) + j) * dt);
        if (p.y > 4.5 || p.y < 0.0) { continue; }
        let b = sun_at(p);
        acc += b * dt;
        let m = noise3(p * 16.0 + vec3f(tm * 0.21, -tm * 0.13 + sin(tm * 0.3), tm * 0.17));
        dust += b * smoothstep(0.8, 0.95, m);
    }
    return SUNC * (acc * 0.045 + dust * 0.35);
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let q = quality();
    let tf = plane_y(ro, rd, 0.0);
    let floor_ok = tf >= tmin && tf <= tmax;
    var tend = tmax;
    if (floor_ok) { tend = tf; }
    let sl = box_span(ro, rd, vec3f(-6.0, 0.0, -6.0), vec3f(-2.8, 4.5, 6.0));
    let sr = box_span(ro, rd, vec3f(2.8, 0.0, -6.0), vec3f(6.0, 4.5, 6.0));
    var t0 = 1e5;
    var t1 = -1.0;
    if (sl.x <= sl.y && sl.y > tmin) { t0 = min(t0, sl.x); t1 = max(t1, sl.y); }
    if (sr.x <= sr.y && sr.y > tmin) { t0 = min(t0, sr.x); t1 = max(t1, sr.y); }
    t0 = max(t0, tmin);
    t1 = min(t1, tend);
    var hit = false;
    var t = t0;
    if (t0 < t1) {
        let steps = i32(mix(40.0, 90.0, q));
        for (var i = 0; i < 90; i = i + 1) {
            if (i >= steps) { break; }
            let d = map(ro + rd * t);
            if (d < 0.0015 + 0.001 * t) { hit = true; break; }
            t += d * 0.8;
            if (t > t1) { break; }
        }
    }
    var col = vec3f(0.0);
    var th = horizon_t(tmax);
    if (hit) {
        th = min(t, tmax);
        let p = ro + rd * t;
        let m = MAT;
        let sid = SID;
        let n = nrm(p);
        let a1 = clamp(map(p + n * 0.07) / 0.07, 0.0, 1.0);
        let a2 = clamp(map(p + n * 0.3) / 0.3, 0.0, 1.0);
        let ao = clamp(0.5 * (a1 + a2), 0.12, 1.0) * (0.55 + 0.45 * smoothstep(0.0, 1.5, p.y));
        var base = vec3f(0.0);
        if (m == 0) {
            let nz = noise3(p * 3.0 + vec3f(sid * 2.0));
            let nf = noise3(p * 15.0);
            let hs = hash12(vec2f(sid, 2.0));
            base = mix(vec3f(0.42, 0.40, 0.37), vec3f(0.46, 0.39, 0.32), hs) * (0.6 + 0.5 * nz) * (0.8 + 0.35 * nf);
            let li = smoothstep(0.62, 0.78, noise3(p * 5.0 + vec3f(sid * 3.0, 1.0, 0.0)));
            base = mix(base, vec3f(0.55, 0.47, 0.22), li * 0.5);
            base = mix(base, vec3f(0.14, 0.22, 0.07), smoothstep(0.45, 0.9, n.y) * smoothstep(0.35, 0.65, nz));
        } else if (m == 1) {
            base = vec3f(0.18, 0.13, 0.09) * (0.6 + 0.6 * noise3(vec3f(p.x * 20.0, p.y * 2.0, p.z * 20.0)));
        } else {
            base = mix(vec3f(0.10, 0.22, 0.05), vec3f(0.32, 0.45, 0.12), noise3(p * 6.0));
        }
        col = lit(p, n, base, ao);
        if (m == 2) { col += base * SUNC * 0.25 * sun_at(p); }
    } else if (floor_ok) {
        th = tf;
        let p = ro + rd * tf;
        let base = floor_base(p);
        let ao = clamp(0.25 + 0.75 * map(p + vec3f(0.0, 0.35, 0.0)) / 0.35, 0.2, 1.0);
        col = lit(p, vec3f(0.0, 1.0, 0.0), base, ao);
    } else {
        let pe = ro + rd * th;
        if (pe.y > 4.4) { col = ceiling(pe, rd); } else { col = wall(pe, rd); }
    }
    // birds drifting under the broken roof
    let tm = time();
    for (var k = 0; k < 4; k = k + 1) {
        let fk = f32(k);
        let hb = hash12(vec2f(fk * 3.7, 4.0));
        let dir = select(1.0, -1.0, (k % 2) == 1);
        let a = tm * (0.3 + 0.2 * hb) * dir + fk * 1.7;
        let R = 1.6 + 2.0 * hb;
        let flap = sin(tm * (8.0 + 4.0 * hb) + fk * 2.0);
        let bc = vec3f(cos(a) * R + 0.7 * sin(tm * 0.23 + fk), 3.2 + 0.9 * hb + 0.06 * flap, sin(a) * R - 0.5);
        if (abs(rd.y) < 1e-4) { continue; }
        let tb = (bc.y - ro.y) / rd.y;
        if (tb < tmin || tb > th) { continue; }
        let pt = ro + rd * tb;
        let fw = vec2f(-sin(a), cos(a)) * dir;
        let l = pt.xz - bc.xz;
        let lx = abs(dot(l, vec2f(fw.y, -fw.x)));
        let ly = dot(l, fw);
        let span = 0.5 * (0.6 + 0.4 * flap);
        let wl = ly + 0.3 * lx - 0.05;
        let thk = 0.1 * (1.0 - lx / max(span, 0.05));
        let dw = max(lx - span, abs(wl) - thk);
        let db = length(vec2f(lx * 3.0, ly - 0.02)) - 0.16;
        let cov = smoothstep(0.015, 0.0, min(dw, db * 0.4));
        if (cov > 0.0) {
            let bcol = vec3f(0.06, 0.045, 0.035) + SUNC * 0.1 * sun_at(bc);
            col = mix(col, bcol, cov);
            if (cov > 0.5) { th = tb; }
        }
    }
    col = mix(col, vec3f(0.30, 0.26, 0.19), 1.0 - exp(-th * 0.03));
    col += shafts(ro, rd, th, i32(mix(6.0, 12.0, q)));
    return Hit(tone(col * 1.1), th);
}

shaders.0f7ac7d9f07759197f5ddbd5627f:
// Hall of Obelisks: arched windows onto five eras, each with a black obelisk; a glass floor over the abyss.
struct Era { top: vec3f, hor: vec3f, gnd: vec3f, lc: vec3f, ld: vec3f, gh: f32, fog: f32, oh: f32, hill: f32, cloud: f32 };
var<private> LM: i32;

fn era(id: i32) -> Era {
    var e = Era(vec3f(0.12, 0.13, 0.15), vec3f(0.30, 0.30, 0.32), vec3f(0.09, 0.09, 0.10), vec3f(1.0, 0.55, 0.25), normalize(vec3f(0.3, 0.45, 0.6)), -1.0, 0.045, 11.0, 0.08, 1.0);
    switch id {
        case 0: { e = Era(vec3f(0.50, 0.42, 0.34), vec3f(0.95, 0.70, 0.45), vec3f(0.66, 0.47, 0.28), vec3f(1.0, 0.72, 0.42), normalize(vec3f(0.6, 0.3, 0.45)), -0.6, 0.012, 9.0, 0.04, 0.15); }
        case 1: { e = Era(vec3f(0.30, 0.34, 0.37), vec3f(0.56, 0.59, 0.58), vec3f(0.17, 0.17, 0.13), vec3f(0.75, 0.75, 0.78), normalize(vec3f(-0.5, 0.5, 0.6)), -0.4, 0.06, 7.5, 0.05, 0.9); }
        case 2: { e = Era(vec3f(0.16, 0.30, 0.60), vec3f(0.78, 0.74, 0.62), vec3f(0.48, 0.42, 0.22), vec3f(1.0, 0.82, 0.55), normalize(vec3f(-0.4, 0.22, 0.85)), -1.2, 0.008, 10.0, 0.012, 0.7); }
        case 3: { e = Era(vec3f(0.40, 0.50, 0.66), vec3f(0.80, 0.84, 0.90), vec3f(0.80, 0.85, 0.92), vec3f(1.0, 0.75, 0.55), normalize(vec3f(0.5, 0.1, 0.85)), -0.5, 0.03, 8.0, 0.10, 0.4); }
        default: { }
    }
    return e;
}

fn stone(uv: vec2f) -> vec3f {
    let row = floor(uv.y / 0.5);
    let xx = uv.x / 1.1 + row * 0.5;
    let cell = vec2f(floor(xx), row);
    let f = vec2f(fract(xx), fract(uv.y / 0.5));
    let j = min(min(f.x, 1.0 - f.x) * 2.2, min(f.y, 1.0 - f.y));
    let v = 0.75 + 0.35 * hash12(cell);
    return vec3f(0.085, 0.095, 0.115) * v * mix(0.45, 1.0, smoothstep(0.0, 0.06, j));
}

fn sd_ob(p: vec3f, h: f32, w0: f32, w1: f32) -> f32 {
    let q = max(abs(p.x), abs(p.z));
    let w = mix(w0, w1, clamp(p.y / h, 0.0, 1.0));
    let shaft = max(q - w, max(-p.y, p.y - h));
    let ph = w1 * 1.5;
    let py = p.y - h;
    let pyr = max(q - w1 * (1.0 - py / ph), max(-py, py - ph));
    return min(shaft, pyr) * 0.7;
}

fn lmap(p: vec3f, id: i32, e: Era) -> f32 {
    LM = 0;
    let base = vec3f(0.0, e.gh, 24.0);
    var d = sd_ob(p - base, e.oh, 0.62 - f32(id) * 0.04, 0.36 + f32(id) * 0.01);
    var x = 1e5;
    if (id == 0) {
        for (var i = 0; i < 3; i++) {
            let fi = f32(i);
            let q = p - base - vec3f(-7.0 + fi * 6.5, 0.0, -4.0 + fi * 3.0);
            let hh = 1.2 + fi * 1.3 - fi * fi * 0.5;
            x = min(x, max(length(q.xz) - 0.5, abs(q.y - hh * 0.5) - hh * 0.5));
        }
    } else if (id == 1) {
        x = min(sd_box(p - base - vec3f(-6.0, 1.2, -3.0), vec3f(0.5, 1.2, 0.3)), sd_box(p - base - vec3f(5.0, 0.9, 1.0), vec3f(0.4, 0.9, 0.35)));
    } else if (id == 3) {
        for (var i = 0; i < 2; i++) {
            let fi = f32(i);
            let q = p - base - vec3f(-5.0 + fi * 9.0, 0.0, -5.0 + fi * 2.0);
            x = min(x, max(max(abs(q.x) - 1.2, -q.y), abs(q.z) * 0.85 + q.y * 0.53 - 0.9));
        }
    } else if (id == 4) {
        for (var i = 0; i < 2; i++) {
            let fi = f32(i);
            let q = p - base - vec3f(-9.0 + fi * 17.0, 0.0, 10.0 + fi * 4.0);
            let hh = 15.0 + fi * 4.0;
            x = min(x, max(length(q.xz) - 0.9 + q.y * 0.02, abs(q.y - hh * 0.5) - hh * 0.5));
        }
    }
    if (x < d) { LM = 1; d = x; }
    return d;
}

fn land(id: i32, lo: vec3f, lr: vec3f) -> vec3f {
    let e = era(id);
    let fid = f32(id);
    let tt = time();
    let up = max(lr.y, 0.0);
    var col = mix(e.hor, e.top, pow(up, 0.6));
    let sd = max(dot(lr, e.ld), 0.0);
    col += e.lc * (pow(sd, 6.0) * 0.3 + pow(sd, 300.0) * 1.5);
    if (lr.y > 0.0) {
        let cp = vec2f(lr.x, lr.z) / (lr.y + 0.08);
        let cn = noise3(vec3f(cp * 0.7 + vec2f(tt * 0.06, 0.0), fid * 3.0)) * 0.65 + noise3(vec3f(cp * 1.9 + vec2f(tt * 0.1, 0.0), fid * 3.0 + 1.0)) * 0.35;
        let cm = smoothstep(0.62 - e.cloud * 0.3, 0.85, cn) * (0.35 + 0.6 * e.cloud);
        let ccol = mix(e.hor * 0.72, e.hor * 1.08 + e.lc * 0.12, smoothstep(0.5, 0.9, cn));
        col = mix(col, ccol, cm * smoothstep(0.0, 0.08, lr.y));
    }
    let az = atan2(lr.x, lr.z);
    let el = lr.y / max(length(lr.xz), 1e-3);
    var hh = e.hill * (0.4 + noise3(vec3f(az * 5.0, fid * 7.0, 0.5)));
    if (id == 4) { hh += abs(az) * 0.3; }
    if (el < hh) { col = mix(e.gnd * 0.5, e.hor, 0.55); }
    var tg = 1e5;
    if (lr.y < 0.0) {
        tg = (e.gh - lo.y) / lr.y;
        let gp = lo + lr * tg;
        var g = e.gnd * (0.65 + 0.6 * noise3(vec3f(gp.xz * 0.25, fid)));
        if (id == 0) { g *= 0.85 + 0.15 * sin(gp.x * 0.6 + gp.z * 0.9 + noise3(vec3f(gp.xz * 0.1, 2.0)) * 4.0); }
        if (id == 2) { g *= 0.88 + 0.12 * sin(gp.x * 0.35 + gp.z * 0.2 - tt * 1.8); }
        g *= 0.55 + 0.6 * e.ld.y;
        // the obelisk's long shadow
        let lxz = e.ld.xz;
        let s = dot(vec2f(0.0, 24.0) - gp.xz, lxz) / dot(lxz, lxz);
        let perp = length(gp.xz + lxz * s - vec2f(0.0, 24.0));
        let shd = (1.0 - smoothstep(0.3, 0.8, perp)) * step(0.0, s) * (1.0 - smoothstep(e.oh, e.oh + 1.0, s * e.ld.y));
        g *= 1.0 - 0.55 * shd;
        if (id == 4) { g += vec3f(1.0, 0.5, 0.2) * step(0.985, hash12(floor(gp.xz * 0.7))) * 0.8; }
        col = mix(g, e.hor, 1.0 - exp(-tg * e.fog));
    }
    let sp = box_span(lo, lr, vec3f(-11.0, e.gh - 0.1, 17.0), vec3f(11.0, e.gh + 20.0, 40.0));
    if (sp.x < sp.y && sp.y > 0.0) {
        var t = max(sp.x, 0.0);
        let tend = min(sp.y, tg);
        let n_st = i32(mix(24.0, 48.0, quality()));
        var hit = false;
        for (var i = 0; i < n_st; i++) {
            let d = lmap(lo + lr * t, id, e);
            if (d < 0.01 + t * 0.0015) { hit = true; break; }
            t += d;
            if (t > tend) { break; }
        }
        if (hit) {
            let p = lo + lr * t;
            let m = LM;
            let k = vec2f(1.0, -1.0) * 0.02;
            let n = normalize(k.xyy * lmap(p + k.xyy, id, e) + k.yyx * lmap(p + k.yyx, id, e) + k.yxy * lmap(p + k.yxy, id, e) + k.xxx * lmap(p + k.xxx, id, e));
            let dif = max(dot(n, e.ld), 0.0);
            let rim = pow(1.0 - max(dot(n, -lr), 0.0), 3.0);
            let ry = p.y - e.gh;
            var c = vec3f(0.0);
            if (m == 0) {
                c = vec3f(0.025, 0.025, 0.03) * (e.hor * 1.2 + e.lc * dif * 2.0);
                let hv = normalize(e.ld - lr);
                let glint = 0.6 + 0.4 * sin(tt * 0.7 + fid * 1.7 + ry * 0.3);
                c += e.lc * pow(max(dot(n, hv), 0.0), 30.0) * 0.35 * glint;
                c += e.lc * rim * 0.12 * glint;
                let fc = select(p.x, p.z - 24.0, abs(n.x) > abs(n.z));
                let groove = smoothstep(0.44, 0.49, abs(fract(ry * (0.9 + fid * 0.3)) - 0.5));
                let chan = (1.0 - smoothstep(0.08, 0.13, abs(fc))) * step(1.0, ry) * step(ry, e.oh - 1.0);
                c += e.lc * max(groove * 0.5, chan) * 0.07 * glint;
            } else {
                var base = e.gnd * 0.7;
                if (id == 3) { base = vec3f(0.45, 0.28, 0.14); }
                if (id == 4) { base = vec3f(0.08, 0.06, 0.05); }
                c = base * (e.hor * 0.6 + e.lc * dif * 1.1);
                if (id == 3) { c += vec3f(1.0, 0.55, 0.2) * 0.12 * (0.8 + 0.2 * sin(tt * 7.0)); }
            }
            col = mix(c, e.hor, 1.0 - exp(-t * e.fog));
        }
    }
    // weather on and beyond the glass
    if (id == 4) {
        let rv = vec2f(lo.x * 28.0, lo.y * 1.2 + tt * 7.0);
        let hr = hash12(floor(rv));
        let s = step(0.86, hr) * (1.0 - smoothstep(0.05, 0.2, abs(fract(rv.x) - 0.5))) * fract(rv.y + hr);
        col = mix(col, vec3f(0.55, 0.6, 0.66), s * 0.4);
    }
    if (id == 4 || id == 1) {
        let dv = vec2f(lo.x * 9.0, lo.y * 9.0 + tt * 0.3);
        let hd = hash12(floor(dv));
        let drop = step(0.8, hd) * (1.0 - smoothstep(0.1, 0.25, length(fract(dv) - 0.5)));
        col = mix(col, col * 1.3 + vec3f(0.05), drop * 0.6);
    }
    if (id == 3) {
        let sv = vec2f(lo.x * 10.0 + sin(lo.y * 2.0 + tt) * 0.4, lo.y * 10.0 + tt * 1.2);
        let hs = hash12(floor(sv));
        let fl = step(0.8, hs) * (1.0 - smoothstep(0.08, 0.2, length(fract(sv) - 0.5)));
        col = mix(col, vec3f(0.95, 0.97, 1.0), fl * 0.8);
    }
    if (id == 1) {
        let mn = noise3(vec3f(lo.x * 0.6 + tt * 0.25, lo.y * 1.2, 4.0));
        col = mix(col, e.hor * 1.05, smoothstep(0.4, 0.8, mn) * 0.35);
    }
    return col;
}

fn cmap(p: vec3f) -> f32 {
    let b = vec3f(0.0, 0.85 + 0.08 * sin(time() * 0.6), 0.0);
    var q = p - b;
    let xz = rot2(time() * 0.15) * q.xz;
    q = vec3f(xz.x, q.y, xz.y);
    return sd_ob(q, 2.1, 0.26, 0.17);
}

fn ob_shade(p: vec3f, rd: vec3f) -> vec3f {
    let k = vec2f(1.0, -1.0) * 0.0015;
    let n = normalize(k.xyy * cmap(p + k.xyy) + k.yyx * cmap(p + k.yyx) + k.yxy * cmap(p + k.yxy) + k.xxx * cmap(p + k.xxx));
    let ang = time() * 0.15;
    let b = vec3f(0.0, 0.85 + 0.08 * sin(time() * 0.6), 0.0);
    var q = p - b;
    let qxz = rot2(ang) * q.xz;
    q = vec3f(qxz.x, q.y, qxz.y);
    let nxz = rot2(ang) * n.xz;
    let fc = select(q.x, q.z, abs(nxz.x) > abs(nxz.y));
    let r = reflect(rd, n);
    var env = mix(vec3f(0.02, 0.025, 0.035), vec3f(0.13, 0.15, 0.2), smoothstep(-0.3, 0.7, r.y));
    let sidel = pow(max(abs(r.x), abs(r.z)), 10.0) * smoothstep(-0.15, 0.2, r.y) * (1.0 - smoothstep(0.35, 0.85, r.y));
    env += vec3f(1.0, 0.6, 0.28) * sidel * 0.6;
    let fres = 0.06 + 0.94 * pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    var c = vec3f(0.012, 0.013, 0.017) + env * (0.2 + 0.8 * fres);
    c += vec3f(0.07, 0.09, 0.12) * max(-n.y, 0.0);
    let groove = smoothstep(0.44, 0.49, abs(fract(q.y * 2.2) - 0.5));
    let chan = (1.0 - smoothstep(0.02, 0.035, abs(fc))) * step(0.15, q.y) * step(q.y, 1.9);
    let pulse = exp(-abs(q.y - fract(time() * 0.07) * 2.8) * 2.5);
    c += vec3f(0.5, 0.68, 1.0) * max(groove * 0.6, chan) * (0.04 + 0.5 * pulse) * step(q.y, 2.1);
    return c;
}

fn abyss(pf: vec3f, rd: vec3f) -> vec3f {
    let tx = select(1e5, (select(-2.5, 2.5, rd.x > 0.0) - pf.x) / rd.x, abs(rd.x) > 1e-5);
    let tz = select(1e5, (select(-2.5, 2.5, rd.z > 0.0) - pf.z) / rd.z, abs(rd.z) > 1e-5);
    let ts = min(tx, tz);
    let h = pf + rd * ts;
    let depth = -h.y;
    let lat = select(h.x, h.z, tx < tz);
    var c = stone(vec2f(lat, h.y)) * 2.0 * exp(-depth * 0.22);
    c += vec3f(0.25, 0.3, 0.38) * 0.04 * exp(-depth * 0.3);
    for (var k = 0; k < 4; k++) {
        let ph = fract(f32(k) * 0.25 - time() * 0.03);
        let dk = -0.3 - ph * 9.0;
        let tk = dk / rd.y;
        if (tk < ts) {
            let mp = pf + rd * tk;
            let m = noise3(vec3f(mp.xz * 0.8 + vec2f(time() * 0.05, f32(k) * 3.1), time() * 0.07 + f32(k)));
            let a = smoothstep(0.4, 0.75, m) * sin(PI * ph) * exp(dk * 0.12);
            c = mix(c, vec3f(0.30, 0.35, 0.42), a * 0.45);
        }
    }
    return c;
}

fn floor_col(p: vec3f, rd: vec3f) -> vec3f {
    let m = max(abs(p.x), abs(p.z));
    if (m < 2.5) {
        var c = abyss(p, rd);
        let fp = fract(p.xz / 1.25);
        let bar = min(min(fp.x, 1.0 - fp.x), min(fp.y, 1.0 - fp.y)) * 1.25;
        let fb = min(bar, (2.5 - m) * 0.6);
        let fres = 0.04 + 0.96 * pow(1.0 - abs(rd.y), 5.0);
        c += fres * vec3f(0.10, 0.12, 0.16);
        let fm = 1.0 - smoothstep(0.015, 0.03, fb);
        c = mix(c, vec3f(0.05, 0.045, 0.04) + vec3f(0.12, 0.07, 0.03) * fres, fm);
        return c;
    }
    let f = fract(p.xz / 1.5);
    let cell = floor(p.xz / 1.5);
    let j = min(min(f.x, 1.0 - f.x), min(f.y, 1.0 - f.y));
    var c = vec3f(0.06, 0.066, 0.078) * (0.75 + 0.4 * hash12(cell)) * mix(0.5, 1.0, smoothstep(0.0, 0.025, j));
    let ax = abs(p.x);
    let az = abs(p.z);
    var sp = exp(-(6.0 - ax) * 0.55) * exp(-(az - 3.7) * (az - 3.7) * 0.9);
    sp += exp(-(6.0 - az) * 0.55) * exp(-(ax - 3.7) * (ax - 3.7) * 0.9);
    c += vec3f(0.75, 0.6, 0.45) * sp * 0.09;
    c += vec3f(0.05, 0.07, 0.1) * exp(-(m - 2.5) * 2.0);
    c += vec3f(0.03, 0.035, 0.045) * pow(1.0 - abs(rd.y), 5.0);
    c *= 0.6 + 0.4 * smoothstep(0.0, 0.8, 6.0 - m);
    return c;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    var col = vec3f(0.0);
    var th = horizon_t(tmax);
    var done = false;
    let sp = box_span(ro, rd, vec3f(-0.42, 0.7, -0.42), vec3f(0.42, 3.45, 0.42));
    if (sp.x < sp.y && sp.y > tmin && sp.x < tmax) {
        var t = max(sp.x, tmin);
        let te = min(sp.y, tmax);
        let n_st = i32(mix(28.0, 64.0, quality()));
        for (var i = 0; i < n_st; i++) {
            let d = cmap(ro + rd * t);
            if (d < 0.001) { done = true; break; }
            t += d;
            if (t > te) { break; }
        }
        if (done) { col = ob_shade(ro + rd * t, rd); th = t; }
    }
    if (!done) {
        let tf = plane_y(ro, rd, 0.0);
        if (tf >= tmin && tf <= tmax + 0.01) {
            col = floor_col(ro + rd * tf, rd);
            th = min(tf, horizon_t(tmax));
        } else {
            let pe = ro + rd * th;
            if (pe.y > ROOM_HEIGHT - 0.03) {
                let g = abs(fract(pe.xz / 2.0) - 0.5);
                let beam = smoothstep(0.42, 0.46, max(g.x, g.y));
                col = vec3f(0.025, 0.028, 0.035) * (1.0 - 0.5 * beam) + vec3f(0.04, 0.05, 0.065) * exp(-length(pe.xz) * 0.45);
            } else {
                let ax = abs(pe.x);
                let az = abs(pe.z);
                var O = vec3f(0.0, 0.0, select(1.0, -1.0, pe.z < 0.0));
                var wall = select(2, 0, pe.z < 0.0);
                if (ax > az) { O = vec3f(select(-1.0, 1.0, pe.x > 0.0), 0.0, 0.0); wall = select(3, 1, pe.x > 0.0); }
                let U = vec3f(-O.z, 0.0, O.x);
                let lat = dot(pe, U);
                let side = select(0, 1, lat > 0.0);
                var ids = array<i32, 8>(0, 3, 2, 4, 1, 0, 4, 2);
                let id = ids[wall * 2 + side];
                let lu = lat - select(-3.7, 3.7, lat > 0.0);
                let y = pe.y;
                let dr = max(abs(lu) - 0.8, max(0.5 - y, y - 3.3));
                let dcirc = max(length(vec2f(lu, y - 3.3)) - 0.8, 3.3 - y);
                let dw = min(dr, dcirc);
                let e = era(id);
                if (dw < 0.0) {
                    let lr = vec3f(dot(rd, U), rd.y, dot(rd, O));
                    let lo = vec3f(lu, y, 0.0);
                    var c = land(id, lo, lr) * 0.88 + vec3f(0.02, 0.025, 0.03);
                    let my = abs(fract((y - 0.5) / 0.7 + 0.5) - 0.5) * 0.7;
                    let bar = min(abs(lu), my);
                    let mul = 1.0 - smoothstep(0.012, 0.024, bar);
                    col = mix(c, vec3f(0.02, 0.018, 0.016) + e.lc * 0.08, mul);
                } else {
                    var c = stone(vec2f(lat, y));
                    let jamb = 1.0 - smoothstep(0.0, 0.2, dw);
                    c = mix(c, c * 1.6 + e.lc * 0.18, jamb);
                    c += mix(e.lc, vec3f(0.5, 0.6, 0.75), 0.3) * 0.06 * exp(-dw * 1.3);
                    c *= 0.45 + 0.55 * smoothstep(0.0, 1.2, y);
                    c *= 1.0 - 0.45 * smoothstep(3.6, 4.5, y);
                    col = c;
                }
            }
        }
    }
    // mist rising from the abyss through the glass
    let rdl = max(dot(rd.xz, rd.xz), 1e-5);
    let tc = clamp(-dot(ro.xz, rd.xz) / rdl, tmin, th);
    let pc = ro + rd * tc;
    let rr = dot(pc.xz, pc.xz);
    let dens = exp(-rr * 0.35) * exp(-max(pc.y, 0.0) * 0.6) * (0.5 + 0.7 * noise3(vec3f(pc.xz * 1.2, pc.y * 1.3 - time() * 0.35)));
    col += vec3f(0.22, 0.27, 0.34) * dens * 0.45;
    return Hit(tone(col * 1.5), th);
}

shaders.0b6c5f8347d9d3052a79a576150a:
// Two mirror dodecahedra, one ABOVE (chiral hand A) and one BELOW (hand B, its
// true mirror), reflected across eye level. Vertices are folded in 4D by a
// quasiperiodic golden double rotation, then normalized onto the 3-sphere and
// STEREOGRAPHICALLY projected, so the figure turns inside-out through infinity.
// A 5-fold quasicrystal fills the void; five Hopf-fibration rings link the two
// figures; 23 motes ride a (5,2) torus knot. Heartbeat on param(0).x.

fn h_rot(p: vec2f, a: f32) -> vec2f {
  let c = cos(a); let s = sin(a);
  return vec2f(c * p.x - s * p.y, s * p.x  * p.y);
}

// quasiperiodic Clifford double rotation (planes (x,w),(y,z) in ratio phi)
fn rot4(p: vec4f, t: f32) -> vec4f {
  var q = p;
  let a = t * 0.30;
  let b = t * 0.30 * 1.6180339887;
  var r = h_rot(vec2f(q.x, q.w), a);              q.x = r.x; q.w = r.y;
  r = h_rot(vec2f(q.y, q.z), b);                  q.y = r.x; q.z = r.y;
  r = h_rot(vec2f(q.z, q.w), t * 0.12 + 2.0);     q.z = r.x; q.w = r.y;
  return q;
}

fn quasi(uv: vec2f, t: f32) -> f32 {
  var s = 0.0;
  for (var k: i32 = 0; k < 5; k = k + 1) {
    let ang = PI  ;

  }
  return s;
}

fn h_seg(ro: vec3f, rd: vec3f, a: vec3f, b: vec3f) -> f32 {
  let v = b - a;
  let cc = dot(v, v);
  let w0 = ro - a;
  let bb = dot(rd, v);
  let dd = dot(rd, w0);
  let ee = dot(v, w0);
  let D = max(cc - bb * bb, 1e-6);
  let s = clamp((ee - bb * dd) / D, 0.0, 1.0);
  let ps = a + s * v;
  let t = max(dot(ps - ro, rd), 0.0);
  return length(ro  * rd - ps);
}

fn dfac(w: f32) -> f32 { return 0.35  * smoothstep(-1.0, 1.0, w); }

fn cage(o: vec3f, rd: vec3f, pv: array<vec3f,20>, wd: array<f32,20>, de: array<vec2<i32>,30>, col: vec3f, T: f32) -> vec3f {
  var g = vec3f(0.0);
  for (var e: i32 = 0; e < 30; e = e + 1) {
    let ia = de[e].x; let ib = de[e].y;
    let d = h_seg(o, rd, pv[ia], pv[ib]);
    let df = dfac(0.5 * (wd[ia] + wd[ib]));
    let flow = 0.7 + 0.6 * sin(T * 3.0 + f32(e) * 0.8);
    g += col * df * flow ;   // fatter so it survives low-res
  }
  return g;
}

fn hand(o: vec3f, rd: vec3f, pv: array<vec3f,20>, wd: array<f32,20>, tt: array<vec4<i32>,5>, tint: vec3f) -> vec3f {
  var g = vec3f(0.0);
  let k = 0.00085;
  for (var e: i32 = 0; e < 5; e = e + 1) {
    let q = tt[e];
    let a = pv[q.x]; let b = pv[q.y]; let c = pv[q.z]; let d = pv[q.w];
    let tn = tint * 0.25 ;
    let d0 = h_seg(o,rd,a,b); let d1 = h_seg(o,rd,a,c); let d2 = h_seg(o,rd,a,d);
    let d3 = h_seg(o,rd,b,c); let d4 = h_seg(o,rd,b,d); let d5 = h_seg(o,rd,c,d);
    g += tn * (k + k/(d1*d1+0.0009) + k/(d2*d2+0.0009)
             + k/(d3*d3+0.0009) + k/(d4*d4+0.0009) + k/(d5*d5+0.0009));
  }
  return g;
}

// five linked rings (Hopf-fibration flavored) threading the gap
fn hopf(o: vec3f, rd: vec3f, T: f32) -> vec3f {
  var g = vec3f(0.0);
  let Rc = 2.1; let rr = 1.2;
  for (var j: i32 = 0; j < 5; j = j + 1) {
    let a = f32(j) * TAU / 5.0 + T * 0.05;
    let ca = cos(a); let sa = sin(a);
    let C = vec3f(Rc * ca, 0.0, Rc * sa);
    let n = vec3f(-sa, 1.15, ca);
    let u = normalize(cross(n, vec3f(0.0, 1.0, 0.0)));
    let v = cross(n, u);
    var prev = C + rr * u;
    for (var s: i32 = 1; s <= 14; s = s + 1) {
      let th = f32(s)  * TAU;
      let cur = C + rr * (u * th + v * sin(th));
      let d = h_seg(o, rd, prev, cur);

      prev = cur;
    }
  }
  return g;
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
  let T = time();
  let CY = 2.4;             // mirror plane (eye level)
  let sep = .7;            // vertical gap between the two figures

  var bpm = param(0).x;
  if (bpm < 20.0) { bpm = 72.0; }
  let cyc = 6.0 / bpm;
  let pb = fract(T / cyc);
  let dubPhase = clamp(0.26 / cyc, 0.05, 0.4);
  let beat = exp(-pow(pb / 0.045, 2.0)) + 0.6 * exp(-pow((pb - dubPhase) / 0.05, 2.0));
  // time reverses between lub and dub: a triangle bump (0 at lub, 1 at dub, 0 at
  // cycle end) subtracted from the clock -> rewind in [lub,dub], fast-forward after.
  let bump = select(1.0 - (pb - dubPhase) / (1.0 - dubPhase), pb / dubPhase, pb < dubPhase);
  let Teff = T - 0.6 * cyc * bump;

  let ph = 1.618034; let iv = 0.618034;
  var dv: array<vec3f, 20> = array<vec3f, 20>(
    vec3f(1.0,1.0,1.0), vec3f(1.0,1.0,-1.0), vec3f(1.0,-1.0,1.0), vec3f(1.0,-1.0,-1.0),
    vec3f(-1.0,1.0,1.0), vec3f(-1.0,1.0,-1.0), vec3f(-1.0,-1.0,1.0), vec3f(-1.0,-1.0,-1.0),
    vec3f(0.0,iv,ph), vec3f(iv,ph,0.0), vec3f(ph,0.0,iv),
    vec3f(0.0,iv,-ph), vec3f(iv,-ph,0.0), vec3f(-ph,0.0,iv),
    vec3f(0.0,-iv,ph), vec3f(-iv,ph,0.0), vec3f(ph,0.0,-iv),
    vec3f(0.0,-iv,-ph), vec3f(-iv,-ph,0.0), vec3f(-ph,0.0,-iv)
  );
  var de: array<vec2<i32>, 30> = array<vec2<i32>, 30>(
    vec2<i32>(0,8),vec2<i32>(0,9),vec2<i32>(0,10),vec2<i32>(1,9),vec2<i32>(1,1),
    vec2<i32>(1,16),vec2<i32>(2,1),vec2<i32>(2,12),vec2<i32>(2,14),vec2<i32>(3,2),
    vec2<i32>(3,6),vec2<i32>(3,17),vec2<i32>(4,8),vec2<i32>(4,13),vec2<i32>(4,15),
    vec2<i32>(5,11),vec2<i32>(5,15),vec2<i32>(5,1),vec2<i32>(6,13),vec2<i32>(6,14),
    vec2<i32>(6,18),vec2<i32>(7,17),vec2<i32>(7,18),vec2<i32>(7,1),vec2<i32>(8,4),
    vec2<i32>(9,15),vec2<i32>(1,6),vec2<i32>(11,17),vec2<i32>(12,18),vec2<i32>(13,19)
  );
  // hand A: five tetrahedra (hand B is its mirror, drawn by reflecting the ray)
  var tA: array<vec4<i32>, 5> = array<vec4<i32>, 5>(
    vec4<i32>(0,3,5,6), vec4<i32>(1,8,12,1), vec4<i32>(2,9,13,17), vec4<i32>(4,1,11,8), vec4<i32>(7,14,15,16)
  );

  // fold in 4D -> onto the 3-sphere -> stereographic projection
  let Sproj = 1.15 ;
  var pv: array<vec3f, 20>;
  var wd: array<f32, 20>;
  for (var i: i32 = 0; i < 20; i = i + 1) {
    let r = rot4(vec4f(dv[i], 0.0), Teff);
    let u = normalize(r);
    let den = max(1.0 - u.w, 0.22);           // clamp so infinity stays bounded
    wd[i] = u.w;
    pv[i] = u.xyz ;
  }

  let hue = 0.5 + 0.5 * sin(Teff * 0.25);
  let cageCol = mix(vec3f(0.2, 0.40, 1.05), vec3f(1.05, 0.42, 0.92), hue);
  let warm = vec3f(1.05, 0.40, 0.80);
  let cool = vec3f(0.35, 0.88, 1.3);

  // ABOVE: hand A
  let TOP = vec3f(0.0, CY + sep, 0.0);
  let oa = ro - TOP;
  var glow = cage(oa, rd, pv, wd, de, cageCol, Teff) + hand(oa, rd, pv, wd, tA, warm);

  // BELOW: reflect the ray across y = CY -> the mirror figure (hand B), cooler
  let rob = vec3f(ro.x, 2.0 * CY - ro.y, ro.z);
  let rdb = vec3f(rd.x, -rd.y, rd.z);
  let ob = rob - TOP;
  glow += cage(ob, rdb, pv, wd, de, cageCol * vec3f(0.8,0.85,1.1), Teff) + hand(ob, rdb, pv, wd, tA, cool);

  // (Hopf rings removed — the quality-gate made them flicker; dropping them
  //  also lightens the scene so the edges hold up.)

  // 23 motes on a (5,2) cinquefoil torus knot, around the mirror plane
  let oc = ro ;
  for (var m: i32 = 0; m < 23; m = m + 1) {
    let th = f32(m) * TAU / 23.0  * 0.12;
    let rrk = 3.1 + 0.95 * cos(2.0 * th);
    let pos = vec3f(rrk * cos(5.0 * th), 1.3 * sin(2.0 * th), rrk * sin(5.0 * th));
    let t = max(dot(pos , rd), 0.0);
    let d = length(oc + t * rd - pos);
    let tw = 0.6 + 0.6 * sin(Teff  + f32(m) * .7);
    glow += vec3f(0.85, 0.55, 1.05)  * (0.0010 / (d  + 0.004));
  }

  glow *= 1.0 + 1.0 * beat;

  // void: dark purple + finer 5-fold quasicrystal + beat flash + stars
  var bg = vec3f(0.02, 0.06, 0.030);
  bg += vec3f(0.10, 0.04, 0.26) * smoothstep(0.0, -0.9, rd.y) * 0.30;
  let qc = quasi(rd.xy * 14.0, T * 0.4);        // moire stays on real time (no rewind)
  var fr = 0.5 + 0.5 * sin(qc * 2.2 + T * 0.3);
  fr = fr * fr;
  bg += vec3f(0.16, 0.05, 0.30) * fr * (0.38  * beat);

  let st = hash13(floor(rd ));


  return Hit(tone(bg + glow), horizon_t(tmax));
}

shaders.1a7af80d362180119f66a769ff40:
// Antimemetics Division, restricted lab: a coffee-ringed steel table, lost researchers, diagrams that forget themselves, one calm capybara.
// exemplar v1: pools of light under each tube, glass display boards whose diagrams glow, steam off the coffee, lit haze, a filmic curve.
var<private> FIG: array<vec4f, 4>;
var<private> PFL: array<f32, 6>;
var<private> FL: f32;
var<private> SIP: f32;
var<private> MAT: i32;
var<private> HID: i32;

const CAPY: vec3f = vec3f(2.6, 0.0, 0.8);
const CAPY_YAW: f32 = -0.7;
const LCOL: vec3f = vec3f(0.84, 1.0, 0.88);
const TEAL: vec3f = vec3f(0.25, 0.95, 0.85);
const AMBER: vec3f = vec3f(1.0, 0.62, 0.2);

fn aces(x: vec3f) -> vec3f { return (x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14); }

// filmic curve (ACES fit), a soft vignette round the camera's own axis, and a hair of dither
fn tm(c: vec3f, rd: vec3f) -> vec3f {
    let fw = room.inv_rot_proj * vec4f(0.0, 0.0, 0.5, 1.0);
    let vig = 1.0 - 0.3 * smoothstep(0.97, 0.55, dot(rd, normalize(fw.xyz / fw.w)));
    return clamp(aces(max(c, vec3f(0.0)) * vig) + (hash13(rd * 913.7) - 0.5) / 255.0, vec3f(0.0), vec3f(1.0));
}

// light from the tubes at a point: the nearest panel in each row (they meet evenly half way, so no seam)
fn panel_light(p: vec3f) -> f32 {
    let ix = clamp(round(p.x / 3.2), -1.0, 1.0);
    let i0 = i32(ix + 1.0);
    var l = 0.0;
    for (var r = 0; r < 2; r = r + 1) {
        let c = vec3f(ix * 3.2, 4.45, select(-2.2, 2.2, r == 1));
        let v = c - p;
        let d2 = dot(v, v);
        let cs = v.y * inverseSqrt(d2);
        l += PFL[i0 + r * 3] * (cs * cs * cs * 0.85 + 0.15) * 12.0 / (1.0 + d2 * 0.5);
    }
    return l;
}

fn setup() {
    let t = time();
    var P: array<vec2f, 5>;
    P[0] = vec2f(-1.0 + 0.45 * sin(t * 0.23), 1.3 + 0.15 * sin(t * 0.31));
    P[1] = vec2f(0.9 + 0.5 * sin(t * 0.19 + 1.0), -1.35 + 0.12 * cos(t * 0.27));
    P[2] = vec2f(-2.45 + 0.15 * sin(t * 0.29 + 2.0), -0.3 + 0.6 * sin(t * 0.17 + 0.5));
    P[3] = vec2f(0.75 + 0.3 * sin(t * 0.21 + 3.0), 1.5 + 0.1 * sin(t * 0.37));
    P[4] = CAPY.xz;
    for (var i = 0; i < 4; i = i + 1) {
        let fi = f32(i);
        let ph = t / 3.4 + fi * 0.37;
        let k = floor(ph);
        let fr = ph - k;
        let ta = (i + 1 + i32(hash12(vec2f(k, fi + 0.5)) * 3.99)) % 5;
        let tb = (i + 1 + i32(hash12(vec2f(k + 1.0, fi + 0.5)) * 3.99)) % 5;
        let da = P[ta] - P[i];
        let db = P[tb] - P[i];
        let a0 = atan2(da.x, da.y);
        let a1 = atan2(db.x, db.y);
        var dd = a1 - a0;
        dd = dd - TAU * floor((dd + PI) / TAU);
        let yaw = a0 + dd * smoothstep(0.72, 0.95, fr);
        let arm = smoothstep(0.35, 0.85, sin(t * 0.5 + fi * 2.1));
        FIG[i] = vec4f(P[i], yaw, arm);
    }
    var s = 0.0;
    for (var i = 0; i < 6; i = i + 1) {
        var f = 0.93 + 0.04 * sin(t * 0.8 + f32(i) * 1.7);
        if (i == 4) { f *= 0.3 + 0.7 * smoothstep(0.3, 0.42, noise3(vec3f(t * 1.5, 3.0, 0.0))); }
        PFL[i] = f;
        s += f;
    }
    FL = s / 6.0;
    SIP = smoothstep(0.55, 0.85, sin(t * 0.7) * 0.5 + 0.5);
}

fn cap(p: vec3f, a: vec3f, b: vec3f, r: f32) -> f32 {
    let pa = p - a;
    let ba = b - a;
    let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h) - r;
}

fn sd_ell(p: vec3f, r: vec3f) -> f32 {
    let k0 = length(p / r);
    let k1 = length(p / (r * r));
    return k0 * (k0 - 1.0) / max(k1, 1e-5);
}

fn sdb2(p: vec2f, b: vec2f) -> f32 {
    let q = abs(p) - b;
    return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0);
}

fn ceil_emit(xz: vec2f, blur: f32) -> vec3f {
    let ix = clamp(round(xz.x / 3.2), -1.0, 1.0);
    let south = xz.y > 0.0;
    let c = vec2f(ix * 3.2, select(-2.2, 2.2, south));
    let q = abs(xz - c) - vec2f(0.38, 0.75);
    let d = max(q.x, q.y);
    let m = 1.0 - smoothstep(-blur, blur + 0.01, d);
    let id = i32(ix + 1.0) + select(0, 3, south);
    return LCOL * PFL[id] * m;
}

fn table(p: vec3f) -> vec2f {
    var d = sd_box(p - vec3f(0.0, 0.9, 0.0), vec3f(1.7, 0.02, 0.6)) - 0.008;
    let lp = vec3f(abs(p.x) - 1.55, p.y - 0.44, abs(p.z) - 0.48);
    d = min(d, sd_box(lp, vec3f(0.03, 0.44, 0.03)));
    d = min(d, sd_box(vec3f(abs(p.x) - 1.55, p.y - 0.15, p.z), vec3f(0.02, 0.02, 0.48)));
    var m = 5.0;
    let m1 = p - vec3f(-0.62, 0.98, 0.28);
    let m2 = p - vec3f(1.05, 0.98, -0.32);
    let dm = min(max(length(m1.xz) - 0.045, abs(m1.y) - 0.055), max(length(m2.xz) - 0.045, abs(m2.y) - 0.055));
    if (dm < d) { d = dm; m = 8.0; }
    let sq = p - vec3f(0.25, 0.95, 0.12);
    let sxz = rot2(0.4) * sq.xz;
    let ds = sd_box(vec3f(sxz.x, sq.y, sxz.y), vec3f(0.15, 0.025, 0.2)) - 0.003;
    if (ds < d) { d = ds; m = 10.0; }
    return vec2f(d, m);
}

fn figure(q: vec3f, arm: f32) -> vec2f {
    let y = q.y;
    let lx = vec3f(abs(q.x), q.y, q.z);
    var d = cap(lx, vec3f(0.1, 0.05, 0.0), vec3f(0.1, 0.75, 0.0), 0.07);
    var m = 2.0;
    let rr = mix(0.27, 0.2, clamp((y - 0.5) / 0.9, 0.0, 1.0));
    var dc = max(length(vec2f(q.x, q.z * 1.4)) - rr, max(0.5 - y, y - 1.4)) * 0.7;
    dc = smin(dc, cap(lx, vec3f(0.0, 1.36, 0.0), vec3f(0.19, 1.36, 0.0), 0.085), 0.08);
    dc = min(dc, cap(q, vec3f(-0.23, 1.34, 0.0), vec3f(-0.27, 0.86, 0.06), 0.06));
    let hand = mix(vec3f(0.27, 0.86, 0.06), vec3f(0.13, 1.62, 0.08), arm);
    let elbow = mix(vec3f(0.29, 1.08, 0.0), vec3f(0.33, 1.3, 0.12), arm);
    dc = min(dc, cap(q, vec3f(0.23, 1.34, 0.0), elbow, 0.058));
    dc = min(dc, cap(q, elbow, hand, 0.052));
    if (dc < d) { d = dc; m = 1.0; }
    var ds = cap(q, vec3f(0.0, 1.4, 0.0), vec3f(0.0, 1.55, 0.01), 0.05);
    ds = min(ds, sd_ell(q - vec3f(0.0, 1.645, 0.01), vec3f(0.1, 0.125, 0.11)));
    ds = min(ds, length(q - vec3f(-0.27, 0.82, 0.07)) - 0.045);
    ds = min(ds, length(q - hand - vec3f(0.0, -0.03, 0.0)) - 0.045);
    if (ds < d) { d = ds; m = 3.0; }
    return vec2f(d, m);
}

fn capy_head(q: vec3f) -> vec3f {
    let hq = q - vec3f(0.0, 1.08, 0.08);
    let r = rot2(0.35 * SIP) * hq.yz;
    return vec3f(hq.x, r.x, r.y);
}

fn capy(q: vec3f) -> vec2f {
    var d = max(length(q.xz) - 0.22, abs(q.y - 0.62) - 0.03);
    d = min(d, max(length(q.xz) - 0.03, q.y - 0.62));
    d = min(d, max(abs(length(q.xz) - 0.17) - 0.015, abs(q.y - 0.25) - 0.015));
    var m = 7.0;
    var db = sd_ell(q - vec3f(0.0, 0.9, -0.02), vec3f(0.22, 0.27, 0.26));
    let hq = capy_head(q);
    db = smin(db, sd_ell(hq - vec3f(0.0, 0.16, 0.12), vec3f(0.12, 0.13, 0.2)), 0.07);
    let ex = vec3f(abs(hq.x), hq.y, hq.z);
    db = min(db, length(ex - vec3f(0.08, 0.28, 0.03)) - 0.035);
    let ax = vec3f(abs(q.x), q.y, q.z);
    db = min(db, cap(ax, vec3f(0.12, 0.75, 0.05), vec3f(0.13, 0.67, 0.22), 0.05));
    let mug = mix(vec3f(0.0, 0.98, 0.36), vec3f(0.0, 1.2, 0.42), SIP);
    db = min(db, cap(ax, vec3f(0.1, 0.98, 0.12), vec3f(0.06, mug.y - 0.02, mug.z - 0.04), 0.04));
    if (db < d) { d = db; m = 6.0; }
    let mq = q - mug;
    let dm = max(length(mq.xz) - 0.055, abs(mq.y) - 0.06);
    if (dm < d) { d = dm; m = 9.0; }
    return vec2f(d, m);
}

fn map(p: vec3f) -> f32 {
    let tb = table(p);
    var d = tb.x;
    MAT = i32(tb.y);
    HID = -1;
    let cl = p - CAPY;
    if (length(cl.xz) - 0.6 < d) {
        let l = rot2(CAPY_YAW) * cl.xz;
        let c = capy(vec3f(l.x, cl.y, l.y));
        if (c.x < d) { d = c.x; MAT = i32(c.y); }
    }
    for (var i = 0; i < 4; i = i + 1) {
        let f = FIG[i];
        let rel = p - vec3f(f.x, 0.0, f.y);
        if (length(rel.xz) - 0.42 < d) {
            let l = rot2(f.z) * rel.xz;
            let g = figure(vec3f(l.x, rel.y, l.y), f.w);
            if (g.x < d) { d = g.x; MAT = i32(g.y); HID = i; }
        }
    }
    return d;
}

fn calc_n(p: vec3f) -> vec3f {
    let e = vec2f(0.0015, -0.0015);
    return normalize(e.xyy * map(p + e.xyy) + e.yyx * map(p + e.yyx) + e.yxy * map(p + e.yxy) + e.xxx * map(p + e.xxx));
}

fn fog(c: vec3f, t: f32, rd: vec3f) -> vec3f {
    let hz = mix(vec3f(0.025, 0.032, 0.03), vec3f(0.16, 0.2, 0.17) * FL, smoothstep(-0.3, 0.8, rd.y));
    return mix(c, hz, 1.0 - exp(-t * 0.055));
}

fn tabletop(xz: vec2f, b: vec3f) -> vec3f {
    var c = b * (0.9 + 0.1 * noise3(vec3f(xz.x * 40.0, xz.y * 2.0, 0.0)));
    for (var i = 0; i < 6; i = i + 1) {
        let h = hash33(vec3f(f32(i), 7.0, 3.0));
        let cp = vec2f((h.x - 0.5) * 3.0, (h.y - 0.5) * 1.0);
        let r = length(xz - cp);
        let ring = 1.0 - smoothstep(0.0, 0.012, abs(r - 0.045 - h.z * 0.02));
        c = mix(c, vec3f(0.3, 0.18, 0.08), ring * 0.6 * (0.4 + 0.6 * noise3(vec3f(xz * 30.0, f32(i)))));
    }
    for (var i = 0; i < 7; i = i + 1) {
        let h = hash33(vec3f(f32(i), 2.0, 9.0));
        let cp = vec2f((h.x - 0.5) * 2.9, (h.y - 0.5) * 0.9);
        let q = rot2(h.z * 3.0) * (xz - cp);
        let bq = abs(q) - vec2f(0.105, 0.148);
        if (max(bq.x, bq.y) < 0.0) {
            var pc = vec3f(0.9, 0.9, 0.86);
            let dr = abs(length(q - vec2f(0.0, 0.03)) - 0.05);
            pc = mix(pc, vec3f(0.2, 0.5, 0.5), (1.0 - smoothstep(0.0, 0.004, dr)) * 0.7);
            let dr2 = abs(length(q - vec2f(0.0, 0.03)) - 0.025);
            pc = mix(pc, vec3f(0.7, 0.45, 0.2), (1.0 - smoothstep(0.0, 0.003, dr2)) * 0.6);
            c = pc;
        }
    }
    return c;
}

fn shade_obj(p: vec3f, rd: vec3f, t: f32) -> vec3f {
    let m = MAT;
    let hid = HID;
    let n = calc_n(p);
    let ao = clamp(0.35 + 0.65 * map(p + n * 0.12) / 0.12, 0.3, 1.0);
    var base = vec3f(0.5);
    var spec = 0.04;
    if (m == 1 || m == 2 || m == 3) {
        let f = FIG[max(hid, 0)];
        let rel = p - vec3f(f.x, 0.0, f.y);
        let l = rot2(f.z) * rel.xz;
        let lq = vec3f(l.x, rel.y, l.y);
        let hh = hash12(vec2f(f32(hid) * 3.7, 1.3));
        if (m == 1) {
            base = vec3f(0.86, 0.87, 0.85) * (0.86 + 0.16 * noise3(p * 13.0));
            if (lq.z > 0.0 && abs(lq.x) < 0.01 && lq.y < 1.25) { base *= 0.7; }
            if (lq.z > 0.0 && lq.y > 1.18 && lq.y < 1.42 && abs(lq.x) < (lq.y - 1.18) * 0.45) { base = vec3f(0.42, 0.48, 0.56); }
        } else if (m == 2) {
            base = vec3f(0.11, 0.11, 0.13);
        } else {
            base = mix(vec3f(0.86, 0.66, 0.52), vec3f(0.4, 0.26, 0.18), hh);
            let hair = mix(vec3f(0.08, 0.06, 0.05), vec3f(0.55, 0.53, 0.5), fract(hh * 7.3));
            if (lq.y > 1.56 && (lq.y > 1.69 || lq.z < -0.02)) { base = hair; }
            if (lq.z > 0.06 && length(vec2f(abs(lq.x) - 0.04, lq.y - 1.655)) < 0.022) { base = vec3f(0.04); spec = 0.4; }
        }
    } else if (m == 5) {
        base = vec3f(0.5, 0.53, 0.54);
        spec = 0.5;
        if (n.y > 0.9 && p.y > 0.92) { base = tabletop(p.xz, base); spec = 0.25; }
    } else if (m == 6) {
        let cl = p - CAPY;
        let l = rot2(CAPY_YAW) * cl.xz;
        let hq = capy_head(vec3f(l.x, cl.y, l.y));
        base = vec3f(0.44, 0.29, 0.17) * (0.8 + 0.35 * noise3(p * 30.0));
        if (hq.z > 0.26 && hq.y > 0.0) { base = mix(base, vec3f(0.18, 0.11, 0.07), 0.7); }
        if (length(vec3f(abs(hq.x), hq.y, hq.z) - vec3f(0.1, 0.2, 0.21)) < 0.03) { base = vec3f(0.02); spec = 0.6; }
    } else if (m == 7) {
        base = vec3f(0.15, 0.15, 0.16);
        spec = 0.3;
    } else if (m == 8 || m == 9) {
        base = select(vec3f(0.8, 0.79, 0.75), vec3f(0.3, 0.55, 0.52), m == 9);
        spec = 0.2;
        if (n.y > 0.9) { base = vec3f(0.12, 0.07, 0.04); }
    } else if (m == 10) {
        base = vec3f(0.88, 0.88, 0.84);
    }
    let kd = normalize(vec3f(0.15, 1.0, 0.1));
    let dif = max(dot(n, kd), 0.0);
    let hemi = 0.5 + 0.5 * n.y;
    let pl = panel_light(p);
    var col = base * LCOL * (0.03 + pl * (0.08 + 0.45 * dif) + 0.05 * hemi * FL) * ao;
    let rr = reflect(rd, n);
    if (rr.y > 0.05) {
        let tc = (4.5 - p.y) / rr.y;
        col += ceil_emit((p + rr * tc).xz, 0.15 + tc * 0.06) * spec * ao;
    }
    let fres = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
    // the boards' glow wraps the silhouettes: teal from the long walls, amber from the ends
    col += mix(TEAL, AMBER, smoothstep(-0.5, 0.5, abs(n.x) - abs(n.z))) * fres * 0.16 * ao;
    return fog(col, t, rd);
}

fn lineg(d: f32, w: f32) -> f32 { return exp(-d * d / (w * w)) + 0.3 * exp(-abs(d) * 30.0) + 0.1 * exp(-abs(d) * 7.0); }

fn diagrams(uv: vec2f, id: i32, t: f32) -> vec3f {
    let pi = clamp(floor((uv.x + 1.875) / 1.25), 0.0, 2.0);
    let q = vec2f(uv.x + 1.875 - (pi + 0.5) * 1.25, uv.y);
    let ty = (i32(pi) + id) % 3;
    let seed = f32(id) * 1.37 + pi * 0.71;
    let teal = TEAL;
    let amber = AMBER;
    let w = 0.008;
    var col = vec3f(0.0);
    let r = length(q);
    let a = atan2(q.y, q.x);
    if (ty == 0) {
        let k = clamp(round(r / 0.12), 1.0, 5.0);
        let odd = fract(k * 0.5) > 0.25;
        let dir = select(-1.0, 1.0, odd);
        let g = fract(a / TAU + t * 0.04 * dir * (1.0 + k * 0.3) + seed);
        let on = smoothstep(0.08, 0.13, g);
        let tip = exp(-pow((g - 0.985) * 40.0, 2.0)) * 1.5;
        col += select(teal, amber, odd) * lineg(r - k * 0.12, w) * (on + tip) * step(r, 0.66);
        col += amber * exp(-r * r * 900.0) * (0.6 + 0.4 * sin(t * 2.0));
    } else if (ty == 1) {
        let s = r / 0.075 - a / TAU;
        let d = abs(fract(s) - 0.5) * 0.075;
        let lim = step(r, 0.6) * smoothstep(0.02, 0.05, r);
        col += amber * lineg(d, w) * lim * 0.8;
        let ph = abs(fract(t * 0.06 + seed) * 2.0 - 1.0);
        let pr = 0.06 + ph * 0.5;
        let pa = TAU * fract(pr / 0.075);
        let da = fract((a - pa) / TAU + 0.5) - 0.5;
        col += teal * exp(-da * da * 60.0 - pow((r - pr) / 0.05, 2.0)) * lineg(d, w * 1.8) * lim * 2.5;
    } else {
        let x = q.x;
        let y = q.y;
        let inx = step(-0.5, x) * step(x, 0.55);
        let fa = -0.5 + 1.1 * abs(fract(t * 0.05 + seed) * 2.0 - 1.0);
        let fb = -0.55 + 1.2 * abs(fract(t * 0.043 + seed + 0.5) * 2.0 - 1.0);
        let axx = lineg(y + 0.5, w) * inx * (1.0 - smoothstep(fa - 0.06, fa + 0.06, x));
        let axy = lineg(x + 0.5, w) * step(-0.5, y) * step(y, 0.6) * (1.0 - smoothstep(fb - 0.06, fb + 0.06, y));
        col += vec3f(0.55, 0.7, 0.7) * (axx + axy) * 0.7;
        let ph = x * 7.0 + t * 0.4 + seed;
        let f = 0.2 * sin(ph) + 0.05;
        let fp = 1.4 * cos(ph);
        col += teal * lineg((y - f) / sqrt(1.0 + fp * fp), w) * inx;
        let lq = q - vec2f(0.05, -0.05);
        let A2 = 0.12;
        let r2 = dot(lq, lq);
        let F = r2 * r2 - A2 * (lq.x * lq.x - lq.y * lq.y);
        let gr = vec2f(4.0 * lq.x * r2 - 2.0 * A2 * lq.x, 4.0 * lq.y * r2 + 2.0 * A2 * lq.y);
        col += amber * lineg(F / max(length(gr), 0.02), w) * 0.9;
    }
    let fade = 0.5 + 0.5 * sin(t * 0.25 + seed * 2.0 + q.x * 1.5);
    return col * (0.35 + 0.65 * fade);
}

fn wall_col(pe: vec3f, t: f32) -> vec3f {
    var u = 0.0;
    var wi = 0;
    if (abs(pe.x) > 5.97) {
        wi = select(0, 1, pe.x > 0.0);
        u = pe.z * select(1.0, -1.0, pe.x > 0.0);
    } else {
        wi = select(2, 3, pe.z > 0.0);
        u = pe.x * select(-1.0, 1.0, pe.z > 0.0);
    }
    let y = pe.y;
    let light = 0.035 + panel_light(pe) * 0.42;
    var c = vec3f(0.6, 0.62, 0.6) * (0.92 + 0.08 * noise3(pe * 2.0));
    if (y < 0.12) { c = vec3f(0.17, 0.18, 0.17); }
    c *= LCOL * light;
    let side = select(-1.0, 1.0, u > 0.0);
    let bu = u - side * 3.225;
    let bv = y - 1.65;
    let bq = abs(vec2f(bu, bv)) - vec2f(1.875, 0.7);
    let bd = max(bq.x, bq.y);
    let id = wi * 2 + select(0, 1, u > 0.0);
    if (bd < 0.035) {
        if (bd > 0.0) {
            c = vec3f(0.5, 0.52, 0.54) * light * 1.2;
        } else {
            // dark glass: half-wiped smudges catch the light, the diagrams glow through
            var b = vec3f(0.05, 0.065, 0.065) * light * LCOL;
            let sm = noise3(vec3f(bu * 3.0, bv * 5.0, f32(id) * 3.1));
            b += vec3f(0.05, 0.06, 0.06) * light * smoothstep(0.5, 0.8, sm);
            b += vec3f(0.12, 0.14, 0.13) * light * smoothstep(0.6, 0.0, abs(bv - bu * 0.25 - 0.3)) * 0.5;
            b += diagrams(vec2f(bu, bv), id, t) * 1.7;
            c = b;
        }
    } else {
        c += mix(TEAL, AMBER, f32(id % 2)) * 0.07 * exp(-bd * 4.0);
        if (abs(bv + 0.75) < 0.022 && abs(bu) < 1.6) { c = vec3f(0.35, 0.37, 0.38) * light; }
    }
    c *= 0.6 + 0.4 * smoothstep(0.0, 1.5, 6.0 - abs(u));
    return c;
}

fn floor_col(p: vec3f, rd: vec3f) -> vec3f {
    let g = abs(fract(p.xz / 0.6) - 0.5);
    let grout = smoothstep(0.485, 0.495, max(g.x, g.y));
    var c = vec3f(0.42, 0.44, 0.42) * (0.9 + 0.12 * hash12(floor(p.xz / 0.6)));
    c = mix(c, vec3f(0.25, 0.26, 0.25), grout);
    c *= 0.9 + 0.1 * noise3(vec3f(p.xz * 3.0, 0.0));
    var sh = mix(0.45, 1.0, smoothstep(-0.15, 0.45, sdb2(p.xz, vec2f(1.7, 0.6))));
    for (var i = 0; i < 4; i = i + 1) {
        let dd = length(p.xz - FIG[i].xy);
        sh *= 1.0 - 0.45 * exp(-dd * dd * 10.0);
    }
    let dc = length(p.xz - CAPY.xz);
    sh *= 1.0 - 0.4 * exp(-dc * dc * 12.0);
    var col = c * LCOL * (0.02 + panel_light(p) * 0.4) * sh;
    let rr = reflect(rd, vec3f(0.0, 1.0, 0.0));
    if (rr.y > 0.05) {
        col += ceil_emit((p + rr * (4.5 / rr.y)).xz, 0.3) * 0.2 * sh;
    }
    return col;
}

fn ceil_col(p: vec3f) -> vec3f {
    let g = abs(fract(p.xz / 0.6) - 0.5);
    let grid = smoothstep(0.48, 0.495, max(g.x, g.y));
    var c = vec3f(0.3, 0.31, 0.3) * mix(1.0, 0.6, grid) * (0.03 + panel_light(p - vec3f(0.0, 0.3, 0.0)) * 0.05);
    c += ceil_emit(p.xz, 0.01) * 3.0 + ceil_emit(p.xz, 0.45) * 0.25;
    return c;
}

fn env(ro: vec3f, rd: vec3f, tmax: f32) -> Hit {
    let th = horizon_t(tmax);
    let pe = ro + rd * th;
    if (abs(pe.x) > 6.05 || abs(pe.z) > 6.05 || pe.y < -0.05 || pe.y > 4.55) { return no_hit(); }
    var col = vec3f(0.0);
    if (pe.y < 0.03) { col = floor_col(pe, rd); }
    else if (pe.y > 4.47) { col = ceil_col(pe); }
    else { col = wall_col(pe, time()); }
    return Hit(fog(col, th, rd), th);
}

// steam off a cup: a few jittered samples through a small box over its rim; a wavering, widening plume
// whose density is broken up by rising noise
fn wisp(ro: vec3f, rd: vec3f, tend: f32, rim: vec3f, seed: f32) -> vec4f {
    let sp = box_span(ro, rd, rim + vec3f(-0.14, 0.0, -0.14), rim + vec3f(0.14, 0.5, 0.14));
    let t0 = max(sp.x, 0.0);
    let t1 = min(sp.y, tend);
    if (sp.x > sp.y || t0 >= t1) { return vec4f(0.0, 0.0, 0.0, 1.0); }
    let t = time();
    let ns = select(5, 8, quality() > 0.5);
    let dt = (t1 - t0) / f32(ns);
    var tt = t0 + dt * hash12(rd.xy * 517.0 + seed);
    var T = 1.0;
    var acc = 0.0;
    for (var i = 0; i < ns; i = i + 1) {
        let p = ro + rd * tt - rim;
        let h = max(p.y, 0.0);
        let ax = vec2f(sin(h * 9.0 - t * 1.7 + seed), cos(h * 7.0 - t * 1.3 + seed)) * 0.09 * h;
        let r = length(p.xz - ax);
        let w = 0.022 + h * 0.12;
        var d = exp(-r * r / (w * w)) * smoothstep(0.0, 0.04, h) * (1.0 - smoothstep(0.12, 0.48, h));
        d *= smoothstep(0.3, 0.75, noise3(vec3f(p.x * 13.0, h * 6.0 - t * 1.1, p.z * 13.0 + seed)));
        let a = d * dt * 30.0;
        acc += T * a;
        T *= exp(-a);
        tt += dt;
    }
    let lit = LCOL * (0.05 + panel_light(rim + vec3f(0.0, 0.25, 0.0)) * 0.3);
    return vec4f(lit * acc, T);
}

fn shade(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    setup();
    var h = shade_scene(ro, rd, tmin, tmax);
    if (h.t < 0.0) { return h; }
    var c = h.color;
    // steam off the capybara's cup (it follows the sip) and off the two cups on the table
    let ml = mix(vec3f(0.0, 0.98, 0.36), vec3f(0.0, 1.2, 0.42), SIP);
    let mw = rot2(-CAPY_YAW) * ml.xz;
    let cups = array<vec3f, 3>(CAPY + vec3f(mw.x, ml.y + 0.06, mw.y), vec3f(-0.62, 1.035, 0.28), vec3f(1.05, 1.035, -0.32));
    for (var i = 0; i < 3; i = i + 1) {
        let w = wisp(ro, rd, h.t, cups[i], f32(i) * 7.1);
        c = c * w.w + w.rgb * (1.0 - 0.6 * SIP * f32(i == 0));
    }
    return Hit(tm(c * 1.3, rd), h.t);
}

fn shade_scene(ro: vec3f, rd: vec3f, tmin: f32, tmax: f32) -> Hit {
    let sp = box_span(ro, rd, vec3f(-3.4, 0.0, -2.3), vec3f(3.4, 1.85, 2.3));
    let t0 = max(sp.x, tmin);
    let t1 = min(sp.y, tmax);
    if (sp.x <= sp.y && t0 < t1) {
        let steps = i32(mix(36.0, 80.0, quality()));
        var t = t0;
        var hit = false;
        for (var i = 0; i < steps; i = i + 1) {
            let d = map(ro + rd * t);
            if (d < 0.001 * (1.0 + t)) { hit = true; break; }
            t += d * 0.85;
            if (t > t1) { break; }
        }
        if (hit && t <= t1) {
            return Hit(shade_obj(ro + rd * t, rd, t), t);
        }
    }
    return env(ro, rd, tmax);
}

